/**
 * drawUtils.js
 * Canvas 绘制通用工具。
 */

export function roundRect(ctx, x, y, w, h, r) {
  r = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y,     x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x,     y + h, r);
  ctx.arcTo(x,     y + h, x,     y,     r);
  ctx.arcTo(x,     y,     x + w, y,     r);
  ctx.closePath();
}

export function drawGlowDot(ctx, x, y, radius, innerColor, outerColor, alpha = 1) {
  const g = ctx.createRadialGradient(x, y, 0, x, y, radius);
  g.addColorStop(0, innerColor);
  g.addColorStop(0.4, outerColor);
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

/** 二次贝塞尔采样点（用于导线电流粒子） */
export function quadPoint(a, b, sag, u) {
  const mx = (a.x + b.x) / 2;
  const my = (a.y + b.y) / 2 + sag;
  const m = 1 - u;
  return {
    x: m * m * a.x + 2 * m * u * mx + u * u * b.x,
    y: m * m * a.y + 2 * m * u * my + u * u * b.y
  };
}

/** 计算导线的默认下垂量 */
export function wireSag(a, b) {
  const d = Math.hypot(b.x - a.x, b.y - a.y);
  return Math.min(26, d * 0.14);
}

/** 点到线段的距离 */
export function pointSegmentDist(px, py, ax, ay, bx, by) {
  const dx = bx - ax, dy = by - ay;
  const len2 = dx * dx + dy * dy;
  if (len2 === 0) return Math.hypot(px - ax, py - ay);
  let t = ((px - ax) * dx + (py - ay) * dy) / len2;
  t = Math.max(0, Math.min(1, t));
  const cx = ax + t * dx, cy = ay + t * dy;
  return Math.hypot(px - cx, py - cy);
}

/** 文本测量 + 背景底板（用于读数标签） */
export function drawLabel(ctx, text, x, y, opts = {}) {
  const {
    font = 'bold 11px system-ui',
    color = '#7dd3fc',
    bg = 'rgba(10,14,23,0.75)',
    pad = 4,
    align = 'center'
  } = opts;

  ctx.save();
  ctx.font = font;
  ctx.textAlign = align;
  ctx.textBaseline = 'middle';

  const w = ctx.measureText(text).width;
  let bx = x;
  if (align === 'center') bx = x - w / 2 - pad;
  else if (align === 'right') bx = x - w - pad;

  ctx.fillStyle = bg;
  roundRect(ctx, bx, y - 9, w + pad * 2, 18, 5);
  ctx.fill();

  ctx.fillStyle = color;
  ctx.fillText(text, x, y + 0.5);
  ctx.restore();
}