/**
 * CircuitSolver.js
 * 电路物理内核 —— 真正的 Modified Nodal Analysis (MNA)。
 *
 * 核心设计：
 *   1. 由 CircuitGraph 构建电气节点（导线并查集）
 *   2. 由元件 netlist 收集支路
 *   3. 按电气连通分量拆分，每个分量独立 MNA
 *   4. 每个分量选一个接地参考节点（不使用 1e-12 假对地电导）
 *   5. 理想电压源作为 MNA 独立约束进入矩阵（支路电流为附加未知量）
 *   6. 实际电源 = 理想电压源 E + 串联内阻 r（r 直接进入约束方程对角）
 *   7. 电容器采用后向欧拉伴随模型
 *   8. 非线性元件（灯泡）使用不动点迭代
 *
 * 支持的支路类型（由 Component.netlist() 返回）：
 *   { kind:'resistor',  a, b, R }
 *   { kind:'vsource',   a, b, E, r }        a = 正极，b = 负极
 *   { kind:'capacitor', a, b, C, Vprev }
 *   { kind:'open' }                          显式断路（跳过 stamp）
 *
 * 求解结果：
 *   {
 *     ok: boolean,
 *     errors: string[],
 *     nodeVoltage: Float64Array,           // 全局节点电压
 *     comp: Map<compId, {I,V,P,extra}>     // 元件端电流/电压/功率
 *   }
 */

import { solveLinear } from './linalg.js';
import { UnionFind } from './UnionFind.js';

export class CircuitSolver {

  /**
   * @param {import('./CircuitGraph.js').CircuitGraph} graph
   */
  constructor(graph) {
    this.graph = graph;
    this._lastResult = null;
  }

  /**
   * 求解电路
   * @param {object} model  PhysicalModel.get()
   * @param {number} dt     时间步长（秒），用于电容伴随模型
   * @returns {object} 求解结果
   */
  solve(model, dt = 1 / 60) {
    const graph = this.graph;
    const comps = graph.allComponents;

    const errors = [];

    /* ---------- 0. 空电路 ---------- */
    if (comps.length === 0) {
      return this._emptyResult();
    }

    /* ---------- 1. 电气节点 ---------- */
    const nodes = graph.buildNodes();
    const N = nodes.nodeCount;
    const nodeOf = nodes.nodeOf;

    if (N === 0) return this._emptyResult();

    /* ---------- 2. 收集所有支路 ---------- */
    /** @type {Array<object>} */
    const branches = [];

    for (const c of comps) {
      if (c.burnedOut) continue;   // 烧毁元件视为断路

      let nl;
      try {
        nl = c.netlist(model, dt);
      } catch (e) {
        errors.push(`${c.label} 网表生成失败: ${e.message}`);
        continue;
      }
      if (!nl || !nl.length) continue;

      for (const b of nl) {
        if (!b || b.kind === 'open') continue;
        const na = nodeOf(c.id, b.a);
        const nb = nodeOf(c.id, b.b);
        branches.push({ ...b, comp: c, na, nb });
      }
    }

    /* ---------- 3. 按电气节点拆分连通分量 ---------- */
    const nuf = new UnionFind();
    for (let i = 0; i < N; i++) nuf.add(i);
    for (const b of branches) nuf.union(b.na, b.nb);

    /** @type {Map<number, {nodes:number[], branches:object[]}>} */
    const groups = new Map();
    for (let i = 0; i < N; i++) {
      const r = nuf.find(i);
      if (!groups.has(r)) groups.set(r, { nodes: [], branches: [] });
      groups.get(r).nodes.push(i);
    }
    for (const b of branches) {
      const r = nuf.find(b.na);
      groups.get(r)?.branches.push(b);
    }

    /* ---------- 4. 逐分量求解 ---------- */
    const nodeVoltage = new Float64Array(N);

    for (const [, grp] of groups) {
      if (grp.branches.length === 0) continue;   // 孤立节点 → 电压 0
      this._solveComponent(grp, nodeVoltage, model, dt, errors);
    }

    /* ---------- 5. 元件端量汇总 ---------- */
    const compData = new Map();
    for (const c of comps) {
      compData.set(c.id, { I: 0, V: 0, P: 0, extra: {} });
    }

    for (const b of branches) {
      const c = b.comp;
      const va = nodeVoltage[b.na];
      const vb = nodeVoltage[b.nb];
      const data = compData.get(c.id);
      if (!data) continue;

      switch (b.kind) {
        case 'resistor': {
          const R = Math.max(b.R, 1e-9);
          const I = (va - vb) / R;
          // 多支路元件（滑动变阻器）以第一条为主
          if (data._primary === undefined) {
            data._primary = true;
            data.I = I;
            data.V = va - vb;
          }
          break;
        }
        case 'vsource': {
          const I = b._ik ?? 0;
          if (data._primary === undefined) {
            data._primary = true;
            data.I = I;
            data.V = va - vb;
          }
          data.extra.emf = b.E;
          break;
        }
        case 'capacitor': {
          const g = b.C / Math.max(dt, 1e-9);
          const I = g * ((va - vb) - b.Vprev);
          if (data._primary === undefined) {
            data._primary = true;
            data.I = I;
            data.V = va - vb;
          }
          data.extra.C = b.C;
          data.extra.Vc = va - vb;
          break;
        }
      }
    }

    /* ---------- 6. 电压表读数（理想电压表不参与 stamp） ---------- */
    for (const c of comps) {
      if (c.type !== 'voltmeter') continue;
      const data = compData.get(c.id);
      if (!data) continue;
      const na = nodeOf(c.id, 0);
      const nb = nodeOf(c.id, 1);
      data.V = nodeVoltage[na] - nodeVoltage[nb];
      if (data._primary === undefined) data.I = 0;
    }

    /* ---------- 7. 功率 ---------- */
    for (const [, data] of compData) {
      data.P = Math.abs(data.I * data.V);
      if (!Number.isFinite(data.P)) data.P = 0;
      if (!Number.isFinite(data.I)) data.I = 0;
      if (!Number.isFinite(data.V)) data.V = 0;
      delete data._primary;
    }

    const result = {
      ok: errors.length === 0,
      errors,
      nodeVoltage,
      nodeCount: N,
      comp: compData
    };

    this._lastResult = result;
    return result;
  }

  /**
   * 求解单个电气连通分量
   * @private
   */
  _solveComponent(grp, nodeVoltage, model, dt, errors) {
    const { nodes: nodeList, branches } = grp;
    const k = nodeList.length;

    // 局部节点索引
    const localOf = new Map();
    nodeList.forEach((n, i) => localOf.set(n, i));

    // 电压源未知量分配
    const vsIndex = new Map();
    let vsCount = 0;
    for (const b of branches) {
      if (b.kind === 'vsource') {
        vsIndex.set(b, k - 1 + vsCount);
        vsCount++;
      }
    }

    const size = (k - 1) + vsCount;
    if (size <= 0) return;

    /* ---- 矩阵分配 ---- */
    const A = new Array(size);
    for (let i = 0; i < size; i++) A[i] = new Float64Array(size);
    const z = new Float64Array(size);

    const idx = (node) => localOf.get(node) - 1;   // 局部 0 为接地，返回 -1

    /* ---- stamp 辅助 ---- */
    const addG = (a, b, g) => {
      if (!Number.isFinite(g) || g === 0) return;
      const i = idx(a), j = idx(b);
      if (i >= 0) A[i][i] += g;
      if (j >= 0) A[j][j] += g;
      if (i >= 0 && j >= 0) { A[i][j] -= g; A[j][i] -= g; }
    };

    const addI = (a, b, I) => {
      if (!Number.isFinite(I) || I === 0) return;
      const i = idx(a), j = idx(b);
      if (i >= 0) z[i] -= I;
      if (j >= 0) z[j] += I;
    };

    /* ---- 逐支路 stamp ---- */
    for (const b of branches) {
      switch (b.kind) {

        case 'resistor': {
          const R = Math.max(b.R, 1e-9);
          addG(b.na, b.nb, 1 / R);
          break;
        }

        case 'vsource': {
          // 未知量 i_k 定义为电源内部从 b(负极) 流向 a(正极) 的电流
          // KCL:  节点 a 得到 -i_k；节点 b 得到 +i_k
          // 约束: V_a - V_b + i_k * r = E
          const vi = vsIndex.get(b);
          const ip = idx(b.na);
          const iN = idx(b.nb);

          if (ip >= 0) A[ip][vi] -= 1;
          if (iN >= 0) A[iN][vi] += 1;

          if (ip >= 0) A[vi][ip] += 1;
          if (iN >= 0) A[vi][iN] -= 1;

          A[vi][vi] += Math.max(b.r ?? 0, 0);
          z[vi] += b.E;
          break;
        }

        case 'capacitor': {
          // 后向欧拉伴随模型
          // I_C = g*(V_a - V_b) - g*V_prev,  g = C/dt
          const g = b.C / Math.max(dt, 1e-9);
          addG(b.na, b.nb, g);
          addI(b.na, b.nb, -g * b.Vprev);
          break;
        }

        default:
          break;
      }
    }

    /* ---- 求解 ---- */
    const x = solveLinear(A, z);

    /* ---- 回写节点电压 ---- */
    for (let li = 1; li < k; li++) {
      const globalNode = nodeList[li];
      const v = x[li - 1];
      nodeVoltage[globalNode] = Number.isFinite(v) ? v : 0;
    }
    // 接地节点
    nodeVoltage[nodeList[0]] = 0;

    /* ---- 回写电压源支路电流 ---- */
    for (const b of branches) {
      if (b.kind === 'vsource') {
        const vi = vsIndex.get(b);
        const ik = x[vi];
        b._ik = Number.isFinite(ik) ? ik : 0;
      }
    }
  }

  _emptyResult() {
    return {
      ok: true,
      errors: [],
      nodeVoltage: new Float64Array(0),
      nodeCount: 0,
      comp: new Map()
    };
  }
}
