/**
 * DragController.js
 * 处理元件拖动与滑动变阻器滑片拖动。
 */

export class DragController {
  /**
   * @param {import('../core/CircuitGraph.js').CircuitGraph} graph
   */
  constructor(graph) {
    this.graph = graph;
    this.drag = null;   // { type:'component'|'slider', comp, ox, oy }
  }

  startComponentDrag(c, x, y) {
    this.drag = { type: 'component', comp: c, ox: x - c.x, oy: y - c.y };
  }

  startSliderDrag(c) {
    this.drag = { type: 'slider', comp: c };
  }

  move(x, y, bounds) {
    if (!this.drag) return false;
    const d = this.drag;

    if (d.type === 'component') {
      const c = d.comp;
      let nx = x - d.ox;
      let ny = y - d.oy;
      if (bounds) {
        nx = Math.max(bounds.left, Math.min(bounds.right, nx));
        ny = Math.max(bounds.top,  Math.min(bounds.bottom, ny));
      }
      c.x = nx;
      c.y = ny;
      return true;
    }

    if (d.type === 'slider') {
      const c = d.comp;
      const w = 96;
      const rel = (x - (c.x - w / 2 + 6)) / (w - 12);
      c.slider = Math.max(0, Math.min(1, rel));
      return true;
    }

    return false;
  }

  end() {
    const had = !!this.drag;
    this.drag = null;
    return had;
  }

  get active() { return !!this.drag; }
}