/**
 * Switch.js —— 单刀单掷开关
 */

import { Component, nextComponentId } from './Component.js';

export class Switch extends Component {
  static type = 'switch';
  static displayName = '开关';
  static icon = '⏻';
  static category = 'control';
  static PARAM_KEYS = ['closed'];

  constructor(id) {
    super(id ?? nextComponentId('sw'));
    this.closed = false;
  }

  netlist(model) {
    if (this.burnedOut) return [{ kind: 'open' }];
    if (!this.closed) return [{ kind: 'open' }];
    return [{
      kind: 'resistor',
      a: 0, b: 1,
      R: Math.max(model.numeric.switchR, 1e-6)
    }];
  }

  getProps() {
    return [
      { key: 'closed', label: '通断状态', type: 'bool' }
    ];
  }

  toggle() { this.closed = !this.closed; }

  update(dt) { this.coolOverload(dt); }
}