/**
 * AppState.js
 * 极简可观察状态容器。UI 层订阅变化，避免全局变量散落。
 */

export class AppState {
  #state;
  #listeners = new Map();

  constructor(initial = {}) {
    this.#state = { ...initial };
  }

  get(key) {
    return this.#state[key];
  }

  set(key, value) {
    const old = this.#state[key];
    if (old === value) return;
    this.#state[key] = value;
    this.emit('change:' + key, value, old);
    this.emit('change', key, value, old);
  }

  patch(obj) {
    for (const k of Object.keys(obj)) this.set(k, obj[k]);
  }

  snapshot() {
    return { ...this.#state };
  }

  on(evt, fn) {
    if (!this.#listeners.has(evt)) this.#listeners.set(evt, new Set());
    this.#listeners.get(evt).add(fn);
    return () => this.off(evt, fn);
  }

  off(evt, fn) {
    this.#listeners.get(evt)?.delete(fn);
  }

  emit(evt, ...args) {
    const set = this.#listeners.get(evt);
    if (!set) return;
    for (const fn of [...set]) {
      try { fn(...args); }
      catch (e) { console.error('[AppState] listener error on', evt, e); }
    }
  }
}