/**
 * MetalWire.js —— 金属丝（待测电阻率用）
 *
 * 内部持有一个"真实阻值"（由隐藏的长度/直径/电阻率计算）。
 * 学生用刻度尺与螺旋测微器"测量"得到 L 和 d，
 * 再用伏安法测得 R，最后计算 ρ。
 */

import { Resistor } from './Resistor.js';
import { nextComponentId } from './Component.js';

export class MetalWire extends Resistor {
  static type = 'metalWire';
  static displayName = '金属丝';
  static icon = '〰';
  static category = 'passive';

  constructor(id) {
    super(id ?? nextComponentId('mw'));

    /* 隐藏真实参数（不暴露给 UI） */
    this.hiddenLength   = 0.60;     // m
    this.hiddenDiameter = 0.40e-3;  // m
    this.hiddenRho      = 1.10e-6;  // Ω·m (类似镍铬合金)

    /* 由真实参数反推真实阻值 */
    const S = Math.PI * this.hiddenDiameter ** 2 / 4;
    this.hiddenR = this.hiddenRho * this.hiddenLength / S;

    this.R = this.hiddenR;
    this.isUnknown = true;
    this.isTarget = true;
  }

  /** 学生不可直接编辑参数 */
  getProps() { return []; }

  netlist(model) {
    this.R = this.hiddenR;
    return super.netlist(model);
  }

  /** 供实验层读取真实值（仅用于结果对照，界面不直接展示） */
  get truth() {
    return {
      L: this.hiddenLength,
      d: this.hiddenDiameter,
      rho: this.hiddenRho,
      R: this.hiddenR
    };
  }
}