/**
 * Bulb.js —— 小灯泡
 *
 * 教学型非线性模型：
 *   热态电阻 R_hot  = U_rated² / P_rated
 *   冷态电阻 R_cold ≈ R_hot / 10
 *   当前电阻随"相对功率"非线性变化，并用一阶滞后模拟热惯性。
 *
 * 未通电时电阻趋于 R_cold；达到额定功率时接近 R_hot。
 * 因此 U-I 曲线呈上凸（非线性）。
 */

import { Component, nextComponentId } from './Component.js';
import { clamp } from '../core/Units.js';

const COLD_RATIO = 0.1;     // R_cold / R_hot
const COLD_TEMP  = 0.05;    // 初始"温度"（无量纲 0..1.2）
const HEAT_RATE  = 2.4;     // 加热时间常数 (1/s)
const COOL_RATE  = 0.8;     // 冷却时间常数 (1/s)

export class Bulb extends Component {
  static type = 'bulb';
  static displayName = '小灯泡';
  static icon = '💡';
  static category = 'passive';
  static PARAM_KEYS = ['Urated', 'Prated'];

  constructor(id) {
    super(id ?? nextComponentId('bul'));
    this.Urated = 3.8;      // 额定电压 (V)
    this.Prated = 0.75;     // 额定功率 (W)
    this.temperature = COLD_TEMP;   // 归一化温度 0..1.2
    this.brightness = 0;    // 显示用亮度 0..1.5
  }

  /** 热态（额定）电阻 */
  get Rhot() {
    return (this.Urated * this.Urated) / Math.max(this.Prated, 1e-6);
  }

  /** 冷态电阻 */
  get Rcold() {
    return this.Rhot * COLD_RATIO;
  }

  /** 当前电阻 */
  get R() {
    const t = clamp(this.temperature, 0, 1.2);
    return this.Rcold + (this.Rhot - this.Rcold) * t;
  }

  netlist() {
    if (this.burnedOut) return [{ kind: 'open' }];
    return [{
      kind: 'resistor',
      a: 0, b: 1,
      R: Math.max(this.R, 0.01)
    }];
  }

  getProps() {
    return [
      { key: 'Urated', label: '额定电压', unit: 'V', min: 0.5, max: 24, step: 0.1 },
      { key: 'Prated', label: '额定功率', unit: 'W', min: 0.05, max: 20, step: 0.05 }
    ];
  }

  update(dt, model) {
    this.coolOverload(dt);
    if (this.burnedOut) { this.brightness = 0; return; }

    // 加热/冷却一阶滞后
    const Pn = clamp(this.P / Math.max(this.Prated, 1e-6), 0, 2.2);
    const Ttarget = clamp(Math.pow(Pn, 0.42), 0, 1.2);

    if (model?.bulbModel === 'linear') {
      // 线性模型：直接趋近于稳态，几乎无热惯性
      this.temperature += (Ttarget - this.temperature) * clamp(dt * 20, 0, 1);
    } else {
      const rate = (Ttarget > this.temperature) ? HEAT_RATE : COOL_RATE;
      this.temperature += (Ttarget - this.temperature) * clamp(dt * rate, 0, 1);
    }

    // 亮度：近似正比于 P/Prated 的幂函数
    this.brightness = clamp(Math.pow(this.P / Math.max(this.Prated, 1e-6), 0.7), 0, 1.6);
  }
}