/**
 * VoltmeterResistance.js
 * 实验 6：伏阻法测电阻（双电压表 + 电阻箱）
 *
 * 电路：
 *   E+ ── S ── n1 ─[Rx]─ n2 ─[电阻箱 R0]─ n3 ── E-
 *                │        │                  │
 *               [V1]     [V2]               (回线)
 *
 * 原理：
 *   Rx 与电阻箱 R0 串联 → 电流相同 I
 *   Ux = I·Rx,  U0 = I·R0
 *   →  Rx = R0 · Ux / U0
 */

import { register } from './ExperimentRegistry.js';
import { ExperimentValidator } from './ExperimentValidator.js';
import { SchematicRenderer } from '../rendering/SchematicRenderer.js';
import { TopologyAnalyzer } from '../core/TopologyAnalyzer.js';

/* ------------------------------------------------------------------
   标准电路图
   ------------------------------------------------------------------ */

function buildSchematic() {
  const T = SchematicRenderer.terminalPos;

  const E  = { id: 'sch-E',  type: 'battery',       x:  80, y: 220, rot: 90, label: 'E' };
  const S  = { id: 'sch-S',  type: 'switch',        x: 180, y:  80, rot: 0,  label: 'S' };
  const Rx = { id: 'sch-Rx', type: 'resistor',      x: 300, y:  80, rot: 0,  label: 'Rx', value: '?' };
  const R0 = { id: 'sch-R0', type: 'resistanceBox', x: 430, y:  80, rot: 0,  label: 'R0', value: '电阻箱' };
  const V1 = { id: 'sch-V1', type: 'voltmeter',     x: 300, y: 230, rot: 0,  label: 'V1' };
  const V2 = { id: 'sch-V2', type: 'voltmeter',     x: 430, y: 230, rot: 0,  label: 'V2' };

  const els = [E, S, Rx, R0, V1, V2];
  const P = (e, ti) => T(e, ti);
  const w = (id, pts) => ({ id, pts });

  const wires = [
    /* 主回路 */
    w('w1', [ P(E,0), { x: 80, y: 80 }, P(S,0) ]),
    w('w2', [ P(S,1), P(Rx,0) ]),                // n1
    w('w3', [ P(Rx,1), P(R0,0) ]),               // n2
    w('w4', [ P(R0,1), { x: 560, y: 80 },
              { x: 560, y: 420 }, { x: 80, y: 420 }, P(E,1) ]),

    /* V1 并接 Rx */
    w('w5', [ P(Rx,0), P(V1,0) ]),
    w('w6', [ P(Rx,1), P(V1,1) ]),

    /* V2 并接 R0 */
    w('w7', [ P(R0,0), P(V2,0) ]),
    w('w8', [ P(R0,1), P(V2,1) ])
  ];

  return { width: 620, height: 460, elements: els, wires };
}

const FIELDS = [
  { key: 'n',  label: '次数',              digits: 0 },
  { key: 'Ux', label: 'Ux',  unit: 'V',   digits: 4 },
  { key: 'U0', label: 'U0',  unit: 'V',   digits: 4 },
  { key: 'R0', label: 'R0',  unit: 'Ω',   digits: 2 },
  { key: 'Rx', label: 'Rx = R0·Ux/U0', unit: 'Ω', digits: 4 }
];

const VoltmeterResistance = {
  id: 'voltmeter-method',
  name: '伏阻法测电阻',
  category: '实验设计',

  purpose:
    '在只有电压表和电阻箱的条件下测量未知电阻 Rx；' +
    '理解串联电路电流相等的特点；' +
    '掌握用电压比例法求电阻的方法。',

  principle:
    'Rx 与电阻箱 R0 串联，通过它们的电流 I 相同。' +
    'Ux = I·Rx，U0 = I·R0。' +
    '两式相除得 Rx / R0 = Ux / U0，' +
    '因此 Rx = R0 · Ux / U0。' +
    '改变电阻箱的示数 R0，可以测量多组数据。',

  equipment: [
    { type: 'battery',         count: 1, label: '电源 E' },
    { type: 'switch',          count: 1, label: '开关 S' },
    { type: 'resistanceBox',   count: 1, label: '电阻箱 R0' },
    { type: 'unknownResistor', count: 1, label: '待测电阻 Rx' },
    { type: 'voltmeter',       count: 2, label: '电压表 V1、V2' }
  ],

  schematic: buildSchematic(),

  defaultSetup: [
    { type: 'battery',         x: 0.12, y: 0.35 },
    { type: 'switch',          x: 0.32, y: 0.18 },
    { type: 'unknownResistor', x: 0.50, y: 0.18 },
    { type: 'resistanceBox',   x: 0.72, y: 0.18 },
    { type: 'voltmeter',       x: 0.50, y: 0.68 },
    { type: 'voltmeter',       x: 0.72, y: 0.68 }
  ],

  fields: FIELDS,

  /* ---------- 校验 ---------- */
  validate({ topo }) {
    const checks = [];

    checks.push(ExperimentValidator.checkCount(topo, 'battery',         1, '电源'));
    checks.push(ExperimentValidator.checkCount(topo, 'switch',          1, '开关'));
    checks.push(ExperimentValidator.checkCount(topo, 'resistanceBox',   1, '电阻箱 R0'));
    checks.push(ExperimentValidator.checkCount(topo, 'unknownResistor', 1, '待测电阻 Rx'));
    checks.push(ExperimentValidator.checkCount(topo, 'voltmeter',       2, '两个电压表'));

    /* Rx 与 R0 串联 */
    const Rx = topo.comps.find(c => c.type === 'unknownResistor');
    const R0 = topo.comps.find(c => c.type === 'resistanceBox');
    if (Rx && R0) {
      const ok = ExperimentValidator.isSeries(topo, Rx, R0);
      checks.push({
        name: 'Rx 与 R0 串联',
        ok,
        msg: ok ? '待测电阻与电阻箱已串联' : 'Rx 与 R0 应串联连接'
      });
    }

    /* 两表分别并接 Rx、R0 */
    const volts = topo.comps.filter(c => c.type === 'voltmeter' && !c.burnedOut);
    if (volts.length >= 2 && Rx && R0) {
      const vForRx = volts.find(v => topo.inParallel(v, Rx));
      const vForR0 = volts.find(v => topo.inParallel(v, R0));
      checks.push({
        name: 'V1 并接 Rx',
        ok: !!vForRx,
        msg: vForRx ? '其中一个电压表已并联在 Rx 两端' : '一个电压表应并联在 Rx 两端'
      });
      checks.push({
        name: 'V2 并接 R0',
        ok: !!vForR0,
        msg: vForR0 ? '另一个电压表已并联在 R0 两端' : '另一个电压表应并联在 R0 两端'
      });
    } else if (volts.length < 2) {
      checks.push({
        name: '两个电压表',
        ok: false,
        msg: '本实验需要两个电压表'
      });
    }

    checks.push(ExperimentValidator.checkClosedLoop(topo));

    return { checks };
  },

  /* ---------- 数据采集 ---------- */
  makeRow(ctx) {
    const { graph, model, index } = ctx;

    const Rx  = graph.allComponents.find(c => c.type === 'unknownResistor' && !c.burnedOut);
    const R0c = graph.allComponents.find(c => c.type === 'resistanceBox'   && !c.burnedOut);
    if (!Rx || !R0c) return null;

    const volts = graph.allComponents.filter(c => c.type === 'voltmeter' && !c.burnedOut);
    if (volts.length < 2) return null;

    const topo = new TopologyAnalyzer(graph).analyze(model);
    const vForRx = volts.find(v => topo.inParallel(v, Rx));
    const vForR0 = volts.find(v => topo.inParallel(v, R0c));

    if (!vForRx || !vForR0) return null;

    const Ux = Math.abs(vForRx.V);
    const U0 = Math.abs(vForR0.V);

    if (Ux < 1e-6 || U0 < 1e-6) return null;

    const R0 = R0c.R;
    const RxCalc = R0 * Ux / U0;

    return {
      n:  index + 1,
      Ux: +Ux.toFixed(5),
      U0: +U0.toFixed(5),
      R0: +R0.toFixed(3),
      Rx: +RxCalc.toFixed(5)
    };
  },

  /* ---------- 实时读数 ---------- */
  collectLiveData({ graph, model }) {
    const items = [];

    const Rx  = graph.allComponents.find(c => c.type === 'unknownResistor' && !c.burnedOut);
    const R0c = graph.allComponents.find(c => c.type === 'resistanceBox'   && !c.burnedOut);

    if (R0c) {
      items.push({
        k: '电阻箱 R0',
        v: `${R0c.R.toFixed(0)} Ω`,
        cls: 'warn'
      });
    }

    const volts = graph.allComponents.filter(c => c.type === 'voltmeter' && !c.burnedOut);
    const sorted = volts.slice().sort((a, b) => a.x - b.x);

    sorted.forEach((v, i) => {
      items.push({
        k: `电压表 V${i + 1}`,
        v: `${Math.abs(v.V).toFixed(4)} V`,
        cls: v.overRange ? 'danger' : 'purple'
      });
    });

    return items;
  },

  charts: [
    {
      key: 'ratio',
      title: 'Rx 随测量次数的分布',
      xField: 'n',
      yField: 'Rx',
      xLabel: '次数 n',
      yLabel: 'Rx / Ω',
      mode: 'both',
      fit: false
    }
  ],

  interpret() {
    return {
      title: '实验结论',
      lines: [
        '原理：串联电路电流相同，Rx = R0 · Ux / U0。',
        '改变电阻箱示数 R0，可得到多组 (Ux, U0) 数据。',
        'Rx 的真实值不会直接显示，需要通过数据自行计算。'
      ]
    };
  }
};

register(VoltmeterResistance);

export default VoltmeterResistance;