/**
 * main.js
 * 应用入口 —— 装配所有模块，驱动主循环。
 *
 * 关键集成：
 *   1. 右侧面板拆成两块独立 DOM：
 *        #propertyPanel  参数编辑（独立刷新，输入框不丢焦）
 *        #panelBody      状态/故障（每 120ms 重绘）
 *   2. 实验模式（ExperimentMode）通过 window.CircuitLab 桥接
 *   3. 主循环里自动推动实验自动采样（RC 等）
 */

/* ================================================================
   1. 模块导入
   ================================================================ */

import { CircuitGraph }    from './core/CircuitGraph.js';
import { CircuitSolver }   from './core/CircuitSolver.js';
import { PhysicalModel }   from './core/PhysicalModel.js';
import { AppState }        from './core/AppState.js';

import { createComponent, componentFromData } from './components/registry.js';
import { bumpIdCounter, currentIdCounter }    from './components/Component.js';

import { CircuitCanvas }   from './rendering/CircuitCanvas.js';

import { SelectionController } from './interaction/SelectionController.js';
import { WireController }      from './interaction/WireController.js';
import { DragController }      from './interaction/DragController.js';

import { FaultSystem }     from './faults/FaultSystem.js';

import { UIManager }       from './ui/UIManager.js';
import { PalettePanel }    from './ui/PalettePanel.js';
import { PropertyPanel }   from './ui/PropertyPanel.js';
import { ModalManager }    from './ui/ModalManager.js';

/* 实验模式（内部会 import OhmResistance 等实验定义，触发注册） */
import { ExperimentMode }  from './experiments/ExperimentMode.js';

/* ================================================================
   2. 核心实例
   ================================================================ */

const graph  = new CircuitGraph();
const solver = new CircuitSolver(graph);

const state = new AppState({
  mode: 'free',         // 'free' | 'experiment'
  running: false,
  paused: false,
  classroom: false,
  simTime: 0
});

const canvasEl = document.getElementById('cv');
const stageEl  = document.getElementById('stage');

const renderer = new CircuitCanvas(canvasEl, stageEl);

/* ================================================================
   3. 右侧面板骨架（在 #panel 内部拆两块）
   ================================================================ */

const panelRoot = document.getElementById('panel');
panelRoot.innerHTML = '';

const propertyHost = document.createElement('div');
propertyHost.id = 'propertyPanel';
panelRoot.appendChild(propertyHost);

const panelBody = document.createElement('div');
panelBody.id = 'panelBody';
panelRoot.appendChild(panelBody);

/* ================================================================
   4. UI 模块
   ================================================================ */

const ui    = new UIManager();
const modal = new ModalManager();

/* 关键：把 UIManager 的目标从 #panel 重定向到 #panelBody，
   避免覆盖 #propertyPanel 里的输入框 */
ui.panel = panelBody;

const faults = new FaultSystem();

const selection = new SelectionController(graph, () => {
  refreshPropertyPanel();
  refreshMainPanel();

  const sel = selection.selection;
  if (sel?.kind === 'component') {
    ExperimentMode.current?.highlightSchematicFor?.(sel.obj);
  }
  // 通知实验面板刷新「器材参数」Tab
  ExperimentMode.current?.onSelectionChange?.();
});
const wires = new WireController(graph, selection);
const drag  = new DragController(graph);

const palettePanel = new PalettePanel(
  document.getElementById('palette'),
  (type) => addComponentAtCenter(type)
);

const propertyPanel = new PropertyPanel(propertyHost);

/* ================================================================
   5. 参数变更钩子
   ================================================================ */

const propHooks = {
  onChange: () => {
    if (state.get('running')) tickPhysics(1 / 60);
    refreshMainPanel();
  },
  onReset: () => {
    if (state.get('running')) tickPhysics(1 / 60);
    refreshMainPanel();
  }
};

/* ================================================================
   6. 增删元件
   ================================================================ */

function addComponentAtCenter(type) {
  const c = createComponent(type);
  if (!c) return;

  const n = graph.components.size;
  const cx = renderer.W / 2 + ((n % 5) - 2) * 46;
  const cy = renderer.H / 2 + (Math.floor(n / 5) % 4 - 1.5) * 72;

  c.x = Math.max(110, Math.min(renderer.W - 110, cx));
  c.y = Math.max(80,  Math.min(renderer.H - 80, cy));

  graph.addComponent(c);
  selection.selectComponent(c);
  pushHistory();
  ui.setStatus('已添加 ' + c.label, 'ok');
}

function removeSelected() {
  const sel = selection.selection;
  if (!sel) return;

  if (sel.kind === 'component') {
    graph.removeComponent(sel.obj.id);
    selection.clear();
    pushHistory();
    ui.setStatus('已删除元件', 'ok');
  } else if (sel.kind === 'wire') {
    graph.removeWire(sel.obj.id);
    selection.clear();
    pushHistory();
    ui.setStatus('已删除导线', 'ok');
  }
}

/* ================================================================
   7. 撤销 / 重做
   ================================================================ */

const history = {
  stack: [],
  idx: -1,

  push(snapshot) {
    if (this.stack[this.idx] === snapshot) return;
    this.stack = this.stack.slice(0, this.idx + 1);
    this.stack.push(snapshot);
    if (this.stack.length > 80) this.stack.shift();
    this.idx = this.stack.length - 1;
  },

  canUndo() { return this.idx > 0; },
  canRedo() { return this.idx < this.stack.length - 1; },

  undo() {
    if (!this.canUndo()) return false;
    this.idx--;
    this._restore(this.stack[this.idx]);
    return true;
  },

  redo() {
    if (!this.canRedo()) return false;
    this.idx++;
    this._restore(this.stack[this.idx]);
    return true;
  },

  _restore(snap) {
    const data = JSON.parse(snap);
    graph.clear();
    for (const cd of data.components) {
      const c = componentFromData(cd);
      if (c) graph.components.set(c.id, c);
    }
    graph.wires = (data.wires || []).map((w, i) => ({
      id: 'w' + (i + 1),
      a: { ...w.a },
      b: { ...w.b },
      current: 0,
      selected: false
    }));
    graph.invalidateNodes();
    selection.clear();
    refreshMainPanel();
    refreshPropertyPanel();
  }
};

function snapshot() {
  return JSON.stringify({
    components: graph.allComponents.map(c => c.serialize()),
    wires: graph.wires.map(w => ({ a: { ...w.a }, b: { ...w.b } }))
  });
}

function pushHistory() {
  history.push(snapshot());
}

/* ================================================================
   8. 物理仿真
   ================================================================ */

function tickPhysics(dt) {
  const model = PhysicalModel.get();

  // 1) 求解电路
  const result = solver.solve(model, dt);

  // 2) 写回元件
  for (const c of graph.allComponents) {
    const d = result.comp.get(c.id);
    if (d) {
      c.I = d.I;
      c.V = d.V;
      c.P = d.P;
    } else {
      c.I = 0; c.V = 0; c.P = 0;
    }
  }

  // 3) 导线电流（保守估算）
  computeWireCurrents();

  // 4) 元件状态更新
  for (const c of graph.allComponents) {
    c.update(dt, model);
  }

  // 5) 故障检测
  faults.update(graph, model, dt, true);

  state.set('simTime', state.get('simTime') + dt);
}

/**
 * 导线电流估算 —— 保守策略，不伪造理想导线电流。
 */
function computeWireCurrents() {
  for (const w of graph.wires) {
    const a = graph.getComponent(w.a.cid);
    const b = graph.getComponent(w.b.cid);
    if (!a || !b) { w.current = 0; continue; }

    const Ia = a.I || 0;
    const Ib = b.I || 0;

    if (Math.abs(Ia - Ib) < Math.max(1e-3, Math.abs(Ia) * 0.15)) {
      w.current = (Ia + Ib) / 2;
    } else if (a.type === 'battery' || b.type === 'battery') {
      w.current = Math.abs(Ia) > Math.abs(Ib) ? Ia : Ib;
    } else {
      w.current = 0;
    }
  }
}

/* ================================================================
   9. 自由模式电路检查
   ================================================================ */

function checkCircuit() {
  const model = PhysicalModel.get();
  const comps = graph.allComponents;
  const issues = [];

  if (comps.length === 0) {
    return {
      ok: false,
      issues: [{ level: 'info', title: '实验台是空的', detail: '请先从左侧器材库添加元件' }]
    };
  }

  const sources = comps.filter(c => c.type === 'battery' && !c.burnedOut);
  if (sources.length === 0) {
    issues.push({ level: 'danger', title: '电路中没有电源', detail: '请添加一个电源' });
  }

  for (const c of comps) {
    if (c.type === 'battery') continue;
    let connected = 0;
    for (let i = 0; i < c.terminals.length; i++) {
      if (graph.isConnected(c.id, i)) connected++;
    }
    if (connected === 0) {
      issues.push({
        level: 'warn',
        title: `${c.label} 未接线`,
        detail: '该元件没有连接任何导线'
      });
    }
  }

    /* 所有可以当作"负载"的元件类型（含电阻箱 / 待测电阻 / 金属丝） */
  const LOAD_TYPES = [
    'resistor',
    'resistanceBox',
    'unknownResistor',
    'metalWire',
    'bulb',
    'rheostat'
  ];
  const loads = comps.filter(c => LOAD_TYPES.includes(c.type) && !c.burnedOut);
  if (sources.length > 0 && loads.length === 0) {
    issues.push({
      level: 'warn',
      title: '电路中没有负载元件',
      detail: '请添加电阻箱、定值电阻、小灯泡或滑动变阻器'
    });
  }

  if (state.get('running')) {
    for (const s of sources) {
      if (Math.abs(s.I) > model.maxCurrent * 0.5) {
        issues.push({
          level: 'danger',
          title: '⚡ 电路存在短路',
          detail: `电源电流高达 ${Math.abs(s.I).toFixed(2)} A`
        });
      }
    }
  }

  const ok = issues.filter(i => i.level === 'danger').length === 0;
  return { ok, issues };
}

/* ================================================================
   10. 面板刷新
   ================================================================ */

let _checkResult = null;

function refreshMainPanel() {
  ui.renderPanel({
    graph,
    running: state.get('running'),
    selection: selection.selection,
    faults: faults.faults,
    checkResult: _checkResult,
    model: PhysicalModel.get()
  });
}

function refreshPropertyPanel() {
  const sel = selection.selection;
  const c = sel?.kind === 'component' ? sel.obj : null;
  propertyPanel.render(c, PhysicalModel.get(), propHooks);
}

/* ================================================================
   11. 画布交互
   ================================================================ */

function canvasPos(e) {
  const r = canvasEl.getBoundingClientRect();
  return { x: e.clientX - r.left, y: e.clientY - r.top };
}

canvasEl.addEventListener('pointerdown', (e) => {
  const { x, y } = canvasPos(e);
  canvasEl.setPointerCapture(e.pointerId);
  if (e.button === 2) return;

  const t = selection.hitTerminal(x, y, 16);
  if (t) { wires.start(t.cid, t.ti); return; }

  const sl = selection.hitSlider(x, y);
  if (sl) {
    drag.startSliderDrag(sl);
    selection.selectComponent(sl);
    return;
  }

  const c = selection.hitComponent(x, y);
  if (c) {
    drag.startComponentDrag(c, x, y);
    selection.selectComponent(c);
    return;
  }

  const w = selection.hitWire(x, y);
  if (w) { selection.selectWire(w); return; }

  selection.clear();
});

canvasEl.addEventListener('pointermove', (e) => {
  const { x, y } = canvasPos(e);

  if (wires.draft) {
    const t = selection.hitTerminal(x, y, 16);
    wires.move(x, y, t);
    return;
  }

  if (drag.active) {
    const changed = drag.move(x, y, {
      left: 60, right: renderer.W - 60,
      top: 50,  bottom: renderer.H - 50
    });
    if (changed) {
      if (drag.drag?.type === 'slider' && state.get('running')) {
        tickPhysics(1 / 60);
      }
      refreshPropertyPanel();
      refreshMainPanel();
    }
    return;
  }

  if (selection.hitTerminal(x, y, 16))    canvasEl.style.cursor = 'crosshair';
  else if (selection.hitSlider(x, y))     canvasEl.style.cursor = 'ew-resize';
  else if (selection.hitComponent(x, y))  canvasEl.style.cursor = 'move';
  else if (selection.hitWire(x, y))       canvasEl.style.cursor = 'pointer';
  else                                    canvasEl.style.cursor = 'default';
});

canvasEl.addEventListener('pointerup', (e) => {
  const { x, y } = canvasPos(e);

  if (wires.draft) {
    const t = selection.hitTerminal(x, y, 16);
    const w = wires.end(t);
    if (w) {
      pushHistory();
      ui.setStatus('已连接导线', 'ok');
    }
  }

  if (drag.active) {
    const wasDrag = drag.drag;
    drag.end();
    if (wasDrag && wasDrag.type === 'component') pushHistory();
  }
});

canvasEl.addEventListener('pointercancel', () => {
  wires.cancel();
  drag.end();
});

let _lastClick = 0;

canvasEl.addEventListener('click', (e) => {
  const { x, y } = canvasPos(e);
  const now = performance.now();

  const c = selection.hitComponent(x, y);
  if (!c) return;

  if (now - _lastClick < 320) {
    graph.removeComponent(c.id);
    selection.clear();
    pushHistory();
    ui.setStatus('已删除 ' + c.label, 'ok');
    _lastClick = 0;
    return;
  }
  _lastClick = now;

  if (c.type === 'switch' || c.type === 'spdt') {
    c.toggle();
    if (state.get('running')) tickPhysics(1 / 60);
    refreshMainPanel();
    refreshPropertyPanel();
  }
});

canvasEl.addEventListener('contextmenu', (e) => {
  e.preventDefault();
  const { x, y } = canvasPos(e);

  const w = selection.hitWire(x, y);
  if (w) {
    graph.removeWire(w.id);
    selection.clear();
    pushHistory();
    ui.setStatus('已删除导线', 'ok');
    return;
  }

  const c = selection.hitComponent(x, y);
  if (c) {
    graph.removeComponent(c.id);
    selection.clear();
    pushHistory();
    ui.setStatus('已删除 ' + c.label, 'ok');
  }
});

/* ================================================================
   12. 顶栏 / 底栏绑定
   ================================================================ */

function bindTopbar() {
  /* 物理模型下拉 */
  const sel = document.getElementById('modelSelect');
  if (sel) {
    sel.innerHTML = '';
    for (const m of PhysicalModel.list()) {
      const o = document.createElement('option');
      o.value = m.id;
      o.textContent = m.name;
      sel.appendChild(o);
    }
    sel.value = PhysicalModel.current;

    sel.addEventListener('change', () => {
      PhysicalModel.set(sel.value);
      if (state.get('running')) tickPhysics(1 / 60);
      refreshMainPanel();
      refreshPropertyPanel();
      ui.setStatus('已切换到 ' + PhysicalModel.get().name, 'ok');
    });
  }

  /* 模式切换 —— 只更新 state，UI 布局由 ExperimentMode 处理 */
  document.querySelectorAll('.tab[data-mode]').forEach(t => {
    t.addEventListener('click', () => {
      document.querySelectorAll('.tab[data-mode]').forEach(x => x.classList.remove('active'));
      t.classList.add('active');
      const mode = t.dataset.mode;
      state.set('mode', mode);
    });
  });

  /* 课堂模式（全屏） */
  document.getElementById('btnClassroom')?.addEventListener('click', async (e) => {
    const on = !state.get('classroom');
    state.set('classroom', on);
    document.body.classList.toggle('classroom', on);
    e.currentTarget.classList.toggle('active', on);

    try {
      if (on && !document.fullscreenElement) {
        await document.documentElement.requestFullscreen();
      } else if (!on && document.fullscreenElement) {
        await document.exitFullscreen();
      }
    } catch (err) {
      console.warn('全屏切换失败:', err);
    }

    // 全屏后画布需要重新测量尺寸
    setTimeout(() => renderer.resize(), 150);
  });

  /* 用户按 ESC 退出全屏时，同步按钮与样式状态 */
  document.addEventListener('fullscreenchange', () => {
    if (!document.fullscreenElement && state.get('classroom')) {
      state.set('classroom', false);
      document.body.classList.remove('classroom');
      document.getElementById('btnClassroom')?.classList.remove('active');
      setTimeout(() => renderer.resize(), 150);
    }
  });

  /* 帮助 */
  document.getElementById('btnHelp')?.addEventListener('click', () => {
    modal.open({ title: '⚡ 使用说明', html: ui.help() });
  });
}

function bindToolbar() {

  /* 检查电路 —— 按模式分流 */
  document.getElementById('btnCheck')?.addEventListener('click', () => {
    const mode = state.get('mode');
    if (mode === 'experiment' && ExperimentMode.current?.currentDef) {
      _checkResult = ExperimentMode.current.checkCurrent();
    } else {
      _checkResult = checkCircuit();
    }
    refreshMainPanel();
    if (_checkResult.ok) ui.setStatus('✅ 电路检查通过', 'ok');
    else                 ui.setStatus('⚠ 发现问题，请查看右侧提示', 'err');
  });

  /* 通电 / 断电 */
  document.getElementById('btnRun')?.addEventListener('click', () => {
    const running = state.get('running');

    if (running) {
      state.set('running', false);
      state.set('paused', false);
      for (const w of graph.wires) w.current = 0;
      for (const c of graph.allComponents) {
        c.I = 0; c.V = 0; c.P = 0;
        if (c.type === 'bulb') c.brightness = 0;
      }
      faults.faults = [];
      ui.setRunning(false);
      ui.setStatus('已断电', 'warn');
      refreshMainPanel();
      ExperimentMode.current?.onRunStateChange?.(false);
      return;
    }

    // 通电前检查
    const mode = state.get('mode');
    _checkResult = (mode === 'experiment' && ExperimentMode.current?.currentDef)
      ? ExperimentMode.current.checkCurrent()
      : checkCircuit();

    const fatal = (_checkResult.issues || []).filter(i => i.level === 'danger');
    if (fatal.length > 0) {
      ui.setStatus('⚠ 电路存在严重问题，无法通电', 'err');
      refreshMainPanel();
      return;
    }

    state.set('running', true);
    state.set('paused', false);
    state.set('simTime', 0);
    ui.setRunning(true);
    ui.setStatus('⚡ 电路已通电，正在实时计算', 'ok');
    tickPhysics(1 / 60);
    refreshMainPanel();
    ExperimentMode.current?.onRunStateChange?.(true);
  });

  /* 暂停 */
  document.getElementById('btnPause')?.addEventListener('click', () => {
    const paused = !state.get('paused');
    state.set('paused', paused);
    ui.setPaused(paused);
    ui.setStatus(paused ? '已暂停' : '继续运行', paused ? 'warn' : 'ok');
  });

  /* 撤销 / 重做 */
  document.getElementById('btnUndo')?.addEventListener('click', () => {
    if (history.undo()) ui.setStatus('已撤销', 'ok');
    else ui.setStatus('没有可撤销的操作', 'warn');
  });

  document.getElementById('btnRedo')?.addEventListener('click', () => {
    if (history.redo()) ui.setStatus('已重做', 'ok');
    else ui.setStatus('没有可重做的操作', 'warn');
  });

  /* 清空 */
  document.getElementById('btnClear')?.addEventListener('click', () => {
    if (graph.components.size === 0) return;
    if (!confirm('确定清空实验台上的所有元件和导线吗？')) return;
    graph.clear();
    selection.clear();
    state.set('running', false);
    state.set('paused', false);
    faults.faults = [];
    _checkResult = null;
    ui.setRunning(false);
    pushHistory();
    ui.setStatus('已清空实验台', 'ok');
    refreshMainPanel();
    refreshPropertyPanel();
  });

  /* 键盘快捷键 */
  window.addEventListener('keydown', (e) => {
    const tag = e.target?.tagName;
    if (tag === 'INPUT' || tag === 'SELECT' || tag === 'TEXTAREA') return;

    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'z') {
      e.preventDefault();
      if (e.shiftKey) history.redo(); else history.undo();
      return;
    }
    if (e.key === 'Delete' || e.key === 'Backspace') {
      e.preventDefault();
      removeSelected();
    }
    if (e.key === ' ' && state.get('running')) {
      e.preventDefault();
      const paused = !state.get('paused');
      state.set('paused', paused);
      ui.setPaused(paused);
    }
  });
}

/* ================================================================
   13. 主循环
   ================================================================ */

let _lastFrame = 0;
let _panelThrottle = 0;

function loop(now) {
  requestAnimationFrame(loop);

  if (!_lastFrame) _lastFrame = now;
  let dt = (now - _lastFrame) / 1000;
  _lastFrame = now;
  dt = Math.max(0.001, Math.min(0.08, dt));

  // 电流粒子相位
  renderer.current.step(dt);

  // 物理步进
  const running = state.get('running') && !state.get('paused');
  if (running) {
    tickPhysics(dt);
    // 实验模式：自动采样（RC 充放电等）
    ExperimentMode.current?.tick?.(dt, state.get('simTime'));
  }

  // 渲染
  renderer.render({
    graph,
    selection: selection.selection,
    running: state.get('running'),
    wireDraft: wires.draft,
    hoverTerminal: wires.hoverTerminal,
    mouse: wires.mouse
  });

  // 面板节流刷新（120 ms）
  if (state.get('running') && now - _panelThrottle > 120) {
    _panelThrottle = now;
    refreshMainPanel();
    refreshPropertyPanel();
  }
}

/* ================================================================
   14. 初始演示 + 桥接 + 装配
   ================================================================ */

function seedDemo() {
  const bat = createComponent('battery');
  bat.x = renderer.W * 0.28;
  bat.y = renderer.H * 0.36;
  graph.addComponent(bat);

  const sw = createComponent('switch');
  sw.x = renderer.W * 0.62;
  sw.y = renderer.H * 0.36;
  graph.addComponent(sw);

  const bulb = createComponent('bulb');
  bulb.x = renderer.W * 0.62;
  bulb.y = renderer.H * 0.68;
  graph.addComponent(bulb);
}

/**
 * 把内部引用桥接给 ExperimentMode
 */
function installBridge() {
  window.CircuitLab = {
    /* 核心 */
    graph, solver, state, renderer, selection, wires, drag,
    faults, PhysicalModel,

    /* UI */
    ui, modal, propertyPanel,

    /* 内部钩子（供 ExperimentMode 使用） */
    __propertyPanel: propertyPanel,
    __propHooks: propHooks,

    /* 公开方法 */
    addComponentAtCenter,
    tickPhysics,
    checkCircuit,
    pushHistory,
    refreshMainPanel,
    refreshPropertyPanel,

    /* 重建器材库（实验模式切回自由模式时调用） */
    __rebuildPalette: () => palettePanel.render(),

    /* 组件工厂 */
    createComponent,
    componentFromData,
    bumpIdCounter,
    currentIdCounter
  };
}

function init() {
  bindTopbar();
  bindToolbar();

  seedDemo();

  pushHistory();
  refreshMainPanel();
  refreshPropertyPanel();

  /* 桥接 + 安装实验模式 */
  installBridge();
  ExperimentMode.install(window.CircuitLab);
  window.CircuitLab.__expMode = ExperimentMode.current;

  ui.setStatus('欢迎！拖动端子连接导线，然后点击「通电」', 'ok');

  requestAnimationFrame(loop);
}

init();
