/**
 * ExperimentValidator.js
 * 实验级校验 —— 判断学生的电路是否满足"当前实验要求"。
 *
 * 与 CircuitChecker 的区别：
 *   CircuitChecker     —— 电路在电学上能不能跑（自由模式用）
 *   ExperimentValidator—— 电路是否符合某个实验的接法（实验模式用）
 *
 * 校验基于电气拓扑，而非坐标。
 */

export class ExperimentValidator {

  /**
   * @param {object} def         实验定义
   * @param {import('../core/CircuitGraph.js').CircuitGraph} graph
   * @param {object} model       PhysicalModel.get()
   * @param {import('../core/TopologyAnalyzer.js').TopologyAnalyzer} topo
   * @returns {{ pass:boolean, checks:Array<{name:string,ok:boolean,msg:string}> }}
   */
  static validate(def, graph, model, topo) {
    const checks = [];

    if (typeof def.validate === 'function') {
      const res = def.validate({ graph, model, topo });
      if (res && Array.isArray(res.checks)) {
        checks.push(...res.checks);
      }
    }

    const pass = checks.length > 0 && checks.every(c => c.ok);
    return { pass, checks };
  }

  /* ---------------- 通用拓扑断言 ---------------- */

  /**
   * 检查元件 X 是否串联在 Y 的回路中
   * 简化：检查二者是否共享端点（通过导线）
   */
  static isSeries(topo, a, b) {
    const na = topo.compNodes.get(a.id);
    const nb = topo.compNodes.get(b.id);
    if (!na || !nb) return false;

    let shared = 0;
    for (const x of na) {
      for (const y of nb) {
        if (x === y) shared++;
      }
    }
    // 恰好共享一个节点（或重复计数后等于 1）
    return shared >= 1 && !topo.inParallel(a, b);
  }

  /**
   * 检查元件 X 是否并联在元件 Y 两端
   */
  static isParallel(topo, a, b) {
    return topo.inParallel(a, b);
  }

  /**
   * 检查两个元件是否属于同一个电气连通分量
   */
  static sameIsland(topo, a, b) {
    const na = topo.compNodes.get(a.id);
    const nb = topo.compNodes.get(b.id);
    if (!na || !nb) return false;

    for (const [, isl] of topo.islands) {
      const hasA = isl.comps.some(c => c.id === a.id);
      const hasB = isl.comps.some(c => c.id === b.id);
      if (hasA && hasB) return true;
    }
    return false;
  }

  /**
   * 找到某个元件"并联在哪个元件上"（用于判断电压表测的是谁）
   * @returns {Component|null}
   */
  static findParallelTarget(topo, meter, candidates) {
    for (const c of candidates) {
      if (c.id === meter.id) continue;
      if (topo.inParallel(meter, c)) return c;
    }
    return null;
  }

  /**
   * 找到与某元件串联的下一个元件（沿拓扑）
   */
  static findSeriesNeighbors(topo, comp) {
    const result = [];
    for (const other of topo.comps) {
      if (other.id === comp.id) continue;
      if (this.isSeries(topo, comp, other)) result.push(other);
    }
    return result;
  }

  /* ---------------- 通用检查项 ---------------- */

  /**
   * 检查某类型元件数量
   */
  static checkCount(topo, type, expected, label) {
    const n = topo.comps.filter(c => c.type === type && !c.burnedOut).length;
    return {
      name: label || `${type} 数量`,
      ok: n >= expected,
      msg: n >= expected ? `找到 ${n} 个` : `需要至少 ${expected} 个，实际 ${n} 个`
    };
  }

  /**
   * 检查是否存在闭合回路
   */
  static checkClosedLoop(topo) {
    if (topo.sources.length === 0) {
      return { name: '闭合回路', ok: false, msg: '电路中没有电源' };
    }
    const allClosed = topo.closedLoopInfo.every(i => i.closed);
    return {
      name: '闭合回路',
      ok: allClosed,
      msg: allClosed ? '已形成闭合回路' : '电源两端未通过负载连通'
    };
  }

  /**
   * 检查指定类型元件是否被接入到电路中（两端都有连接）
   */
  static checkConnected(topo, type, label) {
    const list = topo.comps.filter(c => c.type === type && !c.burnedOut);
    if (list.length === 0) {
      return { name: label || type, ok: false, msg: '未找到该元件' };
    }
    const allOk = list.every(c => {
      const nodes = topo.compNodes.get(c.id);
      return nodes && new Set(nodes).size >= 2;
    });
    return {
      name: label || type,
      ok: allOk,
      msg: allOk ? '两端已接入电路' : '存在未接入的元件'
    };
  }

  /**
   * 检查某元件 X 是否与 Y 串联
   */
  static checkSeries(topo, aType, bType, label) {
    const as = topo.comps.filter(c => c.type === aType);
    const bs = topo.comps.filter(c => c.type === bType);
    if (as.length === 0 || bs.length === 0) {
      return { name: label || '串联关系', ok: false, msg: '缺少元件' };
    }
    for (const a of as) {
      for (const b of bs) {
        if (this.isSeries(topo, a, b)) {
          return { name: label || '串联关系', ok: true, msg: '连接正确' };
        }
      }
    }
    return { name: label || '串联关系', ok: false, msg: '连接关系不正确' };
  }

  /**
   * 检查某元件 X 是否并联在 Y 两端
   */
  static checkParallel(topo, aType, bType, label) {
    const as = topo.comps.filter(c => c.type === aType);
    const bs = topo.comps.filter(c => c.type === bType);
    if (as.length === 0 || bs.length === 0) {
      return { name: label || '并联关系', ok: false, msg: '缺少元件' };
    }
    for (const a of as) {
      for (const b of bs) {
        if (this.isParallel(topo, a, b)) {
          return { name: label || '并联关系', ok: true, msg: '连接正确' };
        }
      }
    }
    return { name: label || '并联关系', ok: false, msg: '连接关系不正确' };
  }
}