/**
 * linalg.js
 * 线性方程组求解 —— 带部分主元的高斯消元。
 *
 * 奇异列处理：主元过小时跳过该列，对应解分量返回 0。
 * 这样处理悬空 / 冗余约束不会导致 NaN 扩散。
 */

const PIVOT_EPS = 1e-12;

/**
 * 求解 A·x = b
 * @param {Array<Array<number>|Float64Array>} A  系数矩阵（n×n）
 * @param {Array<number>|Float64Array} b         右端向量（n）
 * @returns {Float64Array} 解向量（n）
 */
export function solveLinear(A, b) {
  const n = b.length;
  if (n === 0) return new Float64Array(0);

  // 增广矩阵
  const M = new Array(n);
  for (let i = 0; i < n; i++) {
    const row = new Float64Array(n + 1);
    const Ai = A[i];
    for (let j = 0; j < n; j++) row[j] = Ai[j] ?? 0;
    row[n] = b[i] ?? 0;
    M[i] = row;
  }

  // 前向消元
  for (let col = 0; col < n; col++) {
    // 部分主元选择
    let pivotRow = col;
    let best = Math.abs(M[col][col]);
    for (let r = col + 1; r < n; r++) {
      const v = Math.abs(M[r][col]);
      if (v > best) { best = v; pivotRow = r; }
    }

    if (best < PIVOT_EPS) {
      // 奇异列：跳过，解分量保持 0
      M[col][col] = 0;
      continue;
    }

    if (pivotRow !== col) {
      const t = M[col]; M[col] = M[pivotRow]; M[pivotRow] = t;
    }

    const pv = M[col][col];
    for (let r = col + 1; r < n; r++) {
      const f = M[r][col] / pv;
      if (f === 0) continue;
      const Mr = M[r], Mc = M[col];
      for (let c = col; c <= n; c++) Mr[c] -= f * Mc[c];
    }
  }

  // 回代
  const x = new Float64Array(n);
  for (let i = n - 1; i >= 0; i--) {
    let s = M[i][n];
    for (let j = i + 1; j < n; j++) s -= M[i][j] * x[j];
    const d = M[i][i];
    x[i] = Math.abs(d) < PIVOT_EPS ? 0 : s / d;
    if (!Number.isFinite(x[i])) x[i] = 0;
  }

  return x;
}