/**
 * WireController.js
 * 处理导线拖拽生成、导线草稿预览。
 */

export class WireController {
  /**
   * @param {import('../core/CircuitGraph.js').CircuitGraph} graph
   * @param {import('./SelectionController.js').SelectionController} selection
   */
  constructor(graph, selection) {
    this.graph = graph;
    this.selection = selection;
    this.draft = null;   // { cid, ti }
    this.hoverTerminal = null;
    this.mouse = { x: 0, y: 0 };
  }

  start(cid, ti) {
    this.draft = { cid, ti };
  }

  move(x, y, hitTerm) {
    this.mouse.x = x;
    this.mouse.y = y;
    this.hoverTerminal = hitTerm;
  }

  /**
   * 结束拖拽；若命中另一端子则创建导线
   * @returns {object|null} 创建的导线或 null
   */
  end(hitTerm) {
    const draft = this.draft;
    this.draft = null;
    this.hoverTerminal = null;

    if (!draft || !hitTerm) return null;
    if (hitTerm.cid === draft.cid && hitTerm.ti === draft.ti) return null;

    const w = this.graph.addWire(
      { cid: draft.cid, ti: draft.ti },
      { cid: hitTerm.cid,   ti: hitTerm.ti }
    );
    return w;
  }

  cancel() {
    this.draft = null;
    this.hoverTerminal = null;
  }
}