/**
 * CircuitGraph.js
 * 电路图数据结构 —— 元件集合 + 导线集合。
 * 负责：
 *   1. 元件的增删查
 *   2. 导线的增删查
 *   3. 电气节点构建（导线并查集合并）
 *
 * 注意：这里只做"结构"，不做物理求解。
 */

import { UnionFind } from './UnionFind.js';

export class CircuitGraph {
  constructor() {
    /** @type {Map<string, import('../components/Component.js').Component>} */
    this.components = new Map();
    /** @type {Array<{id:string,a:{cid:string,ti:number},b:{cid:string,ti:number},current:number}>} */
    this.wires = [];
    this._wireSeq = 0;
    this._nodeCache = null;
  }

  /* ---------------- 元件 ---------------- */

  addComponent(c) {
    this.components.set(c.id, c);
    this._nodeCache = null;
    return c;
  }

  removeComponent(id) {
    const c = this.components.get(id);
    if (!c) return null;
    this.components.delete(id);
    // 级联删除相关导线
    this.wires = this.wires.filter(w => w.a.cid !== id && w.b.cid !== id);
    this._nodeCache = null;
    return c;
  }

  getComponent(id) {
    return this.components.get(id) || null;
  }

  get allComponents() {
    return [...this.components.values()];
  }

  /* ---------------- 导线 ---------------- */

  addWire(a, b) {
    if (!a || !b) return null;
    if (a.cid === b.cid && a.ti === b.ti) return null;
    if (this.hasWire(a, b)) return null;

    const w = {
      id: 'w' + (++this._wireSeq),
      a: { cid: a.cid, ti: a.ti },
      b: { cid: b.cid, ti: b.ti },
      current: 0,
      selected: false
    };
    this.wires.push(w);
    this._nodeCache = null;
    return w;
  }

  hasWire(a, b) {
    return this.wires.some(w =>
      (w.a.cid === a.cid && w.a.ti === a.ti && w.b.cid === b.cid && w.b.ti === b.ti) ||
      (w.b.cid === a.cid && w.b.ti === a.ti && w.a.cid === b.cid && w.a.ti === b.ti)
    );
  }

  removeWire(id) {
    const before = this.wires.length;
    this.wires = this.wires.filter(w => w.id !== id);
    if (this.wires.length !== before) {
      this._nodeCache = null;
      return true;
    }
    return false;
  }

  /* ---------------- 电气节点 ---------------- */

  /**
   * 构建电气节点映射（带缓存）
   * @returns {{
   *   uf: UnionFind,
   *   nodeIndex: Map<string, number>,
   *   nodeCount: number,
   *   nodeOf: (cid:string, ti:number)=>number,
   *   keyOf: (cid:string, ti:number)=>string
   * }}
   */
  buildNodes() {
    if (this._nodeCache) return this._nodeCache;

    const uf = new UnionFind();
    const keyOf = (cid, ti) => cid + ':' + ti;

    // 1. 所有端子各自成集合
    for (const c of this.components.values()) {
      for (let i = 0; i < c.terminals.length; i++) {
        uf.add(keyOf(c.id, i));
      }
    }

    // 2. 导线合并
    for (const w of this.wires) {
      uf.union(keyOf(w.a.cid, w.a.ti), keyOf(w.b.cid, w.b.ti));
    }

    // 3. 分配节点编号
    const nodeIndex = new Map();
    for (const c of this.components.values()) {
      for (let i = 0; i < c.terminals.length; i++) {
        const root = uf.find(keyOf(c.id, i));
        if (!nodeIndex.has(root)) nodeIndex.set(root, nodeIndex.size);
      }
    }

    const nodeOf = (cid, ti) => {
      const k = keyOf(cid, ti);
      return nodeIndex.get(uf.find(k)) ?? 0;
    };

    this._nodeCache = {
      uf,
      nodeIndex,
      nodeCount: nodeIndex.size,
      nodeOf,
      keyOf
    };
    return this._nodeCache;
  }

  invalidateNodes() {
    this._nodeCache = null;
  }

  /* ---------------- 工具 ---------------- */

  /** 某端子上连接的所有导线 */
  wiresAt(cid, ti) {
    return this.wires.filter(w =>
      (w.a.cid === cid && w.a.ti === ti) || (w.b.cid === cid && w.b.ti === ti)
    );
  }

  /** 某端子是否已接线 */
  isConnected(cid, ti) {
    return this.wires.some(w =>
      (w.a.cid === cid && w.a.ti === ti) || (w.b.cid === cid && w.b.ti === ti)
    );
  }

  clear() {
    this.components.clear();
    this.wires = [];
    this._wireSeq = 0;
    this._nodeCache = null;
  }

  /** 序列化（供撤销/重做） */
  serialize() {
    return {
      components: this.allComponents.map(c => c.serialize()),
      wires: this.wires.map(w => ({ a: { ...w.a }, b: { ...w.b } })),
      wireSeq: this._wireSeq
    };
  }

  /** 反序列化 */
  deserialize(data, factory) {
    this.clear();
    for (const cd of data.components) {
      const c = factory(cd);
      if (c) this.components.set(c.id, c);
    }
    this.wires = (data.wires || []).map(w => ({
      id: 'w' + (++this._wireSeq),
      a: { ...w.a },
      b: { ...w.b },
      current: 0,
      selected: false
    }));
    this._wireSeq = data.wireSeq ?? this._wireSeq;
    this._nodeCache = null;
  }
}