/**
 * ResistanceBox.js —— 电阻箱
 *
 * 用途：
 *   提供"已知且可调"的准确阻值。
 *   是伏阻法、安阻法测电阻实验的标准器材。
 *
 * 物理行为：
 *   纯电阻，阻值 R 可通过属性面板或 UI 调节。
 */

import { Component, nextComponentId } from './Component.js';

export class ResistanceBox extends Component {
  static type = 'resistanceBox';
  static displayName = '电阻箱';
  static icon = '🎛';
  static category = 'passive';
  static PARAM_KEYS = ['R', 'ratedPower'];

  constructor(id) {
    super(id ?? nextComponentId('rbox'));

    this.terminals = [
      { dx: -50, dy: 0 },
      { dx:  50, dy: 0 }
    ];

    this.R = 100;          // 当前阻值 (Ω)
    this.maxR = 9999;      // 最大阻值
    this.ratedPower = 1;   // 额定功率 (W)
  }

  netlist() {
    if (this.burnedOut) return [{ kind: 'open' }];
    return [{
      kind: 'resistor',
      a: 0, b: 1,
      R: Math.max(this.R, 1e-3)
    }];
  }

  getProps() {
    return [
      {
        key: 'R', label: '设定阻值', unit: 'Ω',
        min: 1, max: this.maxR, step: 1,
        slider: true,
        hint: '旋钮组合值，1 ～ 9999 Ω'
      },
      {
        key: 'ratedPower', label: '额定功率', unit: 'W',
        min: 0.1, max: 10, step: 0.1
      }
    ];
  }

  update(dt) { this.coolOverload(dt); }
}