/**
 * FaultSystem.js
 * 故障检测（每步仿真调用）。
 * 分类：
 *   - TopologyError   （由 CircuitChecker / ExperimentValidator 产生）
 *   - ElectricalFault （运行时：短路、过流、过压、超量程）
 *   - DamageSystem    （过载累计 → 烧毁）
 */

import { fmt } from '../core/Units.js';

export class FaultSystem {
  constructor() {
    /** @type {Array<{level:string,title:string,detail:string,compId?:string}>} */
    this.faults = [];
  }

  /**
   * @param {import('../core/CircuitGraph.js').CircuitGraph} graph
   * @param {object} model   PhysicalModel.get()
   * @param {number} dt
   * @param {boolean} running
   */
  update(graph, model, dt, running) {
    this.faults = [];
    const comps = graph.allComponents;

    if (!running) return this.faults;

    /* ---- 1. 元件过载 / 烧毁 ---- */
    for (const c of comps) {
      if (c.burnedOut) continue;
      if (!this._canBurn(c)) continue;

      const rated = this._ratedPower(c);
      const actual = c.P;

      if (actual > rated * 1.5) {
        c.overloadTime += dt;
        c.markOverload();

        if (model.allowDamage && c.overloadTime > model.damageDelay) {
          c.burn();
          this.faults.push({
            level: 'danger',
            compId: c.id,
            title: `🔥 ${c.label} 已烧毁`,
            detail: `实际功率 ${fmt(actual, 3)} W ／ 额定 ${fmt(rated, 3)} W`
          });
        } else {
          this.faults.push({
            level: 'warn',
            compId: c.id,
            title: `⚠ ${c.label} 过载`,
            detail: `实际 ${fmt(actual, 3)} W ／ 额定 ${fmt(rated, 3)} W`
          });
        }
      } else {
        c.coolOverload(dt);
      }
    }

    /* ---- 2. 电源过流 ---- */
    for (const c of comps) {
      if (c.type !== 'battery' || c.burnedOut) continue;
      const I = Math.abs(c.I);
      if (I > model.maxCurrent * 0.5) {
        this.faults.push({
          level: 'danger',
          compId: c.id,
          title: '⚡ 电源过流（可能短路）',
          detail: `电源电流 ${fmt(I, 2)} A，请检查是否有导线越过负载直接连接电源两端`
        });
      } else if (I > 3) {
        this.faults.push({
          level: 'warn',
          compId: c.id,
          title: '⚡ 电源电流较大',
          detail: `电源电流 ${fmt(I, 2)} A`
        });
      }
    }

    /* ---- 3. 电表超量程 ---- */
    for (const c of comps) {
      if (c.burnedOut) continue;
      if (c.type === 'ammeter' && Math.abs(c.I) > c.range * 1.05) {
        this.faults.push({
          level: 'warn',
          compId: c.id,
          title: '⚠ 电流表超量程',
          detail: `读数 ${fmt(Math.abs(c.I), 3)} A ／ 量程 ${fmt(c.range, 2)} A`
        });
      }
      if (c.type === 'voltmeter' && Math.abs(c.V) > c.range * 1.05) {
        this.faults.push({
          level: 'warn',
          compId: c.id,
          title: '⚠ 电压表超量程',
          detail: `读数 ${fmt(Math.abs(c.V), 2)} V ／ 量程 ${fmt(c.range, 2)} V`
        });
      }
    }

    return this.faults;
  }

  _canBurn(c) {
    return c.type === 'resistor' || c.type === 'bulb' ||
           c.type === 'rheostat' || c.type === 'ammeter';
  }

  _ratedPower(c) {
    if (c.ratedPower != null) return c.ratedPower;
    if (c.type === 'bulb')    return c.Prated;
    if (c.type === 'ammeter') return Math.max(c.range, 0.1) ** 2 * 0.01;
    return 0.25;
  }
}