/**
 * Ammeter.js —— 电流表
 * 理想情况 RA → 0；使用模型 numeric.ammeterR。
 */

import { Component, nextComponentId } from './Component.js';

export class Ammeter extends Component {
  static type = 'ammeter';
  static displayName = '电流表';
  static icon = 'Ⓐ';
  static category = 'meter';
  static PARAM_KEYS = ['range'];

  constructor(id) {
    super(id ?? nextComponentId('amm'));
    this.range = 0.6;    // 量程 (A)
  }

  netlist(model) {
    if (this.burnedOut) return [{ kind: 'open' }];
    return [{
      kind: 'resistor',
      a: 0, b: 1,
      R: Math.max(model.numeric.ammeterR, 1e-9)
    }];
  }

  getProps() {
    return [
      { key: 'range', label: '量程', unit: 'A', min: 0.01, max: 10, step: 0.01 }
    ];
  }

  /** 是否超量程 */
  get overRange() {
    return Math.abs(this.I) > this.range * 1.001;
  }

  update(dt) { this.coolOverload(dt); }
}