/**
 * Resistivity.js
 * 实验 5：金属丝电阻率
 *
 * 目标电路：
 *   电源 E — 开关 S — 电流表 A — 金属丝 W — 滑动变阻器 R — 回到电源
 *   电压表 V 并联在金属丝两端
 *
 * 学生任务：
 *   1. 用【刻度尺】测金属丝长度 L
 *   2. 用【螺旋测微器】测金属丝直径 d
 *   3. 通电、调滑动变阻器、记录多组 (U, I) → 求 R = U / I
 *   4. 计算 ρ = R·S / L = R·(πd²/4) / L
 */

import { register } from './ExperimentRegistry.js';
import { ExperimentValidator } from './ExperimentValidator.js';
import { SchematicRenderer } from '../rendering/SchematicRenderer.js';
import { fmt } from '../core/Units.js';

function buildSchematic() {
  const T = SchematicRenderer.terminalPos;

  const E = { id: 'sch-E', type: 'battery',   x:  80, y: 200, rot: 90, label: 'E' };
  const S = { id: 'sch-S', type: 'switch',    x: 180, y:  80, rot: 0,  label: 'S' };
  const A = { id: 'sch-A', type: 'ammeter',   x: 280, y:  80, rot: 0,  label: 'A' };
  const W = { id: 'sch-W', type: 'resistor',  x: 400, y:  80, rot: 0,  label: 'W', value: '金属丝' };
  const R = { id: 'sch-R', type: 'rheostat',  x: 520, y: 200, rot: 90, label: 'R' };
  const V = { id: 'sch-V', type: 'voltmeter', x: 400, y: 210, rot: 0,  label: 'V' };

  const els = [E, S, A, W, R, V];
  const P = (e, ti) => T(e, ti);
  const w = (id, pts) => ({ id, pts });

  const wires = [
    w('w1', [ P(E,0), { x:  80, y:  80 }, P(S,0) ]),
    w('w2', [ P(S,1), P(A,0) ]),
    w('w3', [ P(A,1), P(W,0) ]),
    w('w4', [ P(W,1), { x: 520, y:  80 }, P(R,0) ]),

    w('w5', [ P(R,2),
              { x: 620, y: 200 },
              { x: 620, y: 320 },
              { x:  80, y: 320 },
              P(E,1) ]),

    w('w6', [ P(W,0), { x: 370, y: 210 }, P(V,0) ]),
    w('w7', [ P(W,1), { x: 430, y: 210 }, P(V,1) ])
  ];

  return { width: 700, height: 360, elements: els, wires };
}

const FIELDS = [
  { key: 'n',  label: '次数',       digits: 0 },
  { key: 'U',  label: '电压 U',     unit: 'V', digits: 4 },
  { key: 'I',  label: '电流 I',     unit: 'A', digits: 5 },
  { key: 'R',  label: '电阻 R',     unit: 'Ω', digits: 4 },
  { key: 'L',  label: '长度 L',     unit: 'm', digits: 4 },
  { key: 'd',  label: '直径 d',     unit: 'm', digits: 6 },
  { key: 'rho',label: '电阻率 ρ',   unit: 'Ω·m', digits: 9 }
];

const Resistivity = {
  id: 'resistivity',
  name: '金属丝电阻率',
  category: '电磁学进阶',

  purpose:
    '用伏安法测量金属丝的电阻 R；' +
    '用刻度尺测长度 L，用螺旋测微器测直径 d；' +
    '计算金属丝的电阻率 ρ = R·S/L。',

  principle:
    '一段均匀金属丝的电阻 R = ρ·L/S，其中 ρ 是电阻率，' +
    'L 是长度，S = πd²/4 是横截面积。' +
    '因此 ρ = R·S/L = R·πd²/(4L)。' +
    '通过测量 R、L、d 即可算出电阻率。',

  equipment: [
    { type: 'battery',      count: 1, label: '电源 E' },
    { type: 'switch',       count: 1, label: '开关 S' },
    { type: 'ammeter',      count: 1, label: '电流表 A' },
    { type: 'voltmeter',    count: 1, label: '电压表 V' },
    { type: 'rheostat',     count: 1, label: '滑动变阻器 R' },
    { type: 'metalWire',    count: 1, label: '金属丝 W' }
  ],

  schematic: buildSchematic(),

  defaultSetup: [
    { type: 'battery',    x: 0.18, y: 0.30 },
    { type: 'switch',     x: 0.42, y: 0.20 },
    { type: 'ammeter',    x: 0.62, y: 0.20 },
    { type: 'metalWire',  x: 0.42, y: 0.55 },
    { type: 'rheostat',   x: 0.78, y: 0.55 },
    { type: 'voltmeter',  x: 0.18, y: 0.78 }
  ],

  fields: FIELDS,

  /* ---- 自定义测量 UI：刻度尺 + 螺旋测微器 ---- */
  renderMeasureUI(container, ctx) {
    /* 尺子 */
    const ruler = ctx.get('rulerL') ?? 0.60;
    const mic   = ctx.get('micD')   ?? 0.40e-3;

    container.insertAdjacentHTML('beforeend', `
      <div class="prop-row">
        <div class="prop-head">
          <span class="k">刻度尺（长度 L）</span>
          <span class="v" id="measL">${(ruler * 100).toFixed(1)} cm</span>
        </div>
        <input type="range" class="prop-range" id="measLRange"
          min="0.20" max="1.00" step="0.01" value="${ruler}">
      </div>
      <div class="prop-row">
        <div class="prop-head">
          <span class="k">螺旋测微器（直径 d）</span>
          <span class="v" id="measD">${(mic * 1000).toFixed(3)} mm</span>
        </div>
        <input type="range" class="prop-range" id="measDRange"
          min="0.20" max="0.80" step="0.001" value="${(mic * 1000).toFixed(3)}">
        <div class="prop-hint">拖动滑块模拟测量；实际测量中应多次测量取平均。</div>
      </div>
      <div class="row" style="border-top:1px dashed var(--line);margin-top:6px;padding-top:8px">
        <span class="k">当前 ρ = R·πd²/(4L)</span>
        <span class="v purple" id="rhoPreview">—</span>
      </div>
    `);

    const lRange = container.querySelector('#measLRange');
    const dRange = container.querySelector('#measDRange');
    const lText  = container.querySelector('#measL');
    const dText  = container.querySelector('#measD');
    const rhoPv  = container.querySelector('#rhoPreview');

    const update = () => {
      const L = parseFloat(lRange.value);
      const d_mm = parseFloat(dRange.value);
      const d = d_mm * 1e-3;
      ctx.set('rulerL', L);
      ctx.set('micD', d);
      lText.textContent = (L * 100).toFixed(1) + ' cm';
      dText.textContent = d_mm.toFixed(3) + ' mm';

      /* 用当前 R 计算 ρ 预览 */
      const R = ctx.get('lastR');
      if (Number.isFinite(R) && R > 0) {
        const S = Math.PI * d * d / 4;
        const rho = R * S / L;
        rhoPv.textContent = rho.toExponential(3) + ' Ω·m';
      } else {
        rhoPv.textContent = '—';
      }
    };

    lRange.addEventListener('input', update);
    dRange.addEventListener('input', update);
    update();
  },

  /* ---- 校验 ---- */
  validate({ topo }) {
    const checks = [];
    checks.push(ExperimentValidator.checkCount(topo, 'battery',   1, '电源'));
    checks.push(ExperimentValidator.checkCount(topo, 'switch',    1, '开关'));
    checks.push(ExperimentValidator.checkCount(topo, 'ammeter',   1, '电流表'));
    checks.push(ExperimentValidator.checkCount(topo, 'voltmeter', 1, '电压表'));
    checks.push(ExperimentValidator.checkCount(topo, 'rheostat',  1, '滑动变阻器'));
    checks.push(ExperimentValidator.checkCount(topo, 'metalWire', 1, '金属丝'));

    checks.push(ExperimentValidator.checkClosedLoop(topo));

    const volt = topo.comps.find(c => c.type === 'voltmeter');
    const wire = topo.comps.find(c => c.type === 'metalWire');
    if (volt && wire) {
      const ok = ExperimentValidator.isParallel(topo, volt, wire);
      checks.push({
        name: '电压表并接金属丝',
        ok,
        msg: ok ? '电压表已并联在金属丝两端' : '电压表应并联在金属丝两端'
      });
    }

    const amp = topo.comps.find(c => c.type === 'ammeter');
    if (amp && wire) {
      const ok = ExperimentValidator.isSeries(topo, amp, wire);
      checks.push({
        name: '电流表串联',
        ok,
        msg: ok ? '电流表已串联' : '电流表应串联在电路中'
      });
    }

    return { checks };
  },

  /* ---- 数据采集 ---- */
  makeRow(ctx) {
    const { graph, index, extra } = ctx;
    const amp  = graph.allComponents.find(c => c.type === 'ammeter' && !c.burnedOut);
    const volt = graph.allComponents.find(c => c.type === 'voltmeter' && !c.burnedOut);
    const wire = graph.allComponents.find(c => c.type === 'metalWire' && !c.burnedOut);
    if (!amp || !volt || !wire) return null;

    const I = Math.abs(amp.I);
    const U = Math.abs(volt.V);
    if (I < 1e-6) return null;

    const R = U / I;
    const L = extra.rulerL ?? 0.60;
    const d = extra.micD ?? 0.40e-3;
    const S = Math.PI * d * d / 4;
    const rho = R * S / L;

    /* 缓存一下 R 给预览用 */
    extra.lastR = R;

    return {
      n: index + 1,
      U: +U.toFixed(5),
      I: +I.toFixed(6),
      R: +R.toFixed(5),
      L: +L.toFixed(4),
      d: +d.toFixed(6),
      rho: +rho.toExponential(6)
    };
  },

  charts: [
    {
      key: 'ui',
      title: 'U-I 曲线（斜率即为 R）',
      xField: 'I',
      yField: 'U',
      xLabel: 'I / A',
      yLabel: 'U / V',
      mode: 'scatter',
      fit: true,
      fitFormatter: (f) => `斜率 R ≈ ${f.b.toFixed(4)} Ω (R² = ${f.r2.toFixed(4)})`
    }
  ],

  interpret(fits, extra) {
    const fit = fits?.ui;
    const L   = extra.rulerL ?? 0.60;
    const d   = extra.micD ?? 0.40e-3;
    const lines = [];
    if (fit) {
      const R = fit.b;
      const S = Math.PI * d * d / 4;
      const rho = R * S / L;
      lines.push(`由 U-I 拟合得 R ≈ ${R.toFixed(5)} Ω`);
      lines.push(`测得 L = ${(L * 100).toFixed(1)} cm，d = ${(d * 1000).toFixed(3)} mm`);
      lines.push(`横截面积 S = πd²/4 = ${S.toExponential(3)} m²`);
      lines.push(`电阻率 ρ = R·S/L = ${rho.toExponential(3)} Ω·m`);
    } else {
      lines.push('请先记录多组数据');
    }
    return { title: '实验结果', lines };
  }
};

register(Resistivity);

export default Resistivity;