/**
 * CapacitorRC.js
 * 实验 4：电容器充放电
 *
 * 目标电路：
 *   电源 E — 开关 S — 电阻 R — 电容 C — 回到电源
 *   电压表 V 并联在电容两端
 *
 * 核心：
 *   充电  Uc(t) = E (1 - e^(-t/τ)),   τ = RC
 *   放电  Uc(t) = U0 e^(-t/τ)
 *   使用自动采样：每 0.05s 记录一组 (t, Uc, I, Q)
 */

import { register } from './ExperimentRegistry.js';
import { ExperimentValidator } from './ExperimentValidator.js';
import { SchematicRenderer } from '../rendering/SchematicRenderer.js';

function buildSchematic() {
  const T = SchematicRenderer.terminalPos;

  const E = { id: 'sch-E', type: 'battery',   x:  80, y: 170, rot: 90, label: 'E', value: '6 V' };
  const S = { id: 'sch-S', type: 'switch',    x: 180, y:  80, rot: 0,  label: 'S' };
  const R = { id: 'sch-R', type: 'resistor',  x: 300, y:  80, rot: 0,  label: 'R' };
  const C = { id: 'sch-C', type: 'capacitor', x: 420, y:  80, rot: 0,  label: 'C' };
  const V = { id: 'sch-V', type: 'voltmeter', x: 420, y: 210, rot: 0,  label: 'V' };

  const els = [E, S, R, C, V];
  const P = (e, ti) => T(e, ti);
  const w = (id, pts) => ({ id, pts });

  const wires = [
    // 电源正极 → 开关 → 电阻 → 电容
    w('w1', [ P(E, 0), { x:  80, y:  80 }, P(S, 0) ]),
    w('w2', [ P(S, 1), P(R, 0) ]),
    w('w3', [ P(R, 1), P(C, 0) ]),

    // 电容右端 → 绕过右侧 → 回到电源负极
    w('w4', [ P(C, 1), { x: 500, y: 80 }, { x: 500, y: 260 }, { x: 80, y: 260 }, P(E, 1) ]),

    // 电压表并接在电容两端：两条竖直下引线
    w('w5', [ P(C, 0), { x: 398, y: 210 } ]),
    w('w6', [ P(C, 1), { x: 442, y: 210 } ])
  ];

  return { width: 580, height: 300, elements: els, wires };
}

const FIELDS = [
  { key: 't', label: '时间 t',   unit: 's', digits: 3 },
  { key: 'Uc',label: '电压 Uc',  unit: 'V', digits: 4 },
  { key: 'I', label: '电流 I',   unit: 'A', digits: 5 },
  { key: 'Q', label: '电荷 Q',   unit: 'C', digits: 5 }
];

const CapacitorRC = {
  id: 'capacitor-rc',
  name: '电容器充放电',
  category: '电磁学进阶',

  purpose:
    '观察电容器充放电过程中电压和电流随时间的变化；' +
    '理解时间常数 τ = RC 的物理意义；' +
    '掌握用 Uc-t 曲线求时间常数的方法。',

  principle:
    '充电过程：Uc(t) = E (1 - e^(-t/τ))，' +
    '放电过程：Uc(t) = U0 e^(-t/τ)，' +
    '其中 τ = R·C 是时间常数。τ 时刻 Uc 达到稳态值的 63.2%。' +
    '通过观察电压与电流随时间的变化，可以验证指数规律。',

  equipment: [
    { type: 'battery',   count: 1, label: '电源 E' },
    { type: 'switch',    count: 1, label: '开关 S' },
    { type: 'resistor',  count: 1, label: '电阻 R' },
    { type: 'capacitor', count: 1, label: '电容 C' },
    { type: 'voltmeter', count: 1, label: '电压表 V' }
  ],

  schematic: buildSchematic(),

  defaultSetup: [
    { type: 'battery',   x: 0.18, y: 0.35 },
    { type: 'switch',    x: 0.42, y: 0.20 },
    { type: 'resistor',  x: 0.62, y: 0.20 },
    { type: 'capacitor', x: 0.80, y: 0.20 },
    { type: 'voltmeter', x: 0.80, y: 0.70 }
  ],

  fields: FIELDS,

  /* ---- 自动采样：每 0.05s 记录一组 ---- */
  autoSample: {
    interval: 0.05,
    sampler: ({ graph, simTime }) => {
      const cap = graph.allComponents.find(c => c.type === 'capacitor' && !c.burnedOut);
      if (!cap) return null;

      const volt = graph.allComponents.find(c => c.type === 'voltmeter' && !c.burnedOut);
      const Uc = volt ? volt.V : cap.Vc;
      const I  = cap.I;
      const Q  = cap.C * cap.Vc;

      return {
        t: +simTime.toFixed(3),
        Uc: +Uc.toFixed(5),
        I: +I.toFixed(6),
        Q: +Q.toFixed(6)
      };
    }
  },

  /* ---- 校验 ---- */
  validate({ topo }) {
    const checks = [];
    checks.push(ExperimentValidator.checkCount(topo, 'battery',   1, '电源'));
    checks.push(ExperimentValidator.checkCount(topo, 'switch',    1, '开关'));
    checks.push(ExperimentValidator.checkCount(topo, 'resistor',  1, '电阻'));
    checks.push(ExperimentValidator.checkCount(topo, 'capacitor', 1, '电容器'));
    checks.push(ExperimentValidator.checkCount(topo, 'voltmeter', 1, '电压表'));

    const volt = topo.comps.find(c => c.type === 'voltmeter');
    const cap  = topo.comps.find(c => c.type === 'capacitor');
    if (volt && cap) {
      const ok = ExperimentValidator.isParallel(topo, volt, cap);
      checks.push({
        name: '电压表并接电容',
        ok,
        msg: ok ? '电压表已并联在电容两端' : '电压表应并联在电容两端'
      });
    }

    return { checks };
  },

  /* ---- 手动采集（可选） ---- */
  makeRow(ctx) {
    const { graph } = ctx;
    const cap = graph.allComponents.find(c => c.type === 'capacitor' && !c.burnedOut);
    if (!cap) return null;
    const volt = graph.allComponents.find(c => c.type === 'voltmeter' && !c.burnedOut);
    const Uc = volt ? volt.V : cap.Vc;
    return {
      t: +(ctx.simTime ?? 0).toFixed(3),
      Uc: +Uc.toFixed(5),
      I: +cap.I.toFixed(6),
      Q: +(cap.C * cap.Vc).toFixed(6)
    };
  },

  charts: [
    {
      key: 'uc-t',
      title: 'Uc-t 曲线',
      xField: 't',
      yField: 'Uc',
      xLabel: 't / s',
      yLabel: 'Uc / V',
      mode: 'line',
      fit: false
    },
    {
      key: 'i-t',
      title: 'I-t 曲线',
      xField: 't',
      yField: 'I',
      xLabel: 't / s',
      yLabel: 'I / A',
      mode: 'line',
      fit: false
    }
  ],

  interpret(fits, extra) {
    const lines = [
      '充电阶段：Uc 从 0 迅速上升，I 从最大值迅速衰减。',
      '放电阶段：Uc 指数下降，I 反向。',
      '时间常数 τ = R·C：在 t = τ 时 Uc ≈ 0.632·E（充电）或 0.368·U0（放电）。'
    ];
    return { title: '实验结论', lines };
  }
};

register(CapacitorRC);

export default CapacitorRC;