/**
 * SelectionController.js
 * 处理"选中"状态与命中检测。
 */

export class SelectionController {
  /**
   * @param {import('../core/CircuitGraph.js').CircuitGraph} graph
   * @param {(sel:object|null)=>void} onChange
   */
  constructor(graph, onChange) {
    this.graph = graph;
    this.onChange = onChange;
    this.selection = null;   // { kind:'component'|'wire', obj }
  }

  set(sel) {
    const prev = this.selection;
    this.selection = sel;
    if (prev !== sel || (prev && sel && prev.obj !== sel.obj)) {
      this.onChange?.(sel);
    }
  }

  clear() { this.set(null); }

  selectComponent(c) {
    for (const w of this.graph.wires) w.selected = false;
    this.set(c ? { kind: 'component', obj: c } : null);
  }

  selectWire(w) {
    for (const ww of this.graph.wires) ww.selected = false;
    if (w) w.selected = true;
    this.set(w ? { kind: 'wire', obj: w } : null);
  }

  /** 命中检测：端子 */
  hitTerminal(x, y, tol) {
    const comps = this.graph.allComponents;
    for (let i = comps.length - 1; i >= 0; i--) {
      const c = comps[i];
      for (let t = 0; t < c.terminals.length; t++) {
        const p = c.termPos(t);
        if (Math.hypot(p.x - x, p.y - y) < tol) {
          return { cid: c.id, ti: t };
        }
      }
    }
    return null;
  }

  /** 命中检测：元件 */
  hitComponent(x, y) {
    const comps = this.graph.allComponents;
    for (let i = comps.length - 1; i >= 0; i--) {
      const c = comps[i];
      const { w, h } = this._bbox(c);
      if (Math.abs(x - c.x) < w / 2 && Math.abs(y - c.y) < h / 2) return c;
    }
    return null;
  }

  _bbox(c) {
    switch (c.type) {
      case 'battery':   return { w: 100, h: 70 };
      case 'rheostat':  return { w: 112, h: 96 };
      case 'spdt':      return { w: 120, h: 80 };
      case 'bulb':      return { w: 90, h: 80 };
      case 'ammeter':
      case 'voltmeter': return { w: 96, h: 70 };
      case 'capacitor': return { w: 96, h: 60 };
      default:          return { w: 96, h: 64 };
    }
  }

  /** 命中检测：滑动变阻器滑片 */
  hitSlider(x, y) {
    for (const c of this.graph.allComponents) {
      if (c.type !== 'rheostat' || c.burnedOut) continue;
      const w = 96, h = 30;
      const sx = c.x + (-w / 2 + 6 + (w - 12) * Math.max(0, Math.min(1, c.slider)));
      const sy = c.y - h / 2 - 16;
      if (Math.abs(x - sx) < 13 && y > sy - 14 && y < sy + 28) return c;
    }
    return null;
  }

  /** 命中检测：导线（沿贝塞尔曲线采样） */
  hitWire(x, y, tol = 8) {
    const wires = this.graph.wires;
    for (let i = wires.length - 1; i >= 0; i--) {
      const w = wires[i];
      const a = this._wireEndpoint(w.a);
      const b = this._wireEndpoint(w.b);
      if (!a || !b) continue;

      const dx = b.x - a.x, dy = b.y - a.y;
      const d = Math.hypot(dx, dy);
      const sag = Math.min(26, d * 0.14);
      const mx = (a.x + b.x) / 2;
      const my = (a.y + b.y) / 2 + sag;

      // 采样
      const STEPS = 24;
      for (let s = 0; s <= STEPS; s++) {
        const u = s / STEPS;
        const mu = 1 - u;
        const px = mu * mu * a.x + 2 * mu * u * mx + u * u * b.x;
        const py = mu * mu * a.y + 2 * mu * u * my + u * u * b.y;
        if (Math.hypot(px - x, py - y) < tol) return w;
      }
    }
    return null;
  }

  _wireEndpoint(ref) {
    const c = this.graph.getComponent(ref.cid);
    if (!c) return null;
    return c.termPos(ref.ti);
  }
}