/**
 * Capacitor.js —— 电容器
 * 采用后向欧拉伴随模型，状态量为端电压 Vc。
 */

import { Component, nextComponentId } from './Component.js';

export class Capacitor extends Component {
  static type = 'capacitor';
  static displayName = '电容器';
  static icon = '⊣⊢';
  static category = 'passive';
  static PARAM_KEYS = ['C'];

  constructor(id) {
    super(id ?? nextComponentId('cap'));
    this.C = 1000e-6;   // 1000 μF
    this.Vc = 0;        // 当前端电压（状态量，用于后向欧拉）
    this.Q = 0;         // 电荷量 Q = C·Vc
  }

  netlist(model, dt) {
    if (this.burnedOut) return [{ kind: 'open' }];
    return [{
      kind: 'capacitor',
      a: 0, b: 1,
      C: Math.max(this.C, 1e-9),
      Vprev: this.Vc
    }];
  }

  getProps() {
    return [
      {
        key: 'C', label: '电容', unit: 'μF',
        min: 1, max: 10000, step: 10,
        transform: 'uF',    // UI 显示 μF，内部存 F
        hint: '1 F = 1 000 000 μF'
      }
    ];
  }

  update(dt) {
    this.coolOverload(dt);
    // 更新状态量（求解器已把 V 写入 this.V）
    this.Vc = this.V;
    this.Q = this.C * this.Vc;
  }
}