/**
 * UIManager.js
 * 统一管理右侧信息面板、底部工具栏、状态栏、顶栏交互。
 */

import { fmt } from '../core/Units.js';

export class UIManager {
  constructor() {
    this.panel    = document.getElementById('panel');
    this.statusEl = document.getElementById('status');
    this.runBtn   = document.getElementById('btnRun');
    this.pauseBtn = document.getElementById('btnPause');

    this._statusTimer = null;
  }

  /* ---------------- 状态栏 ---------------- */

  setStatus(msg, type = '') {
    if (!this.statusEl) return;
    this.statusEl.textContent = msg;
    this.statusEl.className = 'status' + (type ? ' ' + type : '');
  }

  /* ---------------- 右侧信息面板 ---------------- */

  /**
   * @param {object} data { graph, running, selection, faults, checkResult, model }
   */
  renderPanel(data) {
    if (!this.panel) return;

    const { graph, running, selection, faults, checkResult, model } = data;
    const comps = graph.allComponents;
    const parts = [];

    /* -------- 电路状态 -------- */
    parts.push(this._cardCircuitStatus(comps, running, model));

    /* -------- 选中元件：仅显示运行量（参数在专用面板） -------- */
    if (selection?.kind === 'component') {
      parts.push(this._cardSelectionRuntime(selection.obj, running));
    }

    /* -------- 故障 -------- */
    if (faults && faults.length) {
      parts.push(this._cardFaults(faults));
    }

    /* -------- 检查结果 -------- */
    if (checkResult?.issues?.length) {
      parts.push(this._cardChecks(checkResult));
    } else if (checkResult?.ok) {
      parts.push(`<div class="card"><div class="card-title">电路检查</div>
        <div class="fault-item ok"><div><b>✅ 电路连接正确</b><br>可以通电进行实验</div></div>
      </div>`);
    }

    /* -------- 元件清单 -------- */
    if (comps.length) {
      parts.push(this._cardManifest(comps));
    }

    this.panel.innerHTML = parts.join('');
  }

  _cardCircuitStatus(comps, running, model) {
    let inner = '';

    if (comps.length === 0) {
      inner = `<div class="empty-tip">暂无元件<br>点击左侧器材库添加</div>`;
    } else if (!running) {
      inner = `<div class="empty-tip">电路未通电<br>点击「▶ 通电」开始计算</div>`;
    } else {
      const src = comps.find(c => c.type === 'battery' && !c.burnedOut);
      if (src) {
        inner += `<div class="row"><span class="k">电源电动势 E</span>
          <span class="v acc">${fmt(src.E, 2)} V</span></div>`;
        inner += `<div class="row"><span class="k">路端电压 U</span>
          <span class="v">${fmt(src.V, 3)} V</span></div>`;
        const iCls = Math.abs(src.I) > 5 ? 'danger' : 'ok';
        inner += `<div class="row"><span class="k">电源电流 I</span>
          <span class="v ${iCls}">${fmt(src.I, 3)} A</span></div>`;

        // 内电压
        const r = src.rOverride != null ? src.rOverride : model.numeric.sourceR;
        if (r > 0.01) {
          inner += `<div class="row"><span class="k">内电压 Ir</span>
            <span class="v warn">${fmt(Math.abs(src.I) * r, 3)} V</span></div>`;
        }
      }
      const totalP = comps.reduce((a, c) => a + (c.P || 0), 0);
      inner += `<div class="row"><span class="k">电路总功率</span>
        <span class="v">${fmt(totalP, 3)} W</span></div>`;
    }

    return `<div class="card"><div class="card-title">电路状态</div>${inner}</div>`;
  }

  _cardSelectionRuntime(c, running) {
    if (!running) return '';
    return `<div class="card"><div class="card-title">${c.label} · 实时读数</div>
      <div class="row"><span class="k">电流 I</span><span class="v acc">${fmt(c.I, 4)} A</span></div>
      <div class="row"><span class="k">电压 U</span><span class="v acc">${fmt(c.V, 3)} V</span></div>
      <div class="row"><span class="k">功率 P</span><span class="v">${fmt(c.P, 3)} W</span></div>
      ${c.type === 'bulb' ? `<div class="row"><span class="k">亮度</span><span class="v purple">${fmt(c.brightness, 2)}</span></div>` : ''}
      ${c.type === 'capacitor' ? `<div class="row"><span class="k">电荷 Q</span><span class="v purple">${fmt(c.Q, 4)} C</span></div>` : ''}
    </div>`;
  }

  _cardFaults(faults) {
    const rows = faults.map(f => {
      const cls = f.level === 'warn' ? 'warn' : (f.level === 'ok' ? 'ok' : (f.level === 'info' ? 'info' : ''));
      return `<div class="fault-item ${cls}">
        <div><b>${f.title}</b>${f.detail ? '<br>' + f.detail : ''}</div>
      </div>`;
    }).join('');
    return `<div class="card"><div class="card-title">故障诊断</div>${rows}</div>`;
  }

  _cardChecks(checkResult) {
    const rows = checkResult.issues.map(i => {
      const cls = i.level === 'danger' ? '' : (i.level === 'warn' ? 'warn' : 'info');
      return `<div class="fault-item ${cls}">
        <div><b>${i.title}</b>${i.detail ? '<br>' + i.detail : ''}</div>
      </div>`;
    }).join('');
    return `<div class="card"><div class="card-title">电路检查</div>${rows}</div>`;
  }

  _cardManifest(comps) {
    const counts = new Map();
    for (const c of comps) {
      counts.set(c.label, (counts.get(c.label) || 0) + 1);
    }
    let inner = '';
    for (const [name, n] of counts) {
      inner += `<div class="row"><span class="k">${name}</span><span class="v">× ${n}</span></div>`;
    }
    return `<div class="card"><div class="card-title">元件清单</div>${inner}</div>`;
  }

  /* ---------------- 按钮状态 ---------------- */

  setRunning(running) {
    if (!this.runBtn) return;
    if (running) {
      this.runBtn.textContent = '⏹ 断电';
      this.runBtn.className = 'btn stop';
      this.pauseBtn.disabled = false;
      this.pauseBtn.textContent = '⏸ 暂停';
    } else {
      this.runBtn.textContent = '▶ 通电';
      this.runBtn.className = 'btn run';
      this.pauseBtn.disabled = true;
    }
  }

  setPaused(paused) {
    if (!this.pauseBtn) return;
    this.pauseBtn.textContent = paused ? '▶ 继续' : '⏸ 暂停';
  }

  /* ---------------- 弹窗 ---------------- */

  help() {
    return `
      <b>1. 添加器材</b><br>
      点击左侧「器材库」中的任意元件，即可添加到实验台。<br><br>

      <b>2. 连接导线</b><br>
      每个元件两端（或三端）有<b>小圆点</b>，那是接线端子。<br>
      按住一个端子拖动到另一个端子松开，即可生成导线。<br><br>

      <b>3. 操作元件</b><br>
      · <b>拖动元件主体</b>：移动位置<br>
      · <b>点击开关</b>：切换通断<br>
      · <b>拖动滑片</b>：调节滑动变阻器阻值<br>
      · <b>右键</b>：删除元件或导线<br><br>

      <b>4. 通电实验</b><br>
      点击底部 <code>▶ 通电</code>，物理引擎开始实时计算。<br>
      电流会用<b>流动光点</b>显示，数值实时更新。<br><br>

      <b>5. 物理模型</b><br>
      · <b>初中理想</b>：电源无内阻、电压表内阻无穷大<br>
      · <b>高中理想</b>：含电源内阻 r<br>
      · <b>真实实验</b>：含电表内阻、导线电阻、灯泡非线性<br><br>

      <b>⚠ 注意</b><br>
      短路过载会<b>真正烧毁元件</b>（除初中模型外）。<br>
      烧毁后元件变为断路，需清空重来。
    `;
  }
}