/**
 * CircuitCanvas.js
 * 实验台主渲染器。
 * 职责：
 *   - 管理 Canvas 尺寸与 DPR
 *   - 绘制背景、导线、元件、端子、电流粒子、拖拽预览
 *   - 提供坐标转换与视图尺寸
 */

import { roundRect, drawLabel } from './drawUtils.js';
import { CurrentRenderer } from './CurrentRenderer.js';
import { fmt, clamp } from '../core/Units.js';

const TERM_R = 5.5;
export const HIT_TERM = 16;

export class CircuitCanvas {
  /**
   * @param {HTMLCanvasElement} canvas
   * @param {HTMLElement} stage
   */
  constructor(canvas, stage) {
    this.canvas = canvas;
    this.stage = stage;
    this.ctx = canvas.getContext('2d');
    this.current = new CurrentRenderer();

    this.W = 800;
    this.H = 500;
    this.dpr = 1;

    this._bindResize();
  }

  _bindResize() {
    const onResize = () => this.resize();
    window.addEventListener('resize', onResize);
    if (window.ResizeObserver) {
      new ResizeObserver(onResize).observe(this.stage);
    }
    this.resize();
  }

  resize() {
    const r = this.stage.getBoundingClientRect();
    this.W = Math.max(320, Math.floor(r.width));
    this.H = Math.max(240, Math.floor(r.height));
    this.dpr = Math.min(window.devicePixelRatio || 1, 2);

    this.canvas.width  = Math.round(this.W * this.dpr);
    this.canvas.height = Math.round(this.H * this.dpr);
    this.canvas.style.width  = this.W + 'px';
    this.canvas.style.height = this.H + 'px';
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
  }

  /**
   * 主渲染入口
   * @param {object} scene { graph, selection, running, wireDraft, mouse, hover }
   */
  render(scene) {
    const ctx = this.ctx;

    this._drawBackground(ctx);

    // 导线 + 电流
    for (const w of scene.graph.wires) {
      this._drawWire(ctx, w, scene);
    }
    if (scene.running) {
      for (const w of scene.graph.wires) {
        if (Math.abs(w.current || 0) < 1e-4) continue;
        const a = this._terminalPos(scene.graph, w.a);
        const b = this._terminalPos(scene.graph, w.b);
        if (!a || !b) continue;
        this.current.drawWireCurrent(ctx, { a, b, current: w.current });
      }
    }

    // 元件
    for (const c of scene.graph.allComponents) {
      this._drawComponent(ctx, c, scene);
    }

    // 端子（最上层）
    for (const c of scene.graph.allComponents) {
      for (let i = 0; i < c.terminals.length; i++) {
        this._drawTerminal(ctx, c, i, scene);
      }
    }

    // 拉线预览
    if (scene.wireDraft) {
      this._drawWireDraft(ctx, scene);
    }

    // 空场景提示
    const hint = document.getElementById('hint');
    if (hint) {
      hint.style.opacity = scene.graph.components.size === 0 ? '1' : '0';
    }
  }

  /* ---------------- 背景 ---------------- */

  _drawBackground(ctx) {
    const { W, H } = this;
    ctx.fillStyle = '#0d1320';
    ctx.fillRect(0, 0, W, H);

    ctx.save();
    ctx.strokeStyle = 'rgba(56,189,248,0.055)';
    ctx.lineWidth = 1;
    const g = 32;
    for (let x = 0; x < W; x += g) {
      ctx.beginPath(); ctx.moveTo(x + 0.5, 0); ctx.lineTo(x + 0.5, H); ctx.stroke();
    }
    for (let y = 0; y < H; y += g) {
      ctx.beginPath(); ctx.moveTo(0, y + 0.5); ctx.lineTo(W, y + 0.5); ctx.stroke();
    }
    ctx.restore();

    const rg = ctx.createRadialGradient(W / 2, H / 2, 0, W / 2, H / 2, Math.max(W, H) * 0.7);
    rg.addColorStop(0, 'rgba(56,189,248,0.045)');
    rg.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = rg;
    ctx.fillRect(0, 0, W, H);
  }

  /* ---------------- 导线 ---------------- */

  _terminalPos(graph, ref) {
    const c = graph.getComponent(ref.cid);
    if (!c) return null;
    return c.termPos(ref.ti);
  }

  _drawWire(ctx, w, scene) {
    const a = this._terminalPos(scene.graph, w.a);
    const b = this._terminalPos(scene.graph, w.b);
    if (!a || !b) return;

    const hot = scene.running && Math.abs(w.current || 0) > 1e-4;
    const selected = scene.selection?.kind === 'wire' && scene.selection.obj === w;

    ctx.save();
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    if (hot) {
      ctx.strokeStyle = 'rgba(56,189,248,0.16)';
      ctx.lineWidth = 9;
      this._wirePath(ctx, a, b);
      ctx.stroke();
    }

    ctx.strokeStyle = selected ? '#38bdf8' : (hot ? '#2f4f6b' : '#334155');
    ctx.lineWidth = selected ? 4 : 3;
    this._wirePath(ctx, a, b);
    ctx.stroke();

    ctx.strokeStyle = hot ? 'rgba(125,211,252,0.5)' : 'rgba(148,163,184,0.18)';
    ctx.lineWidth = 1.2;
    this._wirePath(ctx, a, b);
    ctx.stroke();

    ctx.restore();
  }

  _wirePath(ctx, a, b) {
    const dx = b.x - a.x, dy = b.y - a.y;
    const d = Math.hypot(dx, dy);
    const sag = Math.min(26, d * 0.14);
    ctx.beginPath();
    ctx.moveTo(a.x, a.y);
    ctx.quadraticCurveTo((a.x + b.x) / 2, (a.y + b.y) / 2 + sag, b.x, b.y);
  }

  _drawWireDraft(ctx, scene) {
    const draft = scene.wireDraft;
    const c = scene.graph.getComponent(draft.cid);
    if (!c) return;
    const p = c.termPos(draft.ti);

    ctx.save();
    ctx.setLineDash([6, 5]);
    ctx.strokeStyle = '#38bdf8';
    ctx.lineWidth = 2.4;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(p.x, p.y);
    ctx.lineTo(scene.mouse.x, scene.mouse.y);
    ctx.stroke();
    ctx.restore();

    // 目标端子高亮
    if (scene.hoverTerminal && scene.hoverTerminal !== draft) {
      const tc = scene.graph.getComponent(scene.hoverTerminal.cid);
      if (tc) {
        const tp = tc.termPos(scene.hoverTerminal.ti);
        ctx.save();
        ctx.strokeStyle = '#22c55e';
        ctx.lineWidth = 2.5;
        ctx.beginPath();
        ctx.arc(tp.x, tp.y, TERM_R + 7, 0, Math.PI * 2);
        ctx.stroke();
        ctx.restore();
      }
    }
  }

  /* ---------------- 元件 ---------------- */

  _drawComponent(ctx, c, scene) {
    const selected = scene.selection?.kind === 'component' && scene.selection.obj === c;

    ctx.save();
    ctx.translate(c.x, c.y);

    if (selected) {
      ctx.save();
      ctx.strokeStyle = 'rgba(56,189,248,0.65)';
      ctx.lineWidth = 2;
      ctx.setLineDash([5, 4]);
      const w = c.type === 'battery' ? 108 : 100;
      roundRect(ctx, -w / 2 - 6, -46, w + 12, 92, 12);
      ctx.stroke();
      ctx.restore();
    }

    switch (c.type) {
      case 'battery':   this._drawBattery(ctx, c, scene); break;
      case 'resistor':  this._drawResistor(ctx, c, scene); break;
      case 'resistanceBox': this._drawResistanceBox(ctx, c); break;
      case 'rheostat':  this._drawRheostat(ctx, c, scene); break;
      case 'bulb':      this._drawBulb(ctx, c, scene); break;
      case 'capacitor': this._drawCapacitor(ctx, c, scene); break;
      case 'switch':    this._drawSwitch(ctx, c, scene); break;
      case 'spdt':      this._drawSPDT(ctx, c, scene); break;
      case 'ammeter':   this._drawMeter(ctx, c, scene, 'A', '#38bdf8'); break;
      case 'voltmeter': this._drawMeter(ctx, c, scene, 'V', '#a855f7'); break;
      default:          this._drawGeneric(ctx, c); break;
    }

    // 状态标记
    if (c.burnedOut) {
      ctx.save();
      ctx.fillStyle = 'rgba(239,68,68,0.14)';
      roundRect(ctx, -52, -34, 104, 68, 10);
      ctx.fill();
      ctx.strokeStyle = '#ef4444';
      ctx.lineWidth = 1.6;
      ctx.setLineDash([5, 4]);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.fillStyle = '#fca5a5';
      ctx.font = 'bold 11px system-ui';
      ctx.textAlign = 'center';
      ctx.fillText('🔥 已烧毁', 0, -44);
      ctx.restore();
    } else if (c.state === 'overload') {
      ctx.save();
      ctx.fillStyle = '#fbbf24';
      ctx.font = 'bold 11px system-ui';
      ctx.textAlign = 'center';
      ctx.fillText('⚠ 过载', 0, -44);
      ctx.restore();
    }

    ctx.restore();
  }

  _drawTerminal(ctx, c, i, scene) {
    const p = c.termPos(i);
    const isStart = scene.wireDraft &&
      scene.wireDraft.cid === c.id && scene.wireDraft.ti === i;
    const isHover = scene.hoverTerminal &&
      scene.hoverTerminal.cid === c.id && scene.hoverTerminal.ti === i;

    ctx.save();

    ctx.beginPath();
    ctx.arc(p.x, p.y, TERM_R + 4, 0, Math.PI * 2);
    ctx.fillStyle = (isStart || isHover)
      ? 'rgba(56,189,248,0.28)'
      : 'rgba(56,189,248,0.08)';
    ctx.fill();

    ctx.beginPath();
    ctx.arc(p.x, p.y, TERM_R, 0, Math.PI * 2);
    ctx.fillStyle = isStart ? '#38bdf8' : (isHover ? '#22c55e' : '#1e293b');
    ctx.fill();
    ctx.strokeStyle = isStart ? '#bae6fd' : (isHover ? '#86efac' : '#475569');
    ctx.lineWidth = 1.8;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(p.x, p.y, 1.8, 0, Math.PI * 2);
    ctx.fillStyle = isStart ? '#04121f' : '#64748b';
    ctx.fill();

    ctx.restore();
  }

  /* ---------------- 各类元件绘制 ---------------- */

  _drawBattery(ctx, c, scene) {
    const w = 84, h = 46;

    const g = ctx.createLinearGradient(0, -h / 2, 0, h / 2);
    g.addColorStop(0, '#1e293b');
    g.addColorStop(1, '#0f172a');
    ctx.fillStyle = g;
    roundRect(ctx, -w / 2, -h / 2, w, h, 8);
    ctx.fill();
    ctx.strokeStyle = '#334155';
    ctx.lineWidth = 1.5;
    ctx.stroke();

    ctx.fillStyle = '#22c55e';
    roundRect(ctx, -w / 2, -h / 2, 10, h, 8);
    ctx.fill();

    ctx.fillStyle = '#64748b';
    roundRect(ctx, w / 2 - 10, -h / 2, 10, h, 8);
    ctx.fill();

    ctx.fillStyle = '#22c55e';
    ctx.font = 'bold 17px system-ui';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('+', -w / 2 + 22, 0);

    ctx.fillStyle = '#94a3b8';
    ctx.fillText('−', w / 2 - 22, 0);

    ctx.fillStyle = '#7dd3fc';
    ctx.font = 'bold 14px system-ui';
    ctx.fillText(fmt(c.E, 1) + 'V', 0, 0);
  }

  _drawResistor(ctx, c) {
    const w = 78, h = 32;

    ctx.strokeStyle = '#475569';
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.moveTo(-42, 0); ctx.lineTo(-w / 2, 0);
    ctx.moveTo(w / 2, 0); ctx.lineTo(42, 0);
    ctx.stroke();

    const g = ctx.createLinearGradient(0, -h / 2, 0, h / 2);
    g.addColorStop(0, '#334155');
    g.addColorStop(0.5, '#1e293b');
    g.addColorStop(1, '#0f172a');
    ctx.fillStyle = g;
    roundRect(ctx, -w / 2, -h / 2, w, h, 6);
    ctx.fill();
    ctx.strokeStyle = '#475569';
    ctx.lineWidth = 1.4;
    ctx.stroke();

    ctx.save();
    ctx.fillStyle = 'rgba(56,189,248,0.35)';
    ctx.fillRect(-w / 2 + 12, -h / 2 + 3, 4, h - 6);
    ctx.fillRect(-w / 2 + 22, -h / 2 + 3, 4, h - 6);
    ctx.fillStyle = 'rgba(245,158,11,0.35)';
    ctx.fillRect(w / 2 - 20, -h / 2 + 3, 4, h - 6);
    ctx.restore();

    ctx.fillStyle = c.burnedOut ? '#fca5a5' : '#7dd3fc';
    ctx.font = 'bold 13px system-ui';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(fmt(c.R, 1) + 'Ω', 0, 0);
  }
  _drawResistanceBox(ctx, c) {
    const w = 88, h = 50;

    /* 连接线 */
    ctx.strokeStyle = '#475569';
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.moveTo(-50, 0); ctx.lineTo(-w / 2, 0);
    ctx.moveTo(w / 2, 0); ctx.lineTo(50, 0);
    ctx.stroke();

    /* 外壳 */
    const g = ctx.createLinearGradient(0, -h / 2, 0, h / 2);
    g.addColorStop(0, '#334155');
    g.addColorStop(0.5, '#1e293b');
    g.addColorStop(1, '#0f172a');
    ctx.fillStyle = g;
    roundRect(ctx, -w / 2, -h / 2, w, h, 6);
    ctx.fill();
    ctx.strokeStyle = '#475569';
    ctx.lineWidth = 1.4;
    ctx.stroke();

    /* 顶部四个"旋钮"装饰 */
    ctx.save();
    for (let i = 0; i < 4; i++) {
      const kx = -w / 2 + 14 + i * 20;
      const ky = -h / 2 + 9;

      ctx.beginPath();
      ctx.arc(kx, ky, 5, 0, Math.PI * 2);
      ctx.fillStyle = '#0f172a';
      ctx.fill();
      ctx.strokeStyle = 'rgba(148,163,184,0.5)';
      ctx.lineWidth = 1;
      ctx.stroke();

      /* 旋钮指针 */
      ctx.beginPath();
      ctx.moveTo(kx, ky);
      ctx.lineTo(kx, ky - 3.5);
      ctx.strokeStyle = '#38bdf8';
      ctx.lineWidth = 1.4;
      ctx.stroke();
    }
    ctx.restore();

    /* 中间阻值显示 */
    ctx.fillStyle = c.burnedOut ? '#fca5a5' : '#7dd3fc';
    ctx.font = 'bold 14px "Courier New",monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(fmt(c.R, 0) + ' Ω', 0, 8);
  }
  _drawRheostat(ctx, c) {
    const w = 96, h = 30;

    /* 连接线 */
    ctx.strokeStyle = '#475569';
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.moveTo(-48, 0); ctx.lineTo(-w / 2, 0);
    ctx.moveTo(w / 2, 0); ctx.lineTo(48, 0);
    ctx.stroke();

    /* 电阻体 */
    const g = ctx.createLinearGradient(0, -h / 2, 0, h / 2);
    g.addColorStop(0, '#334155');
    g.addColorStop(1, '#0f172a');
    ctx.fillStyle = g;
    roundRect(ctx, -w / 2, -h / 2, w, h, 5);
    ctx.fill();
    ctx.strokeStyle = '#475569';
    ctx.lineWidth = 1.4;
    ctx.stroke();

    /* 电阻丝纹理 */
    ctx.save();
    ctx.strokeStyle = 'rgba(148,163,184,0.35)';
    ctx.lineWidth = 1;
    for (let i = 0; i < 14; i++) {
      const x = -w / 2 + 6 + i * (w - 12) / 13;
      ctx.beginPath();
      ctx.moveTo(x, -h / 2 + 4);
      ctx.lineTo(x, h / 2 - 4);
      ctx.stroke();
    }
    ctx.restore();

    /* 滑片位置 */
    const sx = -w / 2 + 6 + (w - 12) * clamp(c.slider, 0, 1);

    /* 滑片：橙色方块 */
    ctx.save();
    ctx.fillStyle = '#f59e0b';
    roundRect(ctx, sx - 6, -h / 2 - 16, 12, 20, 3);
    ctx.fill();
    ctx.strokeStyle = '#fcd34d';
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.restore();

    /* 阻值显示 */
    ctx.fillStyle = '#fcd34d';
    ctx.font = 'bold 11px system-ui';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(fmt(c.Rtotal * c.slider, 1) + 'Ω', 0, 0);
  }

  _drawBulb(ctx, c) {
    const R = 20;

    ctx.strokeStyle = '#475569';
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.moveTo(-42, 0); ctx.lineTo(-R, 0);
    ctx.moveTo(R, 0);   ctx.lineTo(42, 0);
    ctx.stroke();

    const bright = c.burnedOut ? 0 : Math.max(0, Math.min(1.8, c.brightness));
    if (bright > 0.02) {
      const gr = ctx.createRadialGradient(0, 0, 0, 0, 0, R * 3.2);
      const a = Math.min(1, bright) * 0.55;
      gr.addColorStop(0, `rgba(255,240,150,${a})`);
      gr.addColorStop(0.35, `rgba(255,200,60,${a * 0.5})`);
      gr.addColorStop(1, 'rgba(255,180,0,0)');
      ctx.fillStyle = gr;
      ctx.beginPath();
      ctx.arc(0, 0, R * 3.2, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.beginPath();
    ctx.arc(0, 0, R, 0, Math.PI * 2);
    const bg = ctx.createRadialGradient(-R * 0.3, -R * 0.3, 0, 0, 0, R);
    if (c.burnedOut) {
      bg.addColorStop(0, '#3f3f46');
      bg.addColorStop(1, '#1c1917');
    } else {
      bg.addColorStop(0, `rgba(255,250,220,${0.14 + bright * 0.6})`);
      bg.addColorStop(1, `rgba(120,140,170,${0.12 + bright * 0.25})`);
    }
    ctx.fillStyle = bg;
    ctx.fill();
    ctx.strokeStyle = c.burnedOut ? '#ef4444' : '#64748b';
    ctx.lineWidth = 1.8;
    ctx.stroke();

    ctx.save();
    ctx.strokeStyle = c.burnedOut
      ? '#ef4444'
      : `rgba(255,220,120,${0.5 + bright * 0.5})`;
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    if (c.burnedOut) {
      ctx.moveTo(-8, 6); ctx.lineTo(-3, -2);
      ctx.moveTo(3, 0);  ctx.lineTo(8, 6);
    } else {
      ctx.moveTo(-8, 7);
      ctx.lineTo(-5, -4);
      ctx.lineTo(-1, 4);
      ctx.lineTo(2, -4);
      ctx.lineTo(5, 4);
      ctx.lineTo(8, 7);
    }
    ctx.stroke();
    ctx.restore();

    ctx.fillStyle = '#475569';
    roundRect(ctx, -9, R - 4, 18, 9, 2.5);
    ctx.fill();

    if (c.burnedOut) {
      // 无读数
    } else if (c.P > 0.01) {
      drawLabel(ctx, fmt(c.P, 2) + 'W', 0, -R - 14, {
        color: 'rgba(255,220,120,0.95)'
      });
    }
  }

  _drawCapacitor(ctx, c) {
    const gap = 5, ph = 26;

    ctx.strokeStyle = '#475569';
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.moveTo(-42, 0); ctx.lineTo(-gap, 0);
    ctx.moveTo(gap, 0); ctx.lineTo(42, 0);
    ctx.stroke();

    ctx.fillStyle = '#94a3b8';
    roundRect(ctx, -gap - 4, -ph / 2, 4, ph, 1.5); ctx.fill();
    roundRect(ctx,  gap,     -ph / 2, 4, ph, 1.5); ctx.fill();

    const q = c.Vc * c.C;
    if (Math.abs(q) > 1e-9) {
      ctx.fillStyle = q > 0 ? '#38bdf8' : '#f59e0b';
      ctx.font = 'bold 11px system-ui';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(q > 0 ? '+' : '−', -gap - 12, 0);
      ctx.fillText(q > 0 ? '−' : '+',  gap + 12, 0);
    }

    if (Math.abs(c.V) > 1e-4) {
      drawLabel(ctx, fmt(c.V, 2) + 'V', 0, -ph / 2 - 14, { color: '#a855f7' });
    }
  }

  _drawSwitch(ctx, c) {
    const w = 76;

    ctx.strokeStyle = '#475569';
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.moveTo(-42, 0);   ctx.lineTo(-w / 2, 0);
    ctx.moveTo(w / 2, 0); ctx.lineTo(42, 0);
    ctx.stroke();

    ctx.fillStyle = c.closed ? '#22c55e' : '#64748b';
    ctx.beginPath(); ctx.arc(-w / 2, 0, 5, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc( w / 2, 0, 5, 0, Math.PI * 2); ctx.fill();

    ctx.save();
    ctx.strokeStyle = c.closed ? '#22c55e' : '#94a3b8';
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(-w / 2, 0);
    if (c.closed) ctx.lineTo(w / 2, 0);
    else          ctx.lineTo(w / 2 - 6, -22);
    ctx.stroke();
    ctx.restore();

    ctx.fillStyle = c.closed ? '#22c55e' : '#64748b';
    ctx.font = 'bold 11px system-ui';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(c.closed ? '闭合' : '断开', 0, 32);
  }

  _drawSPDT(ctx, c) {
    // 公共端
    ctx.fillStyle = '#64748b';
    ctx.beginPath(); ctx.arc(-46, 0, 5, 0, Math.PI * 2); ctx.fill();
    // A / B 端点
    ctx.fillStyle = '#64748b';
    ctx.beginPath(); ctx.arc(40, -30, 5, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(40,  30, 5, 0, Math.PI * 2); ctx.fill();

    // 连线
    ctx.strokeStyle = '#475569';
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.moveTo(-46, 0); ctx.lineTo(-30, 0);
    ctx.moveTo(40, -30); ctx.lineTo(60, -30);
    ctx.moveTo(40,  30); ctx.lineTo(60,  30);
    ctx.stroke();

    // 闸刀
    const tx = c.position === 0 ? 40 : 40;
    const ty = c.position === 0 ? -30 : 30;
    ctx.save();
    ctx.strokeStyle = '#22c55e';
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(-30, 0);
    ctx.lineTo(tx - 6, ty);
    ctx.stroke();
    ctx.restore();

    ctx.fillStyle = '#7dd3fc';
    ctx.font = 'bold 10px system-ui';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('A', 66, -30);
    ctx.fillText('B', 66,  30);
    ctx.fillText('C', -56, 0);
  }

  _drawMeter(ctx, c, scene, ch, color) {
    const R = 22;

    ctx.strokeStyle = '#475569';
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.moveTo(-42, 0); ctx.lineTo(-R, 0);
    ctx.moveTo(R, 0);   ctx.lineTo(42, 0);
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(0, 0, R, 0, Math.PI * 2);
    const g = ctx.createRadialGradient(-R * 0.3, -R * 0.3, 0, 0, 0, R);
    g.addColorStop(0, '#1e293b');
    g.addColorStop(1, '#0f172a');
    ctx.fillStyle = g;
    ctx.fill();
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.stroke();

    ctx.fillStyle = color;
    ctx.font = 'bold 18px "Times New Roman", serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(ch, 0, 1);

    if (scene.running) {
      const val = ch === 'A' ? c.I : c.V;
      const txt = fmt(Math.abs(val), ch === 'A' ? 3 : 2) + (ch === 'A' ? 'A' : 'V');
      drawLabel(ctx, txt, 0, -R - 12, { color });
    }

    ctx.fillStyle = '#64748b';
    ctx.font = 'bold 10px system-ui';
    ctx.textAlign = 'center';
    ctx.fillText('+', -R - 8, 4);
    ctx.fillText('−',  R + 8, 4);

    const over = ch === 'A' ? Math.abs(c.I) > c.range : Math.abs(c.V) > c.range;
    if (scene.running && over) {
      ctx.fillStyle = '#ef4444';
      ctx.font = 'bold 10px system-ui';
      ctx.fillText('超量程', 0, R + 16);
    }
  }

  _drawGeneric(ctx, c) {
    ctx.fillStyle = '#334155';
    roundRect(ctx, -30, -20, 60, 40, 6);
    ctx.fill();
    ctx.strokeStyle = '#475569';
    ctx.stroke();
    ctx.fillStyle = '#94a3b8';
    ctx.font = '10px system-ui';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(c.type, 0, 0);
  }
}