/**
 * Battery.js —— 电源
 * 电动势 E + 内阻 r
 * rOverride=null 表示使用当前物理模型的默认内阻。
 */

import { Component, nextComponentId } from './Component.js';
import { clamp } from '../core/Units.js';

export class Battery extends Component {
  static type = 'battery';
  static displayName = '电源';
  static icon = '🔋';
  static category = 'source';
  static PARAM_KEYS = ['E', 'rOverride'];

  constructor(id) {
    super(id ?? nextComponentId('bat'));
    this.terminals = [
      { dx: -42, dy: 0 },   // 正极
      { dx:  42, dy: 0 }    // 负极
    ];
    this.E = 6;              // 电动势 (V)
    this.rOverride = null;   // 内阻覆写 (Ω) 或 null
  }

  netlist(model) {
    if (this.burnedOut) return [{ kind: 'open' }];
    const r = this.rOverride != null
      ? this.rOverride
      : model.numeric.sourceR;
    return [{
      kind: 'vsource',
      a: 0, b: 1,
      E: this.E,
      r: Math.max(0, r)
    }];
  }

  getProps() {
    const model = this.__model ?? null;
    const defaultR = model?.numeric?.sourceR ?? 0.5;
    return [
      {
        key: 'E', label: '电动势', unit: 'V',
        min: 0.5, max: 24, step: 0.1,
        hint: '电源在断路时两端的电压'
      },
      {
        key: 'rOverride', label: '内阻', unit: 'Ω',
        min: 0, max: 20, step: 0.05,
        allowNull: true,
        nullHint: `默认 (${defaultR} Ω)`,
        hint: '设置 0 即理想电源；设为空使用模型默认值'
      }
    ];
  }

  update(dt) {
    this.coolOverload(dt);
  }
}