/**
 * ChartManager.js
 * 原生 SVG 图表渲染。
 *
 * 支持：
 *   - 折线 / 散点
 *   - 线性最小二乘拟合（可选）
 *   - 坐标轴 + 刻度 + 单位
 *   - 数据点提示
 *
 * 数据来源：DataRecorder 里的 Dataset
 */

const NS = 'http://www.w3.org/2000/svg';

function el(tag, attrs = {}) {
  const e = document.createElementNS(NS, tag);
  for (const k in attrs) {
    if (attrs[k] === undefined || attrs[k] === null) continue;
    e.setAttribute(k, String(attrs[k]));
  }
  return e;
}

/* ------------------------------------------------------------------
   线性最小二乘拟合：  y = a + b·x
   返回 { a, b, r2, n }
   ------------------------------------------------------------------ */
export function linearFit(xs, ys) {
  const pts = [];
  for (let i = 0; i < Math.min(xs.length, ys.length); i++) {
    const x = xs[i], y = ys[i];
    if (Number.isFinite(x) && Number.isFinite(y)) pts.push([x, y]);
  }
  const n = pts.length;
  if (n < 2) return { a: 0, b: 0, r2: 0, n };

  let sx = 0, sy = 0, sxx = 0, sxy = 0;
  for (const [x, y] of pts) {
    sx += x; sy += y; sxx += x * x; sxy += x * y;
  }
  const denom = n * sxx - sx * sx;
  const b = Math.abs(denom) < 1e-12 ? 0 : (n * sxy - sx * sy) / denom;
  const a = (sy - b * sx) / n;

  // R²
  const meanY = sy / n;
  let ssTot = 0, ssRes = 0;
  for (const [x, y] of pts) {
    const yHat = a + b * x;
    ssTot += (y - meanY) ** 2;
    ssRes += (y - yHat) ** 2;
  }
  const r2 = ssTot > 1e-15 ? 1 - ssRes / ssTot : 1;

  return { a, b, r2, n };
}

export class ChartManager {
  /**
   * @param {HTMLElement} container
   */
  constructor(container) {
    this.container = container;
    this.charts = new Map();
  }

  /**
   * 绘制一张图
   * @param {string} key    图表标识
   * @param {object} cfg
   *   cfg.title   标题
   *   cfg.dataset  Dataset 实例
   *   cfg.xField   X 字段 key
   *   cfg.yField   Y 字段 key
   *   cfg.mode     'line' | 'scatter' | 'both'
   *   cfg.fit      是否做线性拟合
   *   cfg.xLabel / yLabel  轴标签
   *   cfg.fitLabel 拟合结果显示文本
   */
  plot(key, cfg) {
    if (!this.container) return;
    const wrap = this._getOrCreateCard(key, cfg);
    const svg = wrap.querySelector('svg');
    this._render(svg, cfg);
  }

  _getOrCreateCard(key, cfg) {
    let wrap = this.charts.get(key);
    if (wrap && wrap.isConnected) {
      const t = wrap.querySelector('.chart-title');
      if (t) t.textContent = cfg.title || key;
      return wrap;
    }

    wrap = document.createElement('div');
    wrap.className = 'chart-box';
    wrap.dataset.chartKey = key;

    const title = document.createElement('div');
    title.className = 'chart-title';
    title.textContent = cfg.title || key;
    wrap.appendChild(title);

    const svg = el('svg', {
      viewBox: '0 0 320 200',
      xmlns: NS,
      style: 'display:block;width:100%;height:auto;'
    });
    wrap.appendChild(svg);

    this.container.appendChild(wrap);
    this.charts.set(key, wrap);
    return wrap;
  }

  remove(key) {
    const w = this.charts.get(key);
    if (w && w.isConnected) w.remove();
    this.charts.delete(key);
  }

  clear() {
    for (const w of this.charts.values()) {
      if (w.isConnected) w.remove();
    }
    this.charts.clear();
  }

  /* ---------------- 核心绘图 ---------------- */

  _render(svg, cfg) {
    svg.innerHTML = '';
    const W = 320, H = 200;
    const M = { l: 42, r: 12, t: 14, b: 32 };
    const iw = W - M.l - M.r;
    const ih = H - M.t - M.b;

    const ds = cfg.dataset;
    if (!ds || ds.length === 0) {
      svg.appendChild(el('text', {
        x: W / 2, y: H / 2,
        'text-anchor': 'middle',
        'dominant-baseline': 'middle',
        fill: '#94a3b8',
        'font-size': 12,
        'font-family': 'system-ui'
      })).textContent = '暂无数据';
      return;
    }

    const xs = ds.column(cfg.xField).filter(Number.isFinite);
    const ys = ds.column(cfg.yField).filter(Number.isFinite);
    if (xs.length === 0 || ys.length === 0) return;

    const xMin0 = Math.min(...xs);
    const xMax0 = Math.max(...xs);
    const yMin0 = Math.min(...ys);
    const yMax0 = Math.max(...ys);

    const { xMin, xMax, yMin, yMax, xt, yt } = this._autoScale(xMin0, xMax0, yMin0, yMax0);

    const X = (v) => M.l + (v - xMin) / (xMax - xMin) * iw;
    const Y = (v) => M.t + ih - (v - yMin) / (yMax - yMin) * ih;

    /* ---- 网格 ---- */
    const gGrid = el('g');
    for (const t of xt) {
      gGrid.appendChild(el('line', {
        x1: X(t), y1: M.t, x2: X(t), y2: M.t + ih,
        stroke: 'rgba(56,189,248,0.10)', 'stroke-width': 1
      }));
    }
    for (const t of yt) {
      gGrid.appendChild(el('line', {
        x1: M.l, y1: Y(t), x2: M.l + iw, y2: Y(t),
        stroke: 'rgba(56,189,248,0.10)', 'stroke-width': 1
      }));
    }
    svg.appendChild(gGrid);

    /* ---- 坐标轴 ---- */
    svg.appendChild(el('line', {
      x1: M.l, y1: M.t + ih, x2: M.l + iw, y2: M.t + ih,
      stroke: '#3a4d6b', 'stroke-width': 1.2
    }));
    svg.appendChild(el('line', {
      x1: M.l, y1: M.t, x2: M.l, y2: M.t + ih,
      stroke: '#3a4d6b', 'stroke-width': 1.2
    }));

    /* ---- 刻度 ---- */
    for (const t of xt) {
      svg.appendChild(el('line', {
        x1: X(t), y1: M.t + ih, x2: X(t), y2: M.t + ih + 4,
        stroke: '#3a4d6b', 'stroke-width': 1
      }));
      const tx = el('text', {
        x: X(t), y: M.t + ih + 15,
        'text-anchor': 'middle',
        fill: '#94a3b8', 'font-size': 9.5,
        'font-family': 'system-ui'
      });
      tx.textContent = this._fmtTick(t);
      svg.appendChild(tx);
    }
    for (const t of yt) {
      svg.appendChild(el('line', {
        x1: M.l - 4, y1: Y(t), x2: M.l, y2: Y(t),
        stroke: '#3a4d6b', 'stroke-width': 1
      }));
      const ty = el('text', {
        x: M.l - 6, y: Y(t),
        'text-anchor': 'end',
        'dominant-baseline': 'middle',
        fill: '#94a3b8', 'font-size': 9.5,
        'font-family': 'system-ui'
      });
      ty.textContent = this._fmtTick(t);
      svg.appendChild(ty);
    }

    /* ---- 轴标题 ---- */
    const xLbl = cfg.xLabel || cfg.xField;
    const yLbl = cfg.yLabel || cfg.yField;
    const xT = el('text', {
      x: M.l + iw / 2, y: H - 4,
      'text-anchor': 'middle',
      fill: '#38bdf8', 'font-size': 10.5, 'font-weight': 700,
      'font-family': 'system-ui'
    });
    xT.textContent = xLbl;
    svg.appendChild(xT);

    const yT = el('text', {
      x: 11, y: M.t + ih / 2,
      'text-anchor': 'middle',
      'dominant-baseline': 'middle',
      transform: `rotate(-90 11 ${M.t + ih / 2})`,
      fill: '#38bdf8', 'font-size': 10.5, 'font-weight': 700,
      'font-family': 'system-ui'
    });
    yT.textContent = yLbl;
    svg.appendChild(yT);

    /* ---- 数据点 ---- */
    const pts = [];
    for (const r of ds.rows) {
      const x = r[cfg.xField];
      const y = r[cfg.yField];
      if (Number.isFinite(x) && Number.isFinite(y)) pts.push([x, y]);
    }

    // 折线
    if (cfg.mode === 'line' || cfg.mode === 'both') {
      let d = '';
      for (let i = 0; i < pts.length; i++) {
        const [x, y] = pts[i];
        d += (i === 0 ? 'M' : 'L') + X(x) + ' ' + Y(y) + ' ';
      }
      if (d) {
        svg.appendChild(el('path', {
          d: d.trim(),
          fill: 'none',
          stroke: '#38bdf8',
          'stroke-width': 2,
          'stroke-linejoin': 'round'
        }));
      }
    }

    // 散点
    if (cfg.mode === 'scatter' || cfg.mode === 'both') {
      for (const [x, y] of pts) {
        svg.appendChild(el('circle', {
          cx: X(x), cy: Y(y), r: 3.6,
          fill: '#0d1320',
          stroke: '#38bdf8', 'stroke-width': 2
        }));
      }
    }

    /* ---- 线性拟合 ---- */
    if (cfg.fit && pts.length >= 2) {
      const fit = linearFit(pts.map(p => p[0]), pts.map(p => p[1]));
      const x1 = xMin, x2 = xMax;
      const y1 = fit.a + fit.b * x1;
      const y2 = fit.a + fit.b * x2;
      svg.appendChild(el('line', {
        x1: X(x1), y1: Y(y1), x2: X(x2), y2: Y(y2),
        stroke: '#f59e0b',
        'stroke-width': 2,
        'stroke-dasharray': '6 4'
      }));

      // 拟合结果文字
      const info = cfg.fitFormatter
        ? cfg.fitFormatter(fit)
        : `y = ${fit.a.toFixed(3)} + ${fit.b.toFixed(3)}·x`;
      const ft = el('text', {
        x: M.l + 6, y: M.t + 12,
        fill: '#f59e0b', 'font-size': 10, 'font-weight': 700,
        'font-family': 'system-ui'
      });
      ft.textContent = info;
      svg.appendChild(ft);
    }
  }

  _autoScale(xMin, xMax, yMin, yMax) {
    if (!Number.isFinite(xMin) || !Number.isFinite(xMax)) { xMin = 0; xMax = 1; }
    if (!Number.isFinite(yMin) || !Number.isFinite(yMax)) { yMin = 0; yMax = 1; }

    if (xMin === xMax) { xMin -= 0.5; xMax += 0.5; }
    if (yMin === yMax) { yMin -= 0.5; yMax += 0.5; }

    // 上界取整
    const xRange = this._niceRange(xMin, xMax);
    const yRange = this._niceRange(yMin, yMax, true);

    return {
      xMin: xRange.min, xMax: xRange.max,
      yMin: yRange.min, yMax: yRange.max,
      xt: xRange.ticks, yt: yRange.ticks
    };
  }

  _niceRange(min, max, includeZero = false) {
    if (includeZero && min > 0 && min < max * 0.6) min = 0;
    if (includeZero && max < 0 && max > min * 0.6) max = 0;

    const range = max - min;
    const rough = range / 5;

    const mag = Math.pow(10, Math.floor(Math.log10(rough)));
    const norm = rough / mag;
    let step;
    if (norm <= 1) step = 1;
    else if (norm <= 2) step = 2;
    else if (norm <= 5) step = 5;
    else step = 10;
    step *= mag;

    const nMin = Math.floor(min / step) * step;
    const nMax = Math.ceil(max / step) * step;

    const ticks = [];
    const n = Math.round((nMax - nMin) / step);
    for (let i = 0; i <= n; i++) ticks.push(nMin + step * i);

    return { min: nMin, max: nMax, ticks, step };
  }

  _fmtTick(v) {
    const a = Math.abs(v);
    if (a >= 1e5 || (a > 0 && a < 1e-3)) return v.toExponential(1);
    if (a >= 100) return v.toFixed(0);
    if (a >= 10)  return v.toFixed(1);
    if (a >= 1)   return v.toFixed(2);
    return v.toFixed(3);
  }
}