/**
 * TopologyAnalyzer.js
 * 电气拓扑分析 —— 为 CircuitChecker / ExperimentValidator 提供结构化拓扑信息。
 *
 * 与 CircuitSolver 的区别：
 *   - CircuitSolver 关心"数值解"
 *   - TopologyAnalyzer 关心"连接关系"
 */

import { UnionFind } from './UnionFind.js';

export class TopologyAnalyzer {

  /**
   * @param {import('./CircuitGraph.js').CircuitGraph} graph
   */
  constructor(graph) {
    this.graph = graph;
  }

  /**
   * 完整分析
   * @returns {object}
   */
  analyze(model) {
    const g = this.graph;
    const comps = g.allComponents;
    const nodes = g.buildNodes();
    const nodeOf = nodes.nodeOf;

    /* ---- 1. 元件端子节点表 ---- */
    /** @type {Map<string, number[]>} */
    const compNodes = new Map();
    for (const c of comps) {
      const arr = [];
      for (let i = 0; i < c.terminals.length; i++) arr.push(nodeOf(c.id, i));
      compNodes.set(c.id, arr);
    }

    /* ---- 2. 悬空端子（未接任何导线） ---- */
    const floatingTerminals = [];
    for (const c of comps) {
      for (let i = 0; i < c.terminals.length; i++) {
        if (!g.isConnected(c.id, i)) {
          floatingTerminals.push({ cid: c.id, ti: i, label: c.label });
        }
      }
    }

    /* ---- 3. 电气连通分量（由"参与导通的元件"连接） ---- */
    const uf = new UnionFind();
    for (let i = 0; i < nodes.nodeCount; i++) uf.add(i);

    for (const c of comps) {
      const ns = compNodes.get(c.id);
      if (!ns || ns.length < 2) continue;

      // 断路元件不参与连通（开关断开、烧毁、理想电压表）
      if (!this._isConducting(c, model)) continue;

      for (let i = 1; i < ns.length; i++) uf.union(ns[0], ns[i]);
    }

    /** @type {Map<number, {nodes:Set<number>, comps:Array}>} */
    const islands = new Map();
    for (let i = 0; i < nodes.nodeCount; i++) {
      const r = uf.find(i);
      if (!islands.has(r)) islands.set(r, { nodes: new Set(), comps: [] });
      islands.get(r).nodes.add(i);
    }
    for (const c of comps) {
      const ns = compNodes.get(c.id);
      if (!ns || !ns.length) continue;
      const r = uf.find(ns[0]);
      islands.get(r)?.comps.push(c);
    }

    /* ---- 4. 有源子电路 ---- */
    const poweredIslands = [];
    const idleIslands = [];
    for (const [, isl] of islands) {
      const hasSource = isl.comps.some(c => c.type === 'battery' && !c.burnedOut);
      if (hasSource) poweredIslands.push(isl);
      else idleIslands.push(isl);
    }

    /* ---- 5. 电源信息 ---- */
    const sources = comps.filter(c => c.type === 'battery' && !c.burnedOut);

    /* ---- 6. 负载信息 ---- */
    const loads = comps.filter(c =>
      (c.type === 'resistor' || c.type === 'bulb' || c.type === 'rheostat') && !c.burnedOut
    );

    /* ---- 7. 是否存在闭合回路（每个电源） ---- */
    const closedLoopInfo = sources.map(src => {
      const a = nodeOf(src.id, 0);
      const b = nodeOf(src.id, 1);
      const loopUf = this._buildConductionUf(comps, nodeOf, model);
      return {
        source: src,
        closed: loopUf.connected(a, b)
      };
    });

    return {
      comps,
      compNodes,
      nodeOf,
      nodeCount: nodes.nodeCount,
      floatingTerminals,
      islands,
      poweredIslands,
      idleIslands,
      sources,
      loads,
      closedLoopInfo,

      /** 某元件两端是否在同一电气节点 */
      sameNode(cid, tiA, tiB) {
        return compNodes.get(cid)?.[tiA] === compNodes.get(cid)?.[tiB];
      },

      /** 两个元件端子是否在同一电气节点 */
      nodesEqual(cidA, tiA, cidB, tiB) {
        const na = compNodes.get(cidA)?.[tiA];
        const nb = compNodes.get(cidB)?.[tiB];
        return na !== undefined && na === nb;
      },

      /** 两元件是否直接并联（两端都同节点） */
      inParallel(a, b) {
        const na = compNodes.get(a.id);
        const nb = compNodes.get(b.id);
        if (!na || !nb || na.length < 2 || nb.length < 2) return false;
        return (na[0] === nb[0] && na[1] === nb[1]) ||
               (na[0] === nb[1] && na[1] === nb[0]);
      },

      /** 两元件是否串联（共用恰好一个节点，且各自另一端不同） */
      inSeries(a, b) {
        const na = compNodes.get(a.id);
        const nb = compNodes.get(b.id);
        if (!na || !nb || na.length < 2 || nb.length < 2) return false;
        const share01 = na[0] === nb[0] || na[0] === nb[1] || na[1] === nb[0] || na[1] === nb[1];
        if (!share01) return false;
        // 不能共享两端（那是并联）
        return !((na[0] === nb[0] && na[1] === nb[1]) ||
                 (na[0] === nb[1] && na[1] === nb[0]));
      }
    };
  }

  /**
   * 元件在电气上是否导通
   * @private
   */
  _isConducting(c, model) {
    if (c.burnedOut) return false;

    switch (c.type) {
      case 'switch':
        return !!c.closed;
      case 'spdt':
        return c.position === 0 ? true : true;   // 单刀双掷总有一路通
      case 'voltmeter':
        return Number.isFinite(model.numeric.voltmeterR);
      case 'capacitor':
        return false;   // 直流稳态：电容断路
      default:
        return true;
    }
  }

  /**
   * 构建"电气导通并查集"（用于判断闭合回路）
   * @private
   */
  _buildConductionUf(comps, nodeOf, model) {
    const uf = new UnionFind();

    // 所有端子节点
    for (const c of comps) {
      for (let i = 0; i < c.terminals.length; i++) {
        uf.add(nodeOf(c.id, i));
      }
    }

    // 导线连接
    for (const w of this.graph.wires) {
      uf.union(nodeOf(w.a.cid, w.a.ti), nodeOf(w.b.cid, w.b.ti));
    }

    // 导通元件连接其端子
    for (const c of comps) {
      if (!this._isConducting(c, model)) continue;
      const first = nodeOf(c.id, 0);
      for (let i = 1; i < c.terminals.length; i++) {
        // 滑动变阻器：左-滑片、滑片-右均导通
        uf.union(first, nodeOf(c.id, i));
      }
    }

    return uf;
  }
}