/**
 * ExperimentMode.js
 * 实验模式总控。
 */

import { list, get as getExperiment } from './ExperimentRegistry.js';
import { ExperimentValidator } from './ExperimentValidator.js';
import { ExperimentPanel } from '../ui/ExperimentPanel.js';
import { PropertyPanel } from '../ui/PropertyPanel.js';
import { DataRecorder } from '../data/DataRecorder.js';
import { copyToClipboard, exportDatasetCSV } from '../data/DataExport.js';
import { TopologyAnalyzer } from '../core/TopologyAnalyzer.js';
import { createComponent } from '../components/registry.js';
import { PhysicalModel } from '../core/PhysicalModel.js';
import { linearFit } from '../charts/ChartManager.js';

/* 触发全部实验定义模块的副作用注册 */
import './OhmResistance.js';
import './BulbIV.js';
import './SourceEMF.js';
import './CapacitorRC.js';
import './Resistivity.js';
import './VoltmeterResistance.js';
import './AmmeterResistance.js';

export class ExperimentMode {

  static installed = false;
  static current = null;

  static install(app) {
    if (this.installed) return this.current;
    this.installed = true;
    this.current = new ExperimentMode(app);
    return this.current;
  }

  constructor(app) {
    this.app = app;
    this.currentDef = null;
    this.recorder = new DataRecorder();
    this.lastChartFits = {};
    this.extraResult = {};

    this._initUI();
    this._bindModeSwitch();
  }

  /* ================================================================
     1. UI 初始化
     ================================================================ */

  _initUI() {
    this.panelHost = document.createElement('div');
    this.panelHost.id = 'expPanelHost';
    this.panelHost.style.display = 'none';

    document.querySelector('.body')?.appendChild(this.panelHost);

    this.panel = new ExperimentPanel(this.panelHost);
  }

  /* ================================================================
     2. 模式切换
     ================================================================ */

  _bindModeSwitch() {
    document.querySelectorAll('.tab[data-mode]').forEach(t => {
      t.addEventListener('click', () => {
        const mode = t.dataset.mode;
        setTimeout(() => this._applyMode(mode), 0);
      });
    });

    // 初始
    setTimeout(() => {
      const active = document.querySelector('.tab[data-mode].active');
      this._applyMode(active?.dataset.mode || 'free');
    }, 0);
  }

  _applyMode(mode) {
    const palette = document.getElementById('palette');
    const panel   = document.getElementById('panel');

    if (mode === 'experiment') {
      /* 左侧：实验列表 */
      palette.innerHTML = '';
      this._renderExperimentList(palette);

      /* 右侧：隐藏普通面板，显示实验面板 */
      if (panel) panel.style.display = 'none';
      this.panelHost.style.display = '';

      this.app.ui.setStatus('实验模式 · 请选择一个实验', 'ok');

    } else {
      /* 恢复自由模式 */
      if (panel) panel.style.display = '';
      this.panelHost.style.display = 'none';

      palette.innerHTML = '';
      this.app.__rebuildPalette?.();

      this.app.ui.setStatus('自由搭建模式', 'ok');
    }
  }

  /* ================================================================
     3. 实验列表
     ================================================================ */

  _renderExperimentList(host) {
    host.innerHTML = '';

    const title = document.createElement('div');
    title.className = 'pal-group-title';
    title.textContent = '实验列表';
    host.appendChild(title);

    const exps = list();
    if (exps.length === 0) {
      host.innerHTML += `<div class="empty-tip">暂无实验</div>`;
      return;
    }

    const wrap = document.createElement('div');
    wrap.className = 'exp-list';

    exps.forEach((def, i) => {
      const item = document.createElement('div');
      item.className = 'exp-item';
      item.dataset.expId = def.id;
      item.innerHTML = `<div class="idx">${i + 1}</div>
        <div class="nm">${def.name}</div>`;
      item.addEventListener('click', () => this.loadExperiment(def.id));
      wrap.appendChild(item);
    });

    host.appendChild(wrap);
  }

  /* ================================================================
     4. 加载实验
     ================================================================ */

  loadExperiment(id) {
    const def = getExperiment(id);
    if (!def) return;

    document.querySelectorAll('.exp-item').forEach(el => {
      el.classList.toggle('active', el.dataset.expId === id);
    });

    this.currentDef = def;

    this._resetLab(def);

    this.recorder = new DataRecorder();
    this.recorder.create(def.name, def.fields);
    this.lastChartFits = {};
    this.extraResult = {};
    this.recorder.resetAutoSample();

    this._attachPanel();

    this.app.ui.setStatus(`已加载实验：${def.name} · 请按标准电路图搭接`, 'ok');
  }

  _resetLab(def) {
    const { graph, renderer, selection } = this.app;

    graph.clear();
    selection.clear();

    const setup = def.defaultSetup || [];
    const W = renderer.W, H = renderer.H;

    for (const s of setup) {
      const c = createComponent(s.type);
      if (!c) continue;
      c.x = (s.x ?? 0.5) * W;
      c.y = (s.y ?? 0.5) * H;
      graph.addComponent(c);
    }

    this.app.pushHistory?.();
    this.app.refreshMainPanel?.();
    this.app.refreshPropertyPanel?.();
  }

  /* ================================================================
     5. 面板装配
     ================================================================ */

  _attachPanel() {
    const app = this.app;

    this.panel.setExperiment(this.currentDef, {
      /* ---- 器材参数：把参数渲染到 Tab 内的宿主 ---- */
      renderParams: (container) => {
        const sel = app.selection.selection;
        const c = sel?.kind === 'component' ? sel.obj : null;

        // 用一个临时 PropertyPanel 渲染到指定容器
        const pp = new PropertyPanel(container);
        pp.render(c, PhysicalModel.get(), app.__propHooks);
      },

      /* ---- 实时数据 ---- */
      getLiveData: () => this._collectLiveData(),

      /* ---- 数据 ---- */
      getDataset: () => this.recorder.active,

      onDataDelete: (i) => {
        this.recorder.active?.removeAt(i);
        this._updateFits();
        this.panel.refresh();
      },
      onDataClear: () => {
        this.recorder.active?.clear();
        this.lastChartFits = {};
        this.panel.refresh();
      },
      onDataCopy: async () => {
        const csv = this.recorder.active?.toCSV() || '';
        const ok = await copyToClipboard(csv);
        app.ui.setStatus(ok ? '已复制 CSV 到剪贴板' : '复制失败', ok ? 'ok' : 'err');
      },
      onDataExport: () => {
        exportDatasetCSV(this.recorder.active, `${this.currentDef.name}.csv`);
        app.ui.setStatus('已导出 CSV', 'ok');
      },

      /* ---- 记录 ---- */
      onRecord: () => this._recordOnce(),

      /* ---- 图表 ---- */
      getChartConfigs: () => {
        if (!this.currentDef.charts) return [];
        const ds = this.recorder.active;
        return this.currentDef.charts.map(cfg => ({ ...cfg, dataset: ds }));
      },
      getChartFits: () => this.lastChartFits,
      getExtraResult: () => this.extraResult,

      /* ---- 原理图点击 ---- */
      onSchematicClick: (id) => this._highlightLabBySchematicId(id),

      /* ---- 自定义测量 UI（电阻率专用）---- */
      renderMeasureUI: (container) => {
        if (typeof this.currentDef.renderMeasureUI === 'function') {
          this.currentDef.renderMeasureUI(container, {
            get: (k) => this.extraResult[k],
            set: (k, v) => { this.extraResult[k] = v; }
          });
        }
      }
    });
  }

  /* ================================================================
     6. 选中变化
     ================================================================ */

  onSelectionChange() {
    if (!this.panel || !this.currentDef) return;
    if (this.panel.activeTab === 'params') {
      this.panel.refresh();
    }
  }

  /* ================================================================
     7. 实时数据
     ================================================================ */

  _collectLiveData() {
    const { graph, state } = this.app;
    if (!state.get('running')) return [];

    const items = [];
    const def = this.currentDef;

    if (typeof def.collectLiveData === 'function') {
      const arr = def.collectLiveData({ graph, model: PhysicalModel.get() });
      if (Array.isArray(arr)) return arr;
    }

    /* 通用：显示所有仪表的读数 */
    for (const c of graph.allComponents) {
      if (c.burnedOut) continue;
      if (c.type === 'ammeter') {
        items.push({
          k: '电流表 A',
          v: `${Math.abs(c.I).toFixed(4)} A`,
          cls: c.overRange ? 'danger' : 'acc'
        });
      } else if (c.type === 'voltmeter') {
        items.push({
          k: '电压表 V',
          v: `${Math.abs(c.V).toFixed(3)} V`,
          cls: c.overRange ? 'danger' : 'purple'
        });
      }
    }

    return items;
  }

  /* ================================================================
     8. 记录
     ================================================================ */

  _recordOnce() {
    if (!this.currentDef) return;
    if (!this.app.state.get('running')) {
      this.app.ui.setStatus('请先通电，再记录数据', 'warn');
      return;
    }

    const ds = this.recorder.active;
    if (!ds) return;

    const row = this.currentDef.makeRow?.({
      graph: this.app.graph,
      model: PhysicalModel.get(),
      index: ds.length,
      extra: this.extraResult
    });

    if (!row) {
      this.app.ui.setStatus('当前读数无效，无法记录', 'warn');
      return;
    }

    ds.add(row);
    this._updateFits();

    this.app.ui.setStatus(`已记录第 ${ds.length} 组数据`, 'ok');

    if (this.panel.activeTab === 'data' || this.panel.activeTab === 'chart') {
      this.panel.refresh();
    }
  }

  _updateFits() {
    this.lastChartFits = {};
    const def = this.currentDef;
    const ds = this.recorder.active;
    if (!def || !ds) return;

    for (const cfg of (def.charts || [])) {
      if (!cfg.fit) continue;
      const xs = ds.column(cfg.xField).filter(Number.isFinite);
      const ys = ds.column(cfg.yField).filter(Number.isFinite);
      if (xs.length < 2) continue;
      this.lastChartFits[cfg.key] = linearFit(xs, ys);
    }
  }

  /* ================================================================
     9. 校验
     ================================================================ */

  checkCurrent() {
    if (!this.currentDef) {
      return { ok: false, issues: [{ level: 'info', title: '未选择实验', detail: '' }] };
    }

    const topo = new TopologyAnalyzer(this.app.graph)
      .analyze(PhysicalModel.get());

    const result = ExperimentValidator.validate(
      this.currentDef, this.app.graph, PhysicalModel.get(), topo
    );

    const issues = result.checks.map(c => ({
      level: c.ok ? 'info' : 'danger',
      title: (c.ok ? '✅ ' : '❌ ') + c.name,
      detail: c.msg
    }));

    return { ok: result.pass, issues };
  }

  /* ================================================================
     10. 原理图 ↔ 实验台 联动
     ================================================================ */

  _highlightLabBySchematicId(schId) {
    const map = {
      'sch-E':  'battery',
      'sch-S':  'switch',
      'sch-A':  'ammeter',
      'sch-Rx': 'unknownResistor',
      'sch-R':  'rheostat',
      'sch-V':  'voltmeter',
      'sch-L':  'bulb',
      'sch-R0': 'resistor',
      'sch-C':  'capacitor',
      'sch-W':  'metalWire',
      'sch-K':  'spdt'
    };
    const type = map[schId];
    if (!type) return;

    const targets = this.app.graph.allComponents.filter(c => c.type === type);
    if (targets.length === 1) {
      this.app.selection.selectComponent(targets[0]);
    }
  }

  highlightSchematicFor(comp) {
    if (!comp || !this.currentDef) return;
    const map = {
      battery: 'sch-E',
      switch: 'sch-S',
      ammeter: 'sch-A',
      unknownResistor: 'sch-Rx',
      rheostat: 'sch-R',
      voltmeter: 'sch-V',
      bulb: 'sch-L',
      capacitor: 'sch-C',
      metalWire: 'sch-W',
      spdt: 'sch-K'
    };
    const id = map[comp.type];
    if (id) this.panel.highlightSchematic([id]);
    else this.panel.highlightSchematic([]);
  }

  /* ================================================================
     11. 主循环钩子
     ================================================================ */

  tick(dt, simTime) {
    if (!this.currentDef) return;

    if (this.currentDef.autoSample) {
      const { interval, sampler } = this.currentDef.autoSample;
      this.recorder.autoSample(simTime, interval, () =>
        sampler({
          graph: this.app.graph,
          model: PhysicalModel.get(),
          index: this.recorder.active?.length ?? 0,
          simTime,
          extra: this.extraResult
        })
      );
    }

    if (typeof this.currentDef.tick === 'function') {
      this.currentDef.tick({
        graph: this.app.graph,
        model: PhysicalModel.get(),
        dt, simTime,
        extra: this.extraResult
      });
    }
  }

  onRunStateChange(running) {
    if (!running) {
      this.recorder.resetAutoSample();
    } else {
      this.recorder.resetAutoSample();
    }
  }
}