/**
 * PalettePanel.js
 * 左侧器材库面板。
 */

import { PALETTE_DEF, REGISTRY } from '../components/registry.js';

export class PalettePanel {
  /**
   * @param {HTMLElement} root
   * @param {(type:string)=>void} onAdd
   */
  constructor(root, onAdd) {
    this.root = root;
    this.onAdd = onAdd;
    this.render();
  }

  render() {
    if (!this.root) return;
    this.root.innerHTML = '';

    for (const g of PALETTE_DEF) {
      const wrap = document.createElement('div');
      wrap.className = 'pal-group';

      const title = document.createElement('div');
      title.className = 'pal-group-title';
      title.textContent = g.group;
      wrap.appendChild(title);

      for (const type of g.items) {
        const Cls = REGISTRY[type];
        if (!Cls) continue;

        const btn = document.createElement('div');
        btn.className = 'pal-item';
        btn.dataset.type = type;
        btn.innerHTML = `
          <div class="ico">${Cls.icon}</div>
          <div class="nm">${Cls.displayName}</div>
        `;
        btn.addEventListener('click', () => this.onAdd?.(type));
        wrap.appendChild(btn);
      }
      this.root.appendChild(wrap);
    }
  }
}