/**
 * BulbIV.js
 * 实验 2：小灯泡伏安特性
 *
 * 目标电路：
 *   电源 E — 开关 S — 电流表 A — 小灯泡 L — 滑动变阻器 R — 回到电源
 *   电压表 V 并联在灯泡两端
 *
 * 核心：灯泡的非线性 U-I 特性
 *   - 灯泡电阻随温度变化：冷态 → 热态，电阻上升
 *   - 数据来源是 Bulb 组件真实仿真（含热惯性模型）
 *   - 作图得到非线性伏安曲线
 */

import { register } from './ExperimentRegistry.js';
import { ExperimentValidator } from './ExperimentValidator.js';
import { SchematicRenderer } from '../rendering/SchematicRenderer.js';

/* ------------------------------------------------------------------
   标准电路图
   ------------------------------------------------------------------ */

function buildSchematic() {
  const T = SchematicRenderer.terminalPos;

  const E = { id: 'sch-E', type: 'battery',   x:  80, y: 200, rot: 90, label: 'E',  value: '6 V' };
  const S = { id: 'sch-S', type: 'switch',    x: 180, y:  80, rot: 0,  label: 'S' };
  const A = { id: 'sch-A', type: 'ammeter',   x: 280, y:  80, rot: 0,  label: 'A' };
  const L = { id: 'sch-L', type: 'bulb',      x: 400, y:  80, rot: 0,  label: 'L' };
  const R = { id: 'sch-R', type: 'rheostat',  x: 520, y: 200, rot: 90, label: 'R' };
  const V = { id: 'sch-V', type: 'voltmeter', x: 400, y: 210, rot: 0,  label: 'V' };

  const els = [E, S, A, L, R, V];
  const P = (e, ti) => T(e, ti);
  const w = (id, pts) => ({ id, pts });

  const wires = [
    w('w1', [ P(E,0), { x:  80, y:  80 }, P(S,0) ]),
    w('w2', [ P(S,1), P(A,0) ]),
    w('w3', [ P(A,1), P(L,0) ]),
    w('w4', [ P(L,1), { x: 520, y:  80 }, P(R,0) ]),

    w('w5', [ P(R,2),
              { x: 620, y: 200 },
              { x: 620, y: 320 },
              { x:  80, y: 320 },
              P(E,1) ]),

    w('w6', [ P(L,0), { x: 370, y: 210 }, P(V,0) ]),
    w('w7', [ P(L,1), { x: 430, y: 210 }, P(V,1) ])
  ];

  return { width: 700, height: 360, elements: els, wires };
}

/* ------------------------------------------------------------------
   数据字段
   ------------------------------------------------------------------ */

const FIELDS = [
  { key: 'n',  label: '次数',   digits: 0 },
  { key: 'U',  label: '电压 U', unit: 'V', digits: 3 },
  { key: 'I',  label: '电流 I', unit: 'A', digits: 4 },
  { key: 'R',  label: '电阻 R', unit: 'Ω', digits: 3 },
  { key: 'P',  label: '功率 P', unit: 'W', digits: 4 }
];

/* ------------------------------------------------------------------
   实验定义
   ------------------------------------------------------------------ */

const BulbIV = {
  id: 'bulb-iv',
  name: '小灯泡伏安特性',
  category: '基础电学',

  purpose:
    '测量小灯泡在不同电压下的电流，绘制其伏安特性曲线；' +
    '认识小灯泡电阻随温度（功率）变化导致的非线性特性；' +
    '与定值电阻的线性 U-I 图像进行对比。',

  principle:
    '灯泡灯丝是金属钨，其电阻随温度升高而增大。' +
    '当灯泡两端电压增大时，灯丝温度升高，电阻变大，' +
    '因此 U-I 曲线不再是直线，而是向上弯曲（上凸）。' +
    '通过多组 (U, I) 数据绘制曲线，可以直观展示这一点。',

  equipment: [
    { type: 'battery',   count: 1, label: '电源 E' },
    { type: 'switch',    count: 1, label: '开关 S' },
    { type: 'ammeter',   count: 1, label: '电流表 A' },
    { type: 'voltmeter', count: 1, label: '电压表 V' },
    { type: 'rheostat',  count: 1, label: '滑动变阻器 R' },
    { type: 'bulb',      count: 1, label: '小灯泡 L' }
  ],

  schematic: buildSchematic(),

  defaultSetup: [
    { type: 'battery',   x: 0.20, y: 0.30 },
    { type: 'switch',    x: 0.50, y: 0.20 },
    { type: 'ammeter',   x: 0.75, y: 0.20 },
    { type: 'rheostat',  x: 0.75, y: 0.55 },
    { type: 'bulb',      x: 0.50, y: 0.55 },
    { type: 'voltmeter', x: 0.30, y: 0.75 }
  ],

  fields: FIELDS,

  /* ---------- 校验 ---------- */
  validate({ topo }) {
    const checks = [];

    checks.push(ExperimentValidator.checkCount(topo, 'battery',   1, '电源'));
    checks.push(ExperimentValidator.checkCount(topo, 'switch',    1, '开关'));
    checks.push(ExperimentValidator.checkCount(topo, 'ammeter',   1, '电流表'));
    checks.push(ExperimentValidator.checkCount(topo, 'voltmeter', 1, '电压表'));
    checks.push(ExperimentValidator.checkCount(topo, 'rheostat',  1, '滑动变阻器'));
    checks.push(ExperimentValidator.checkCount(topo, 'bulb',      1, '小灯泡'));

    checks.push(ExperimentValidator.checkClosedLoop(topo));

    const ammeter = topo.comps.find(c => c.type === 'ammeter');
    if (ammeter) {
      const inSeries = topo.comps.some(c =>
        c.id !== ammeter.id &&
        (c.type === 'bulb' || c.type === 'rheostat' ||
         c.type === 'resistor' || c.type === 'unknownResistor') &&
        ExperimentValidator.isSeries(topo, ammeter, c)
      );
      checks.push({
        name: '电流表串联',
        ok: inSeries,
        msg: inSeries ? '电流表已串联在电路中' : '电流表应与灯泡串联'
      });
    }

    const voltmeter = topo.comps.find(c => c.type === 'voltmeter');
    const bulb      = topo.comps.find(c => c.type === 'bulb');
    if (voltmeter && bulb) {
      const ok = ExperimentValidator.isParallel(topo, voltmeter, bulb);
      checks.push({
        name: '电压表并接灯泡',
        ok,
        msg: ok ? '电压表已并联在灯泡两端' : '电压表应并联在灯泡两端'
      });
    }

    return { checks };
  },

  /* ---------- 数据采集 ---------- */
  makeRow(ctx) {
    const { graph, index } = ctx;

    const ammeter = graph.allComponents.find(c => c.type === 'ammeter' && !c.burnedOut);
    const bulb    = graph.allComponents.find(c => c.type === 'bulb'    && !c.burnedOut);

    if (!ammeter || !bulb) return null;

    const voltmeter = graph.allComponents.find(c => c.type === 'voltmeter' && !c.burnedOut);
    const U = voltmeter ? Math.abs(voltmeter.V) : Math.abs(bulb.V);
    const I = Math.abs(ammeter.I);

    if (I < 1e-6) return null;

    const R = U / I;
    const P = U * I;

    return {
      n: index + 1,
      U: +U.toFixed(4),
      I: +I.toFixed(5),
      R: +R.toFixed(4),
      P: +P.toFixed(5)
    };
  },

  /* ---------- 图表 ---------- */
  charts: [
    {
      key: 'ui',
      title: '灯泡伏安特性（U-I 曲线）',
      xField: 'I',
      yField: 'U',
      xLabel: 'I / A',
      yLabel: 'U / V',
      mode: 'both',
      fit: false       // 非线性，不做线性拟合
    },
    {
      key: 'ur',
      title: '电阻随电压变化（R-U 曲线）',
      xField: 'U',
      yField: 'R',
      xLabel: 'U / V',
      yLabel: 'R / Ω',
      mode: 'both',
      fit: false
    }
  ],

  interpret() {
    return {
      title: '实验结论',
      lines: [
        'U-I 曲线向上弯曲（上凸），表明灯泡电阻随温度升高而增大。',
        '电压越高 → 灯丝温度越高 → 电阻越大 → 曲线越陡。',
        '这与定值电阻的线性 U-I 图像形成鲜明对比。'
      ]
    };
  }
};

register(BulbIV);

export default BulbIV;