/**
 * DataPanel.js
 * 数据表格渲染（HTML table）。
 */

export class DataPanel {
  constructor(root) {
    this.root = root;
  }

  /**
   * @param {import('../data/Dataset.js').Dataset} dataset
   * @param {object} hooks { onDelete:(i)=>void, onClear:()=>void, onCopy:()=>void, onExport:()=>void }
   */
  render(dataset, hooks = {}) {
    if (!this.root) return;
    this.root.innerHTML = '';

    if (!dataset) {
      this.root.innerHTML = `<div class="empty-tip">暂无数据集</div>`;
      return;
    }

    /* ---- 工具栏 ---- */
    const bar = document.createElement('div');
    bar.className = 'data-toolbar';
    bar.innerHTML = `
      <span class="data-count">共 ${dataset.length} 组</span>
      <button class="btn ghost" data-act="copy">📋 复制CSV</button>
      <button class="btn ghost" data-act="export">💾 导出</button>
      <button class="btn ghost" data-act="clear">🗑 清空</button>
    `;
    bar.querySelector('[data-act="copy"]').addEventListener('click', () => hooks.onCopy?.());
    bar.querySelector('[data-act="export"]').addEventListener('click', () => hooks.onExport?.());
    bar.querySelector('[data-act="clear"]').addEventListener('click', () => {
      if (dataset.length && confirm('确定清空所有数据吗？')) hooks.onClear?.();
    });
    this.root.appendChild(bar);

    /* ---- 空表 ---- */
    if (dataset.length === 0) {
      const tip = document.createElement('div');
      tip.className = 'empty-tip';
      tip.innerHTML = '暂无数据<br>通电后点击「记录」采集一组';
      this.root.appendChild(tip);
      return;
    }

    /* ---- 表格 ---- */
    const wrap = document.createElement('div');
    wrap.className = 'data-table-wrap';

    const table = document.createElement('table');
    table.className = 'data-table';

    /* 表头 */
    const thead = document.createElement('thead');
    const trh = document.createElement('tr');
    for (const f of dataset.fields) {
      const th = document.createElement('th');
      th.textContent = f.unit ? `${f.label} (${f.unit})` : f.label;
      trh.appendChild(th);
    }
    const thAct = document.createElement('th');
    thAct.textContent = '';
    trh.appendChild(thAct);
    thead.appendChild(trh);
    table.appendChild(thead);

    /* 表体 */
    const tbody = document.createElement('tbody');
    for (let i = 0; i < dataset.rows.length; i++) {
      const r = dataset.rows[i];
      const tr = document.createElement('tr');

      for (const f of dataset.fields) {
        const td = document.createElement('td');
        const v = r[f.key];
        if (v === null || v === undefined) {
          td.textContent = '—';
        } else if (typeof v === 'number') {
          td.textContent = Number.isFinite(v) ? v.toFixed(f.digits ?? 3) : '—';
        } else {
          td.textContent = String(v);
        }
        tr.appendChild(td);
      }

      const tdDel = document.createElement('td');
      const btn = document.createElement('button');
      btn.className = 'data-del';
      btn.textContent = '✕';
      btn.title = '删除此行';
      btn.addEventListener('click', () => hooks.onDelete?.(i));
      tdDel.appendChild(btn);
      tr.appendChild(tdDel);

      tbody.appendChild(tr);
    }
    table.appendChild(tbody);

    wrap.appendChild(table);
    this.root.appendChild(wrap);
  }
}