/**
 * ExperimentRegistry.js
 * 实验注册表。新增实验只需：
 *   1. 新建一个实验定义模块
 *   2. 在此处 register()
 *   3. 不需要修改 CircuitSolver 或任何核心模块
 */

const REGISTRY = new Map();

/**
 * @param {object} def
 *   def.id            唯一 ID
 *   def.name          显示名
 *   def.category      分类（可选）
 *   def.purpose       实验目的
 *   def.principle     实验原理
 *   def.equipment     器材清单 [{type, count, label?}]
 *   def.schematic     标准电路图（SchematicRenderer 格式）
 *   def.defaultSetup  默认实验台初始元件（可选）
 *   def.validate      校验函数 (graph, model) => { pass, checks:[] }
 *   def.fields        数据字段定义
 *   def.makeRow       采集一行的函数 (context) => row | null
 *   def.charts        图表定义 [{key, title, xField, yField, mode, fit, xLabel, yLabel, fitFormatter}]
 *   def.onLoad        实验加载后回调
 */
export function register(def) {
  if (!def || !def.id) throw new Error('Experiment 必须有 id');
  REGISTRY.set(def.id, def);
}

export function get(id) {
  return REGISTRY.get(id) || null;
}

export function list() {
  return [...REGISTRY.values()];
}

export function listByCategory() {
  const map = new Map();
  for (const d of REGISTRY.values()) {
    const c = d.category || '其他';
    if (!map.has(c)) map.set(c, []);
    map.get(c).push(d);
  }
  return map;
}