/**
 * CurrentRenderer.js
 * 电流粒子动画 —— 显示电流方向与相对大小。
 *
 * 注意：粒子只沿"元件支路"或"明确的导线"绘制。
 * 不会对无法确定唯一电流的理想导线伪造电流值。
 */

import { quadPoint, wireSag } from './drawUtils.js';

const MIN_SHOW = 1e-4;   // 小于此电流不绘制

export class CurrentRenderer {
  constructor() {
    this.phase = 0;   // 全局相位（秒）
  }

  step(dt) {
    this.phase += dt;
  }

  /**
   * 在导线上绘制电流粒子
   * @param {CanvasRenderingContext2D} ctx
   * @param {{a:{x,y}, b:{x,y}, current:number}} wire
   */
  drawWireCurrent(ctx, wire) {
    const I = wire.current || 0;
    if (Math.abs(I) < MIN_SHOW) return;

    const a = wire.a, b = wire.b;
    const sag = wireSag(a, b);
    const len = Math.hypot(b.x - a.x, b.y - a.y);
    if (len < 24) return;

    const speed = Math.min(340, Math.max(36, Math.abs(I) * 110));
    const count = Math.min(12, Math.max(2, Math.floor(len / 32)));
    const dir = I > 0 ? 1 : -1;

    ctx.save();
    for (let i = 0; i < count; i++) {
      let u = (this.phase * speed / 200 + i / count) % 1;
      if (u < 0) u += 1;
      if (dir < 0) u = 1 - u;

      const p = quadPoint(a, b, sag, u);
      const alpha = 0.35 + 0.55 * Math.sin(u * Math.PI);

      const g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, 5);
      g.addColorStop(0, `rgba(186,230,253,${alpha})`);
      g.addColorStop(0.4, `rgba(56,189,248,${alpha * 0.85})`);
      g.addColorStop(1, 'rgba(56,189,248,0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(p.x, p.y, 5, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
  }

  /**
   * 在元件两端点之间绘制电流粒子（用于替换"沿导线"的估算）
   * @param {CanvasRenderingContext2D} ctx
   * @param {{x:number,y:number}} a
   * @param {{x:number,y:number}} b
   * @param {number} I
   * @param {string} color
   */
  drawSegment(ctx, a, b, I, color = '#38bdf8') {
    if (Math.abs(I) < MIN_SHOW) return;
    const len = Math.hypot(b.x - a.x, b.y - a.y);
    if (len < 20) return;

    const speed = Math.min(220, Math.max(30, Math.abs(I) * 80));
    const count = Math.min(8, Math.max(2, Math.floor(len / 40)));
    const dir = I > 0 ? 1 : -1;

    ctx.save();
    for (let i = 0; i < count; i++) {
      let u = (this.phase * speed / 200 + i / count) % 1;
      if (u < 0) u += 1;
      if (dir < 0) u = 1 - u;

      const x = a.x + (b.x - a.x) * u;
      const y = a.y + (b.y - a.y) * u;
      const alpha = 0.3 + 0.5 * Math.sin(u * Math.PI);

      ctx.globalAlpha = alpha;
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.arc(x, y, 3.2, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
  }
}