/**
 * Rheostat.js —— 滑动变阻器（三端子）
 * 端子 0：左端  端子 1：右端  端子 2：滑片
 *
 * 内部由两段电阻构成：R_left = R_total * slider
 *                     R_right = R_total * (1 - slider)
 */

import { Component, nextComponentId } from './Component.js';
import { clamp } from '../core/Units.js';

export class Rheostat extends Component {
  static type = 'rheostat';
  static displayName = '滑动变阻器';
  static icon = '⇄';
  static category = 'passive';
  static PARAM_KEYS = ['Rtotal', 'slider', 'ratedPower'];

  constructor(id) {
    super(id ?? nextComponentId('rhe'));
    this.terminals = [
      { dx: -48, dy: 0 },   // 左
      { dx:  48, dy: 0 },   // 右
      { dx:   0, dy: -34 }  // 滑片
    ];
    this.Rtotal = 20;        // 总阻值 (Ω)
    this.slider = 0.5;       // 滑片位置 0..1
    this.ratedPower = 2;     // 额定功率 (W)
  }

  /** 滑片到左端的电阻 */
  get Rleft()  { return Math.max(this.Rtotal * clamp(this.slider, 0, 1), 1e-3); }
  /** 滑片到右端的电阻 */
  get Rright() { return Math.max(this.Rtotal * (1 - clamp(this.slider, 0, 1)), 1e-3); }

  netlist() {
    if (this.burnedOut) return [{ kind: 'open' }];
    return [
      { kind: 'resistor', a: 0, b: 2, R: this.Rleft  },
      { kind: 'resistor', a: 2, b: 1, R: this.Rright }
    ];
  }

  getProps() {
    return [
      { key: 'Rtotal', label: '总阻值', unit: 'Ω', min: 1, max: 200, step: 1 },
      { key: 'slider', label: '滑片位置', unit: '%', min: 0, max: 100, step: 1,
        slider: true, transform: 'percent' },
      { key: 'ratedPower', label: '额定功率', unit: 'W', min: 0.1, max: 20, step: 0.1 }
    ];
  }

  update(dt) { this.coolOverload(dt); }
}