/**
 * OhmResistance.js
 * 实验 1：伏安法测电阻
 *
 * 目标电路：
 *   电源 E — 开关 S — 电流表 A — 待测电阻 Rx — 滑动变阻器 R — 回到电源
 *   电压表 V 并联在 Rx 两端
 *
 * 学生任务：
 *   1. 从器材库取出器材
 *   2. 按标准电路图接线
 *   3. 点击「检查」 → 校验通过
 *   4. 通电 → 调节滑动变阻器 → 多次「记录」
 *   5. 查看 U-I 图 → 斜率即 Rx
 */

import { ExperimentValidator } from './ExperimentValidator.js';
import { register } from './ExperimentRegistry.js';
import { SchematicRenderer } from '../rendering/SchematicRenderer.js';

/* ------------------------------------------------------------------
   标准电路图（教学用）
   ------------------------------------------------------------------ */

function buildSchematic() {
  const T = SchematicRenderer.terminalPos;

  const E  = { id: 'sch-E',  type: 'battery',   x:  80, y: 200, rot: 90, label: 'E',  value: '6 V' };
  const S  = { id: 'sch-S',  type: 'switch',    x: 180, y:  80, rot: 0,  label: 'S' };
  const A  = { id: 'sch-A',  type: 'ammeter',   x: 280, y:  80, rot: 0,  label: 'A' };
  const Rx = { id: 'sch-Rx', type: 'resistor',  x: 400, y:  80, rot: 0,  label: 'Rx', value: '?' };
  const R  = { id: 'sch-R',  type: 'rheostat',  x: 520, y: 200, rot: 90, label: 'R' };
  const V  = { id: 'sch-V',  type: 'voltmeter', x: 400, y: 210, rot: 0,  label: 'V' };

  const els = [E, S, A, Rx, R, V];
  const P = (e, ti) => T(e, ti);
  const w = (id, pts) => ({ id, pts });

  const wires = [
    /* E+ → S → A → Rx 左端 */
    w('w1', [ P(E,0), { x:  80, y:  80 }, P(S,0) ]),
    w('w2', [ P(S,1), P(A,0) ]),
    w('w3', [ P(A,1), P(Rx,0) ]),

    /* Rx 右端 → R 上端（下接线柱 A） */
    w('w4', [ P(Rx,1), { x: 520, y:  80 }, P(R,0) ]),

    /* R 滑片端子（右侧）→ 向右出线 → 绕右下 → 回到 E- */
    w('w5', [ P(R,2),
              { x: 620, y: 200 },
              { x: 620, y: 320 },
              { x:  80, y: 320 },
              P(E,1) ]),

    /* V 并接 Rx */
    w('w6', [ P(Rx,0), { x: 370, y: 210 }, P(V,0) ]),
    w('w7', [ P(Rx,1), { x: 430, y: 210 }, P(V,1) ])
  ];

  return { width: 700, height: 360, elements: els, wires };
}

/* ------------------------------------------------------------------
   数据字段
   ------------------------------------------------------------------ */

const FIELDS = [
  { key: 'n',  label: '次数',   digits: 0 },
  { key: 'U',  label: '电压 U', unit: 'V', digits: 3 },
  { key: 'I',  label: '电流 I', unit: 'A', digits: 4 },
  { key: 'R',  label: '电阻 R', unit: 'Ω', digits: 3 },
  { key: 'P',  label: '功率 P', unit: 'W', digits: 4 }
];

/* ------------------------------------------------------------------
   实验定义
   ------------------------------------------------------------------ */

const UnknownR = {
  id: 'ohm-resistance',
  name: '伏安法测电阻',
  category: '基础电学',

  purpose:
    '学会用电流表和电压表测量未知电阻的阻值；' +
    '理解 R = U/I 的物理含义；' +
    '通过多组数据绘制 U-I 图像，用图像法求电阻。',

  principle:
    '根据欧姆定律 R = U/I，用电压表测出电阻两端电压 U，' +
    '用电流表测出通过电阻的电流 I，即可计算电阻阻值。' +
    '多次改变滑动变阻器接入电阻，得到多组 (U, I)，' +
    '在 U-I 坐标系中描点作图，图线的斜率即为待测电阻 Rx。',

  equipment: [
    { type: 'battery',   count: 1, label: '电源 E' },
    { type: 'switch',    count: 1, label: '开关 S' },
    { type: 'ammeter',   count: 1, label: '电流表 A' },
    { type: 'voltmeter', count: 1, label: '电压表 V' },
    { type: 'rheostat',  count: 1, label: '滑动变阻器 R' },
    { type: 'unknownResistor', count: 1, label: '待测电阻 Rx' }
  ],

  schematic: buildSchematic(),

  /** 学生进入实验后，实验台上预置的器材（未连接） */
  defaultSetup: [
    { type: 'battery',   x: 0.20, y: 0.30 },
    { type: 'switch',    x: 0.50, y: 0.20 },
    { type: 'ammeter',   x: 0.75, y: 0.20 },
    { type: 'rheostat',  x: 0.75, y: 0.55 },
    { type: 'unknownResistor', x: 0.50, y: 0.55 },
    { type: 'voltmeter', x: 0.30, y: 0.75 }
  ],

  fields: FIELDS,

  /* ---------- 校验 ---------- */
  validate({ graph, model, topo }) {
    const checks = [];

    // 1. 电源
    checks.push(ExperimentValidator.checkCount(topo, 'battery', 1, '电源'));

    // 2. 开关
    checks.push(ExperimentValidator.checkCount(topo, 'switch', 1, '开关'));

    // 3. 电流表
    checks.push(ExperimentValidator.checkCount(topo, 'ammeter', 1, '电流表'));

    // 4. 电压表
    checks.push(ExperimentValidator.checkCount(topo, 'voltmeter', 1, '电压表'));

    // 5. 滑动变阻器
    checks.push(ExperimentValidator.checkCount(topo, 'rheostat', 1, '滑动变阻器'));

    // 6. 待测电阻
    checks.push(ExperimentValidator.checkCount(topo, 'unknownResistor', 1, '待测电阻 Rx'));

    // 7. 闭合回路
    checks.push(ExperimentValidator.checkClosedLoop(topo));

    // 8. 电流表串联（不能直接并联在电源两端）
    const ammeter = topo.comps.find(c => c.type === 'ammeter');
    if (ammeter) {
      const inSeries = topo.comps.some(c =>
        c.id !== ammeter.id &&
        (c.type === 'resistor' || c.type === 'unknownResistor' ||
         c.type === 'bulb' || c.type === 'rheostat') &&
        ExperimentValidator.isSeries(topo, ammeter, c)
      );
      checks.push({
        name: '电流表串联',
        ok: inSeries,
        msg: inSeries ? '电流表已串联在电路中' : '电流表应与负载串联'
      });
    }

    // 9. 电压表并联在待测电阻两端
    const voltmeter = topo.comps.find(c => c.type === 'voltmeter');
    const unknownR  = topo.comps.find(c => c.type === 'unknownResistor');
    if (voltmeter && unknownR) {
      const ok = ExperimentValidator.isParallel(topo, voltmeter, unknownR);
      checks.push({
        name: '电压表并接 Rx',
        ok,
        msg: ok ? '电压表已并联在待测电阻两端' : '电压表应并联在待测电阻两端'
      });
    }

    // 10. 滑动变阻器已接入
    const rheo = topo.comps.find(c => c.type === 'rheostat');
    if (rheo) {
      const inCircuit = ExperimentValidator.sameIsland(
        topo, rheo,
        topo.comps.find(c => c.type === 'battery') || rheo
      );
      checks.push({
        name: '滑动变阻器接入',
        ok: inCircuit,
        msg: inCircuit ? '滑动变阻器已接入电路' : '滑动变阻器未接入主回路'
      });
    }

    return { checks };
  },

  /* ---------- 数据采集 ---------- */
  makeRow(ctx) {
    const { graph, index } = ctx;

    const ammeter = graph.allComponents.find(c => c.type === 'ammeter' && !c.burnedOut);
    const unknownR = graph.allComponents.find(c => c.type === 'unknownResistor' && !c.burnedOut);

    if (!ammeter || !unknownR) return null;

    // 使用电压表读数（如果存在）
    const voltmeter = graph.allComponents.find(c => c.type === 'voltmeter' && !c.burnedOut);
    const U = voltmeter ? Math.abs(voltmeter.V) : Math.abs(unknownR.V);
    const I = Math.abs(ammeter.I);

    if (I < 1e-6) return null;

    const R = U / I;
    const P = U * I;

    return {
      n: index + 1,
      U: +U.toFixed(4),
      I: +I.toFixed(5),
      R: +R.toFixed(4),
      P: +P.toFixed(5)
    };
  },

  /* ---------- 图表 ---------- */
  charts: [
    {
      key: 'ui',
      title: 'U-I 图像',
      xField: 'I',
      yField: 'U',
      xLabel: 'I / A',
      yLabel: 'U / V',
      mode: 'scatter',
      fit: true,
      fitFormatter: (f) => {
        // U = a + b·I，理想电阻 a≈0，b=R
        return `U = ${f.a.toFixed(3)} + ${f.b.toFixed(3)}·I  (R² = ${f.r2.toFixed(4)})`;
      }
    }
  ],

  /* ---------- 结果解释 ---------- */
  interpret(chartFits) {
    const fit = chartFits?.ui;
    if (!fit) return null;
    return {
      title: '实验结论',
      lines: [
        `U-I 图线斜率 = ${fit.b.toFixed(3)} Ω`,
        `线性相关系数 R² = ${fit.r2.toFixed(5)}`,
        fit.r2 > 0.99
          ? '数据线性良好，符合欧姆定律'
          : '数据线性较差，请检查接线或增加采样点'
      ]
    };
  }
};

register(UnknownR);

export default UnknownR;