export const PhysicalModel = {
  current: 'junior',

  get() {
    return MODEL_PRESETS[this.current] || MODEL_PRESETS.junior;
  },

  set(id) {
    if (MODEL_PRESETS[id]) {
      this.current = id;
      return true;
    }
    return false;
  },

  list() {
    return Object.values(MODEL_PRESETS);
  },

  /**
   * 返回用于 UI 显示的"理想值描述"
   * @param {string} key
   */
  displayValue(key) {
    return this.get().display[key] ?? '—';
  },

  /**
   * 返回用于求解的数值
   * @param {string} key
   */
  numericValue(key) {
    return this.get().numeric[key];
  }
};