/**
 * Dataset.js
 * 单个数据集 —— 一组字段定义 + 多行数据。
 */

export class Dataset {
  /**
   * @param {string} name
   * @param {Array<{key:string, label:string, unit?:string, digits?:number}>} fields
   */
  constructor(name, fields) {
    this.name = name;
    this.fields = fields.slice();
    this.rows = [];          // Array<object>
    this.meta = {};          // 任意附加信息
    this._listeners = new Set();
  }

  on(fn) {
    this._listeners.add(fn);
    return () => this._listeners.delete(fn);
  }

  _emit() {
    for (const fn of this._listeners) {
      try { fn(this); } catch (e) { console.error(e); }
    }
  }

  /**
   * 追加一行
   * @param {object} row
   * @returns {number} 行索引
   */
  add(row) {
    const r = {};
    for (const f of this.fields) {
      const v = row[f.key];
      r[f.key] = (typeof v === 'number' && Number.isFinite(v)) ? v : (v ?? null);
    }
    this.rows.push(r);
    this._emit();
    return this.rows.length - 1;
  }

  removeAt(i) {
    if (i < 0 || i >= this.rows.length) return false;
    this.rows.splice(i, 1);
    this._emit();
    return true;
  }

  updateAt(i, patch) {
    if (i < 0 || i >= this.rows.length) return false;
    Object.assign(this.rows[i], patch);
    this._emit();
    return true;
  }

  clear() {
    this.rows = [];
    this._emit();
  }

  get length() { return this.rows.length; }

  /**
   * 取某字段一列
   * @param {string} key
   */
  column(key) {
    return this.rows.map(r => r[key]);
  }

  /**
   * 转二维数组（含表头）
   */
  toMatrix(includeHeader = true) {
    const out = [];
    if (includeHeader) {
      out.push(this.fields.map(f => f.unit ? `${f.label}(${f.unit})` : f.label));
    }
    for (const r of this.rows) {
      out.push(this.fields.map(f => {
        const v = r[f.key];
        if (v === null || v === undefined) return '';
        if (typeof v === 'number') {
          return Number.isFinite(v) ? v.toFixed(f.digits ?? 3) : '';
        }
        return String(v);
      }));
    }
    return out;
  }

  toCSV() {
    const m = this.toMatrix(true);
    return m.map(row => row.map(cell => {
      const s = String(cell ?? '');
      return /[,"\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
    }).join(',')).join('\n');
  }

  /** 序列化 */
  serialize() {
    return {
      name: this.name,
      fields: this.fields,
      rows: this.rows,
      meta: this.meta
    };
  }

  static deserialize(data) {
    const d = new Dataset(data.name, data.fields);
    d.rows = (data.rows || []).map(r => ({ ...r }));
    d.meta = data.meta || {};
    return d;
  }
}