/**
 * Voltmeter.js —— 电压表
 * 理想情况 RV → ∞（求解器中不参与 stamp，仅读数由节点电压差给出）。
 */

import { Component, nextComponentId } from './Component.js';

export class Voltmeter extends Component {
  static type = 'voltmeter';
  static displayName = '电压表';
  static icon = 'Ⓥ';
  static category = 'meter';
  static PARAM_KEYS = ['range', 'rOverride'];

  constructor(id) {
    super(id ?? nextComponentId('vol'));
    this.range = 3;         // 量程 (V)
    this.rOverride = null;  // 内阻覆写 (Ω)，null → 使用模型
  }

  netlist(model) {
    if (this.burnedOut) return [{ kind: 'open' }];
    const R = this.rOverride != null
      ? this.rOverride
      : model.numeric.voltmeterR;
    if (!Number.isFinite(R)) return [{ kind: 'open' }];   // 理想电压表 = 断路
    return [{
      kind: 'resistor',
      a: 0, b: 1,
      R: Math.max(R, 1e-3)
    }];
  }

  getProps() {
    return [
      { key: 'range', label: '量程', unit: 'V', min: 0.1, max: 30, step: 0.1 },
      {
        key: 'rOverride', label: '内阻', unit: 'Ω',
        min: 1, max: 1e6, step: 10,
        allowNull: true, nullHint: '模型默认',
        hint: '设为空使用当前物理模型的内阻'
      }
    ];
  }

  get overRange() {
    return Math.abs(this.V) > this.range * 1.001;
  }

  update(dt) { this.coolOverload(dt); }
}