/**
 * SourceEMF.js
 * 实验 3：测电源电动势和内阻
 *
 * 目标电路：
 *   电源 E,r — 开关 S — 电流表 A — 滑动变阻器 R — 回到电源
 *   电压表 V 并联在电源两端（路端电压）
 *
 * 核心：U = E − I·r
 *   改变滑动变阻器，记录多组 (I, U)
 *   用最小二乘拟合 U-I 直线：
 *     纵截距 → 电源电动势 E
 *     斜率   → −r  →  内阻 r = −斜率
 *
 * 注意：结果显示的是"实验测得值"，不是直接读取电源隐藏参数。
 *       但在真实模型下，两者应接近。
 */

import { register } from './ExperimentRegistry.js';
import { ExperimentValidator } from './ExperimentValidator.js';
import { SchematicRenderer } from '../rendering/SchematicRenderer.js';

/* ------------------------------------------------------------------
   标准电路图
   ------------------------------------------------------------------ */

function buildSchematic() {
  const T = SchematicRenderer.terminalPos;

  const E = { id: 'sch-E', type: 'battery',   x:  80, y: 180, rot: 90, label: 'E,r', value: '?' };
  const V = { id: 'sch-V', type: 'voltmeter', x: 200, y: 180, rot: 90, label: 'V' };
  const S = { id: 'sch-S', type: 'switch',    x: 320, y:  80, rot: 0,  label: 'S' };
  const A = { id: 'sch-A', type: 'ammeter',   x: 420, y:  80, rot: 0,  label: 'A' };
  const R = { id: 'sch-R', type: 'rheostat',  x: 560, y:  80, rot: 0,  label: 'R' };

  const els = [E, V, S, A, R];
  const P = (e, ti) => T(e, ti);
  const w = (id, pts) => ({ id, pts });

  const wires = [
    /* E+ → V 上端 */
    w('w1', [ P(E,0), P(V,0) ]),
    /* E- → V 下端 */
    w('w2', [ P(E,1), P(V,1) ]),

    /* E+ 引出 → S → A → R 左端（下接线柱） */
    w('w3', [ P(E,0), { x:  80, y:  80 }, P(S,0) ]),
    w('w4', [ P(S,1), P(A,0) ]),
    w('w5', [ P(A,1), P(R,0) ]),

    /* R 滑片（上接线柱）→ 顶部绕行 → V 下端（= E- 节点） */
    w('w6', [ P(R,2),
              { x: 560, y:  30 },
              { x: 240, y:  30 },
              { x: 240, y: 210 },
              P(V,1) ])
  ];

  return { width: 680, height: 320, elements: els, wires };
}

/* ------------------------------------------------------------------
   数据字段
   ------------------------------------------------------------------ */

const FIELDS = [
  { key: 'n', label: '次数',   digits: 0 },
  { key: 'I', label: '电流 I', unit: 'A', digits: 4 },
  { key: 'U', label: '路端电压 U', unit: 'V', digits: 4 }
];

/* ------------------------------------------------------------------
   实验定义
   ------------------------------------------------------------------ */

const SourceEMF = {
  id: 'source-emf',
  name: '测电源电动势和内阻',
  category: '基础电学',

  purpose:
    '用电流表和电压表测量电源的电动势 E 与内阻 r；' +
    '掌握用 U-I 图像法处理实验数据的方法；' +
    '理解路端电压与电流的关系 U = E − I·r。',

  principle:
    '电源的电动势 E 与内阻 r 满足 U = E − I·r，' +
    '其中 U 为路端电压，I 为通过电源的电流。' +
    '改变外电路电阻（用滑动变阻器），记录多组 (I, U)，' +
    '以 I 为横轴、U 为纵轴作图，得到一条直线：' +
    '纵轴截距为 E，斜率绝对值为 r。',

  equipment: [
    { type: 'battery',   count: 1, label: '电源 E, r' },
    { type: 'switch',    count: 1, label: '开关 S' },
    { type: 'ammeter',   count: 1, label: '电流表 A' },
    { type: 'voltmeter', count: 1, label: '电压表 V' },
    { type: 'rheostat',  count: 1, label: '滑动变阻器 R' }
  ],

  schematic: buildSchematic(),

  defaultSetup: [
    { type: 'battery',   x: 0.20, y: 0.35 },
    { type: 'switch',    x: 0.50, y: 0.20 },
    { type: 'ammeter',   x: 0.75, y: 0.20 },
    { type: 'rheostat',  x: 0.75, y: 0.60 },
    { type: 'voltmeter', x: 0.30, y: 0.75 }
  ],

  fields: FIELDS,

  /* ---------- 校验 ---------- */
  validate({ topo }) {
    const checks = [];

    checks.push(ExperimentValidator.checkCount(topo, 'battery',   1, '电源'));
    checks.push(ExperimentValidator.checkCount(topo, 'switch',    1, '开关'));
    checks.push(ExperimentValidator.checkCount(topo, 'ammeter',   1, '电流表'));
    checks.push(ExperimentValidator.checkCount(topo, 'voltmeter', 1, '电压表'));
    checks.push(ExperimentValidator.checkCount(topo, 'rheostat',  1, '滑动变阻器'));

    checks.push(ExperimentValidator.checkClosedLoop(topo));

    // 电流表串联在干路
    const ammeter = topo.comps.find(c => c.type === 'ammeter');
    const rheo    = topo.comps.find(c => c.type === 'rheostat');
    if (ammeter && rheo) {
      const ok = ExperimentValidator.isSeries(topo, ammeter, rheo);
      checks.push({
        name: '电流表串联',
        ok,
        msg: ok ? '电流表已串联在干路' : '电流表应串联在电路中'
      });
    }

    // 电压表并接电源两端
    const voltmeter = topo.comps.find(c => c.type === 'voltmeter');
    const battery   = topo.comps.find(c => c.type === 'battery');
    if (voltmeter && battery) {
      const ok = ExperimentValidator.isParallel(topo, voltmeter, battery);
      checks.push({
        name: '电压表并接电源',
        ok,
        msg: ok ? '电压表已并联在电源两端' : '电压表应并联在电源两端'
      });
    }

    // 滑动变阻器接入
    if (rheo && battery) {
      const ok = ExperimentValidator.sameIsland(topo, rheo, battery);
      checks.push({
        name: '滑动变阻器接入',
        ok,
        msg: ok ? '滑动变阻器已接入主回路' : '滑动变阻器未接入主回路'
      });
    }

    return { checks };
  },

  /* ---------- 数据采集 ---------- */
  makeRow(ctx) {
    const { graph, index } = ctx;

    const battery   = graph.allComponents.find(c => c.type === 'battery'   && !c.burnedOut);
    const ammeter   = graph.allComponents.find(c => c.type === 'ammeter'   && !c.burnedOut);
    const voltmeter = graph.allComponents.find(c => c.type === 'voltmeter' && !c.burnedOut);

    if (!battery || !ammeter) return null;

    const I = Math.abs(ammeter.I);
    const U = voltmeter ? Math.abs(voltmeter.V) : Math.abs(battery.V);

    if (I < 1e-6) return null;

    return {
      n: index + 1,
      I: +I.toFixed(5),
      U: +U.toFixed(5)
    };
  },

  /* ---------- 图表 ---------- */
  charts: [
    {
      key: 'ui',
      title: 'U-I 图像（U = E − I·r）',
      xField: 'I',
      yField: 'U',
      xLabel: 'I / A',
      yLabel: 'U / V',
      mode: 'scatter',
      fit: true,
      fitFormatter: (f) => {
        // U = a + b·I  →  E = a,  r = -b
        const E = f.a;
        const r = -f.b;
        return `U = ${a_fmt(f.a)} + (${b_fmt(f.b)})·I  ·  E≈${E.toFixed(3)} V, r≈${r.toFixed(3)} Ω`;
      }
    }
  ],

  /* ---------- 结果解释 ---------- */
  interpret(chartFits) {
    const fit = chartFits?.ui;
    if (!fit) return null;
    const E = fit.a;
    const r = -fit.b;
    return {
      title: '实验结论',
      lines: [
        `拟合直线：U = ${E.toFixed(4)} − ${r.toFixed(4)}·I`,
        `纵截距（电动势）E ≈ ${E.toFixed(3)} V`,
        `斜率绝对值（内阻）r ≈ ${r.toFixed(3)} Ω`,
        `线性相关系数 R² = ${fit.r2.toFixed(5)}`
      ]
    };
  }
};

/* 局部格式化工具，避免上文的 a_fmt/b_fmt 未定义 */
function a_fmt(v) { return v.toFixed(3); }
function b_fmt(v) { return v.toFixed(3); }

register(SourceEMF);

export default SourceEMF;