/**
 * Resistor.js —— 定值电阻
 */

import { Component, nextComponentId } from './Component.js';

export class Resistor extends Component {
  static type = 'resistor';
  static displayName = '定值电阻';
  static icon = '▭';
  static category = 'passive';
  static PARAM_KEYS = ['R', 'ratedPower'];

  constructor(id) {
    super(id ?? nextComponentId('res'));
    this.R = 10;             // 阻值 (Ω)
    this.ratedPower = 0.25;  // 额定功率 (W)
  }

  netlist() {
    if (this.burnedOut) return [{ kind: 'open' }];
    return [{
      kind: 'resistor',
      a: 0, b: 1,
      R: Math.max(this.R, 1e-6)
    }];
  }

  getProps() {
    return [
      { key: 'R', label: '阻值', unit: 'Ω', min: 0.1, max: 1000, step: 0.1 },
      { key: 'ratedPower', label: '额定功率', unit: 'W', min: 0.05, max: 20, step: 0.05 }
    ];
  }

  update(dt) { this.coolOverload(dt); }
}