/**
 * registry.js
 * 器材类型注册表 + 工厂。
 */

import { Component, nextComponentId, bumpIdCounter } from './Component.js';
import { Battery }         from './Battery.js';
import { Resistor }        from './Resistor.js';
import { ResistanceBox }   from './ResistanceBox.js';
import { UnknownResistor } from './UnknownResistor.js';
import { MetalWire }       from './MetalWire.js';
import { Rheostat }        from './Rheostat.js';
import { Bulb }            from './Bulb.js';
import { Capacitor }       from './Capacitor.js';
import { Switch }          from './Switch.js';
import { SPDT }            from './SPDT.js';
import { Ammeter }         from './Ammeter.js';
import { Voltmeter }       from './Voltmeter.js';

export const REGISTRY = {
  battery:         Battery,
  resistor:        Resistor,
  resistanceBox:   ResistanceBox,
  unknownResistor: UnknownResistor,
  metalWire:       MetalWire,
  rheostat:        Rheostat,
  bulb:            Bulb,
  capacitor:       Capacitor,
  switch:          Switch,
  spdt:            SPDT,
  ammeter:         Ammeter,
  voltmeter:       Voltmeter
};

/** 器材库分组 */
export const PALETTE_DEF = [
  { group: '电源', items: ['battery'] },
  { group: '元件', items: ['resistor', 'resistanceBox', 'rheostat', 'bulb', 'capacitor'] },
  { group: '控制', items: ['switch', 'spdt'] },
  { group: '仪表', items: ['ammeter', 'voltmeter'] }
];

export function createComponent(type, id) {
  const Cls = REGISTRY[type];
  if (!Cls) return null;
  return new Cls(id);
}

export function componentFromData(data) {
  const c = createComponent(data.type, data.id);
  if (!c) return null;
  c.restore(data);
  const n = parseInt(String(data.id).replace(/[^0-9]/g, ''), 10);
  if (Number.isFinite(n)) bumpIdCounter(n);
  return c;
}

export function isKnownType(t) {
  return !!REGISTRY[t];
}

export { Component, nextComponentId };