/**
 * ExperimentPanel.js
 * 实验模式右侧面板 —— 分 Tab 显示：
 *   [实验说明] [器材参数] [实时数据] [实验数据] [图像]
 *
 * 与 main.js 的双区面板架构配合：
 *   · 自由模式下 #panel 直接显示（含 #propertyPanel + #panelBody）
 *   · 实验模式下 #panel 被隐藏，本面板接管右侧
 *   · 「器材参数」Tab 通过 hooks.renderParams(container) 渲染
 */

import { SchematicRenderer } from '../rendering/SchematicRenderer.js';
import { DataPanel } from './DataPanel.js';
import { ChartManager } from '../charts/ChartManager.js';

export class ExperimentPanel {
  constructor(root) {
    this.root = root;
    this.activeTab = 'guide';
    this.currentDef = null;

    this.schematicRenderer = null;
    this.dataPanel = new DataPanel();
    this.chartManager = null;

    this.hooks = {};
  }

  setExperiment(def, hooks = {}) {
    this.currentDef = def;
    this.hooks = hooks;
    this.activeTab = 'guide';
    this.chartManager?.clear();
    this.render();
  }

  setTab(tab) {
    if (this.activeTab === tab) return;
    this.activeTab = tab;
    this.render();
  }

  /* ---------------- 渲染入口 ---------------- */

  render() {
    if (!this.root) return;
    const def = this.currentDef;

    if (!def) {
      this.root.innerHTML = `<div class="empty-tip">请从左侧选择一个实验</div>`;
      return;
    }

    this.root.innerHTML = '';

    /* Tabs */
    const tabs = document.createElement('div');
    tabs.className = 'tabs';
    const tabDefs = [
      { key: 'guide',  label: '实验说明' },
      { key: 'params', label: '器材参数' },
      { key: 'live',   label: '实时数据' },
      { key: 'data',   label: '实验数据' },
      { key: 'chart',  label: '图像' }
    ];
    for (const t of tabDefs) {
      const btn = document.createElement('button');
      btn.className = 'tab-sm' + (this.activeTab === t.key ? ' active' : '');
      btn.textContent = t.label;
      btn.addEventListener('click', () => this.setTab(t.key));
      tabs.appendChild(btn);
    }
    this.root.appendChild(tabs);

    /* 内容面板 */
    const panel = document.createElement('div');
    panel.className = 'tab-panel active';
    panel.dataset.panel = this.activeTab;
    this.root.appendChild(panel);

    switch (this.activeTab) {
      case 'guide':  this._renderGuide(panel, def); break;
      case 'params': this._renderParams(panel, def); break;
      case 'live':   this._renderLive(panel, def); break;
      case 'data':   this._renderData(panel, def); break;
      case 'chart':  this._renderChart(panel, def); break;
    }
  }

  /* ---------------- 实验说明 ---------------- */

  _renderGuide(panel, def) {
    const c1 = document.createElement('div');
    c1.className = 'card';
    c1.innerHTML = `<div class="card-title">实验目的</div>
      <div class="exp-text">${def.purpose || ''}</div>`;
    panel.appendChild(c1);

    const c2 = document.createElement('div');
    c2.className = 'card';
    c2.innerHTML = `<div class="card-title">实验原理</div>
      <div class="exp-text">${def.principle || ''}</div>`;
    panel.appendChild(c2);

    const c3 = document.createElement('div');
    c3.className = 'card';
    c3.innerHTML = `<div class="card-title">实验器材</div>`;
    for (const e of (def.equipment || [])) {
      const row = document.createElement('div');
      row.className = 'row';
      row.innerHTML = `<span class="k">${e.label || e.type}</span>
        <span class="v">× ${e.count ?? 1}</span>`;
      c3.appendChild(row);
    }
    panel.appendChild(c3);

    const c4 = document.createElement('div');
    c4.className = 'card';
    c4.innerHTML = `<div class="card-title">标准电路图</div>`;
    const box = document.createElement('div');
    box.className = 'schematic-box';
    c4.appendChild(box);
    panel.appendChild(c4);

    requestAnimationFrame(() => {
      if (!this.schematicRenderer) {
        this.schematicRenderer = new SchematicRenderer(box);
        this.schematicRenderer.onElementClick = (id) => {
          this.hooks.onSchematicClick?.(id);
        };
      } else {
        this.schematicRenderer.container = box;
      }
      this.schematicRenderer.render(def.schematic, { interactive: true });
    });
  }

  /* ---------------- 器材参数 ---------------- */

  _renderParams(panel, def) {
    const c = document.createElement('div');
    c.className = 'card';
    c.innerHTML = `<div class="card-title">器材参数</div>`;

    const host = document.createElement('div');
    host.className = 'params-host';
    c.appendChild(host);
    panel.appendChild(c);

    /* 交给 ExperimentMode 渲染（内部会 new 一个 PropertyPanel） */
    if (typeof this.hooks.renderParams === 'function') {
      this.hooks.renderParams(host);
    } else {
      host.innerHTML = `<div class="empty-tip">点击实验台上的元件查看参数</div>`;
    }
  }

  /* ---------------- 实时数据 ---------------- */

  _renderLive(panel, def) {
    const items = this.hooks.getLiveData?.() || [];

    const c = document.createElement('div');
    c.className = 'card';
    c.innerHTML = `<div class="card-title">实时读数</div>`;

    if (items.length === 0) {
      c.insertAdjacentHTML('beforeend',
        `<div class="empty-tip">电路未通电<br>点击「通电」开始测量</div>`);
    } else {
      for (const it of items) {
        const row = document.createElement('div');
        row.className = 'row';
        row.innerHTML = `<span class="k">${it.k}</span>
          <span class="v ${it.cls || ''}">${it.v}</span>`;
        c.appendChild(row);
      }
    }
    panel.appendChild(c);

    /* 采集按钮 */
    const c2 = document.createElement('div');
    c2.className = 'card';
    c2.innerHTML = `
      <div class="card-title">数据采集</div>
      <button class="btn primary" id="expRecordBtn" style="width:100%">📌 记录当前数据</button>
    `;
    panel.appendChild(c2);

    c2.querySelector('#expRecordBtn').addEventListener('click', () => {
      this.hooks.onRecord?.();
    });

    /* 自定义测量区（电阻率等实验需要） */
    if (typeof this.hooks.renderMeasureUI === 'function') {
      const c3 = document.createElement('div');
      c3.className = 'card';
      c3.innerHTML = `<div class="card-title">测量工具</div>`;
      panel.appendChild(c3);
      this.hooks.renderMeasureUI(c3);
    }
  }

  /* ---------------- 实验数据 ---------------- */

  _renderData(panel, def) {
    const box = document.createElement('div');
    box.className = 'card';
    panel.appendChild(box);

    const title = document.createElement('div');
    title.className = 'card-title';
    title.textContent = '数据记录';
    box.appendChild(title);

    const tableHost = document.createElement('div');
    box.appendChild(tableHost);

    this.dataPanel = new DataPanel(tableHost);
    this.dataPanel.render(this.hooks.getDataset?.(), {
      onDelete: (i) => this.hooks.onDataDelete?.(i),
      onClear:  () => this.hooks.onDataClear?.(),
      onCopy:   () => this.hooks.onDataCopy?.(),
      onExport: () => this.hooks.onDataExport?.()
    });
  }

  /* ---------------- 图像 ---------------- */

  _renderChart(panel, def) {
    const host = document.createElement('div');
    host.className = 'chart-host';
    panel.appendChild(host);

    if (!this.chartManager) {
      this.chartManager = new ChartManager(host);
    } else {
      this.chartManager.container = host;
      this.chartManager.charts.clear();
    }

    const configs = this.hooks.getChartConfigs?.() || [];
    if (configs.length === 0) {
      host.innerHTML = `<div class="empty-tip">该实验暂无图像定义</div>`;
      return;
    }

    for (const cfg of configs) {
      this.chartManager.plot(cfg.key, cfg);
    }

    const fits = this.hooks.getChartFits?.();
    if (fits && def.interpret) {
      const info = def.interpret(fits, this.hooks.getExtraResult?.() || {});
      if (info) {
        const card = document.createElement('div');
        card.className = 'card';
        card.innerHTML = `<div class="card-title">${info.title}</div>`;
        for (const line of info.lines) {
          const p = document.createElement('div');
          p.className = 'exp-text';
          p.textContent = line;
          card.appendChild(p);
        }
        panel.appendChild(card);
      }
    }
  }

  /* ---------------- 外部钩子 ---------------- */

  refresh() { this.render(); }

  refreshCharts() {
    if (this.activeTab !== 'chart') return;
    if (!this.chartManager) return;
    const configs = this.hooks.getChartConfigs?.() || [];
    for (const cfg of configs) {
      this.chartManager.plot(cfg.key, cfg);
    }
  }

  highlightSchematic(ids) {
    this.schematicRenderer?.highlight(ids);
  }
}