/**
 * UnknownResistor.js —— 待测电阻（隐藏真实阻值）
 *
 * 学生看不到 R 值，实验数据由真实电路计算产生。
 * 教师模式可以看到并修改 hiddenR。
 */

import { Resistor } from './Resistor.js';
import { nextComponentId } from './Component.js';

export class UnknownResistor extends Resistor {
  static type = 'unknownResistor';
  static displayName = '待测电阻';
  static icon = '❓';
  static category = 'passive';

  constructor(id) {
    super(id ?? nextComponentId('rx'));

    // 真实阻值（隐藏）
    this.hiddenR = 8.72;
    this.R = this.hiddenR;

    // 标记：UI 不显示、不可编辑
    this.isUnknown = true;

    // 判定用：实验中的"被测对象"
    this.isTarget = true;
  }

  /** 覆盖：默认不暴露参数面板 */
  getProps() {
    return [];
  }

  netlist(model) {
    // 每次以 hiddenR 为准，防止外部意外改写
    this.R = this.hiddenR;
    return super.netlist(model);
  }
}