/**
 * PropertyPanel.js
 * 选中元件后的【器材参数】编辑面板。
 *
 * 支持：
 *   - number 输入（含单位）
 *   - 滑块辅助
 *   - 布尔开关
 *   - 下拉选择
 *   - 恢复默认值
 *   - 单位换算（transform: 'percent' | 'uF' | ...）
 */

import { fmt, clamp } from '../core/Units.js';

const TRANSFORMS = {
  percent: {
    toDisplay: (v) => v * 100,
    toStore:   (v) => v / 100,
    fmt: (v) => Math.round(v) + ' %'
  },
  uF: {
    toDisplay: (v) => v * 1e6,
    toStore:   (v) => v * 1e-6,
    fmt: (v) => fmt(v, 1) + ' μF'
  },
  kΩ: {
    toDisplay: (v) => v / 1000,
    toStore:   (v) => v * 1000,
    fmt: (v) => fmt(v, 2) + ' kΩ'
  }
};

export class PropertyPanel {
  /**
   * @param {HTMLElement} root
   */
  constructor(root) {
    this.root = root;
    this.current = null;   // 当前编辑的元件
  }

  /**
   * 渲染参数面板
   * @param {import('../components/Component.js').Component} c
   * @param {object} model
   * @param {object} hooks { onChange:(comp,key,val)=>void, onReset:(comp,key)=>void }
   */
  render(c, model, hooks = {}) {
    this.current = c;
    if (!this.root) return;
    this.root.innerHTML = '';

    if (!c) {
      this.root.innerHTML = `<div class="empty-tip">未选中元件<br>点击实验台上的元件查看参数</div>`;
      return;
    }

    // 标题
    const title = document.createElement('div');
    title.className = 'card-title';
    title.textContent = `${c.label} · 参数`;
    this.root.appendChild(title);

    // 运行量
    this._appendRuntime(c);

    // 参数
    const props = c.getProps();
    if (props.length === 0) {
      const tip = document.createElement('div');
      tip.className = 'empty-tip';
      tip.textContent = '该元件无可调参数';
      this.root.appendChild(tip);
      return;
    }

    for (const p of props) {
      this._appendProp(c, p, model, hooks);
    }
  }

  _appendRuntime(c) {
    const rows = [
      ['电流 I', fmt(c.I, 4), 'acc'],
      ['电压 U', fmt(c.V, 3), 'acc'],
      ['功率 P', fmt(c.P, 3), '']
    ];
    for (const [k, v, cls] of rows) {
      const row = document.createElement('div');
      row.className = 'row';
      row.innerHTML = `<span class="k">${k}</span><span class="v ${cls}">${v}</span>`;
      this.root.appendChild(row);
    }
  }

  _appendProp(c, p, model, hooks) {
    const wrap = document.createElement('div');
    wrap.className = 'prop-row';

    const raw = c[p.key];
    const tf = p.transform ? TRANSFORMS[p.transform] : null;
    const displayVal = tf ? tf.toDisplay(raw) : raw;

    /* -------- label + 当前值 -------- */
    const head = document.createElement('div');
    head.className = 'prop-head';
    const valText = this._formatValue(p, displayVal);
    head.innerHTML = `
      <span class="k">${p.label}</span>
      <span class="v">${valText}</span>
    `;
    wrap.appendChild(head);

    /* -------- 输入控件 -------- */
    if (p.type === 'bool') {
      wrap.appendChild(this._makeBoolInput(c, p, hooks));
    } else if (p.type === 'select') {
      wrap.appendChild(this._makeSelectInput(c, p, hooks));
    } else {
      wrap.appendChild(this._makeNumberInput(c, p, displayVal, tf, hooks));
    }

    if (p.hint) {
      const hint = document.createElement('div');
      hint.className = 'prop-hint';
      hint.textContent = p.hint;
      wrap.appendChild(hint);
    }

    this.root.appendChild(wrap);
  }

  _formatValue(p, v) {
    if (v === null || v === undefined) {
      return p.nullHint ?? '—';
    }
    if (p.transform === 'percent') return Math.round(v) + ' %';
    if (p.transform === 'uF')      return fmt(v, 1) + ' μF';
    if (typeof v === 'number')     return fmt(v, 2) + (p.unit ? ' ' + p.unit : '');
    return String(v);
  }

  /* ---------- 数字输入 ---------- */
  _makeNumberInput(c, p, displayVal, tf, hooks) {
    const box = document.createElement('div');
    box.className = 'prop-input-wrap';

    const input = document.createElement('input');
    input.type = 'number';
    input.className = 'prop-input';
    input.step = p.step ?? 'any';
    if (p.min != null) input.min = p.min;
    if (p.max != null) input.max = p.max;
    input.value = displayVal != null ? this._roundForInput(displayVal) : '';
    if (p.allowNull) input.placeholder = p.nullHint ?? '默认';

    const unit = document.createElement('div');
    unit.className = 'prop-unit';
    unit.textContent = p.unit ?? '';

    const reset = document.createElement('button');
    reset.className = 'prop-reset';
    reset.title = '恢复默认值';
    reset.textContent = '↺';

    const commit = () => {
      let v = input.value.trim();
      let num;

      if (v === '') {
        if (p.allowNull) {
          c[p.key] = null;
          hooks.onChange?.(c, p.key, null);
          input.classList.remove('invalid');
          return;
        }
        num = p.min ?? 0;
      } else {
        num = Number(v);
      }

      if (!Number.isFinite(num)) {
        input.classList.add('invalid');
        return;
      }

      if (p.min != null) num = Math.max(p.min, num);
      if (p.max != null) num = Math.min(p.max, num);

      const stored = tf ? tf.toStore(num) : num;
      c[p.key] = stored;
      hooks.onChange?.(c, p.key, stored);
      input.classList.remove('invalid');
    };

    input.addEventListener('change', commit);
    input.addEventListener('blur', commit);
    input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') { commit(); input.blur(); }
    });

    reset.addEventListener('click', () => {
      // 重建一个"默认实例"取默认值
      const Cls = c.constructor;
      const def = new Cls('__default__');
      const dv = def[p.key];
      c[p.key] = dv;
      const dDisplay = tf ? tf.toDisplay(dv) : dv;
      input.value = dDisplay != null ? this._roundForInput(dDisplay) : '';
      hooks.onReset?.(c, p.key);
      hooks.onChange?.(c, p.key, dv);
    });

    box.appendChild(input);
    box.appendChild(unit);
    box.appendChild(reset);

    // 滑块辅助
    if (p.slider || p.transform === 'percent') {
      const slider = document.createElement('input');
      slider.type = 'range';
      slider.className = 'prop-range';
      slider.min = p.min ?? 0;
      slider.max = p.max ?? 100;
      slider.step = p.step ?? 1;
      slider.value = displayVal ?? 0;

      slider.addEventListener('input', () => {
        const v = Number(slider.value);
        const stored = tf ? tf.toStore(v) : v;
        c[p.key] = stored;
        input.value = this._roundForInput(v);
        hooks.onChange?.(c, p.key, stored);
      });

      box.style.flexWrap = 'wrap';
      box.appendChild(slider);
    }

    return box;
  }

  _roundForInput(v) {
    if (!Number.isFinite(v)) return '';
    if (Math.abs(v) < 1e-4) return '0';
    if (Math.abs(v) >= 1e6) return v.toExponential(3);
    return String(parseFloat(v.toFixed(4)));
  }

  /* ---------- 布尔 ---------- */
  _makeBoolInput(c, p, hooks) {
    const wrap = document.createElement('div');
    wrap.className = 'prop-input-wrap';

    const btn = document.createElement('button');
    btn.className = 'btn';
    btn.style.flex = '1';
    const refresh = () => {
      btn.textContent = c[p.key] ? '已闭合 ✓' : '已断开 ✗';
      btn.style.borderColor = c[p.key] ? 'rgba(34,197,94,.5)' : '';
      btn.style.color = c[p.key] ? 'var(--ok)' : '';
    };
    refresh();

    btn.addEventListener('click', () => {
      c[p.key] = !c[p.key];
      refresh();
      hooks.onChange?.(c, p.key, c[p.key]);
    });

    wrap.appendChild(btn);
    return wrap;
  }

  /* ---------- 下拉 ---------- */
  _makeSelectInput(c, p, hooks) {
    const wrap = document.createElement('div');
    wrap.className = 'prop-input-wrap';

    const sel = document.createElement('select');
    sel.className = 'prop-input';
    for (const opt of (p.options || [])) {
      const o = document.createElement('option');
      o.value = String(opt.value);
      o.textContent = opt.label;
      sel.appendChild(o);
    }
    sel.value = String(c[p.key]);

    sel.addEventListener('change', () => {
      let v = sel.value;
      const numV = Number(v);
      if (Number.isFinite(numV) && /^-?\d+(\.\d+)?$/.test(v)) v = numV;
      c[p.key] = v;
      hooks.onChange?.(c, p.key, v);
    });

    wrap.appendChild(sel);
    return wrap;
  }

  /** 外部状态变化后刷新数值显示 */
  refresh() {
    // 简化：整块重绘由调用方负责
  }
}