/**
 * Units.js
 * 单位、数值格式化与解析。
 * 教学显示值与数值计算值在此统一处理，避免出现 Infinity / NaN 直接进入 UI。
 */

export const UNIT = {
  V: 'V',
  A: 'A',
  MA: 'mA',
  OHM: 'Ω',
  KOHM: 'kΩ',
  W: 'W',
  F: 'F',
  MF: 'mF',
  UF: 'μF',
  S: 's',
  MS: 'ms',
  M: 'm',
  MM: 'mm',
  J: 'J',
  C: 'C'
};

/**
 * 安全数值格式化。
 * @param {number} v
 * @param {number} digits 小数位
 * @returns {string}
 */
export function fmt(v, digits = 2) {
  if (v === null || v === undefined) return '—';
  if (typeof v !== 'number' || !Number.isFinite(v)) {
    if (v === Infinity) return '∞';
    if (v === -Infinity) return '-∞';
    return '—';
  }
  const a = Math.abs(v);
  if (a < 1e-9) return '0';
  if (a >= 1e6) return v.toExponential(2);
  return v.toFixed(digits);
}

/**
 * 紧凑格式化（自动选择单位前缀）
 * @param {number} v
 * @param {string} unit
 */
export function fmtUnit(v, unit = '', digits = 2) {
  if (v === null || v === undefined) return '—';
  if (typeof v !== 'number' || !Number.isFinite(v)) {
    if (v === Infinity) return '∞ ' + unit;
    return '—';
  }
  const a = Math.abs(v);
  if (a >= 1e6) return v.toExponential(2) + ' ' + unit;
  if (a >= 1e3) return (v / 1e3).toFixed(digits) + ' k' + unit;
  if (a > 0 && a < 1e-3) return (v * 1e6).toFixed(digits) + ' μ' + unit;
  if (a > 0 && a < 1) return (v * 1e3).toFixed(digits) + ' m' + unit;
  return v.toFixed(digits) + (unit ? ' ' + unit : '');
}

/**
 * 数值裁剪（含非法值保护）
 */
export function safeNum(v, fallback = 0) {
  return (typeof v === 'number' && Number.isFinite(v)) ? v : fallback;
}

/**
 * 将数值限制在 [min, max]
 */
export function clamp(v, min, max) {
  if (!Number.isFinite(v)) return min;
  return v < min ? min : (v > max ? max : v);
}

/**
 * 解析带单位前缀的字符串： "4.7k" -> 4700
 * @param {string} str
 * @param {string} baseUnit
 * @returns {number|null}
 */
export function parseUnitString(str, baseUnit = '') {
  if (typeof str !== 'string') return null;
  let s = str.trim().replace(/\s+/g, '');
  if (!s) return null;

  // 去掉尾随单位
  const lower = s.toLowerCase();
  const unitLc = baseUnit.toLowerCase();
  if (unitLc && lower.endsWith(unitLc)) {
    s = s.slice(0, s.length - unitLc.length);
  }

  // 前缀
  const prefixes = [
    { p: 'meg', m: 1e6 },
    { p: 'k',   m: 1e3 },
    { p: 'm',   m: 1e-3 },
    { p: 'u',   m: 1e-6 },
    { p: 'μ',   m: 1e-6 },
    { p: 'n',   m: 1e-9 },
    { p: 'p',   m: 1e-12 }
  ];

  let mult = 1;
  for (const { p, m } of prefixes) {
    if (s.toLowerCase().endsWith(p) && s.length > p.length) {
      // 'm' 有歧义：只在后面是数字时视为前缀
      const head = s.slice(0, s.length - p.length);
      if (/^-?\d*\.?\d+$/.test(head)) {
        mult = m;
        s = head;
        break;
      }
    }
  }

  const n = Number(s);
  return Number.isFinite(n) ? n * mult : null;
}

/**
 * 判断两个浮点数是否近似相等
 */
export function approx(a, b, eps = 1e-9) {
  return Math.abs(a - b) <= eps * Math.max(1, Math.abs(a), Math.abs(b));
}