/**
 * ModalManager.js
 * 通用弹窗（帮助、实验说明、错误详情）。
 */

export class ModalManager {
  constructor(maskId = 'modalMask', boxId = 'modalBox') {
    this.mask = document.getElementById(maskId);
    this.box  = document.getElementById(boxId);

    if (!this.mask || !this.box) return;

    this.mask.addEventListener('click', (e) => {
      if (e.target === this.mask) this.close();
    });

    this._keyHandler = (e) => {
      if (e.key === 'Escape') this.close();
    };
    window.addEventListener('keydown', this._keyHandler);
  }

  /**
   * @param {object} opts
   * @param {string} opts.title
   * @param {string} opts.html
   * @param {string} [opts.confirmText]
   * @param {Function} [opts.onConfirm]
   */
  open({ title, html, confirmText = '明白了', onConfirm }) {
    if (!this.box) return;

    this.box.innerHTML = `
      <h2>${title}</h2>
      <div class="content">${html}</div>
      <button class="modal-close" id="modalConfirmBtn">${confirmText}</button>
    `;

    const btn = this.box.querySelector('#modalConfirmBtn');
    btn.addEventListener('click', () => {
      this.close();
      onConfirm?.();
    });

    this.mask.classList.add('show');
  }

  close() {
    this.mask?.classList.remove('show');
  }

  isOpen() {
    return this.mask?.classList.contains('show');
  }
}