/**
 * Component.js
 * 所有器材的基类。
 *
 * 关键契约（供 CircuitSolver 使用）：
 *   netlist(model, dt) 返回一个"支路数组"，每项形如：
 *     { kind:'resistor',  a:端子索引, b:端子索引, R }
 *     { kind:'vsource',   a:端子索引, b:端子索引, E, r }   // a 为正极
 *     { kind:'capacitor', a:端子索引, b:端子索引, C, Vprev }
 *     { kind:'open' }                                       // 显式断路
 *
 * 说明：
 *   - netlist 描述"电气行为"，不描述视觉。
 *   - 一个元件可以返回多条支路（例如滑动变阻器返回两段电阻）。
 *   - 元件内部的所有物理量用 SI 单位（V/A/Ω/F/W）。
 */

import { clamp } from '../core/Units.js';

let __idCounter = 0;

/** 生成新 ID */
export function nextComponentId(prefix = 'c') {
  return prefix + (++__idCounter);
}

/** 恢复 ID 计数器（反序列化时用） */
export function bumpIdCounter(maxId) {
  if (Number.isFinite(maxId) && maxId > __idCounter) __idCounter = maxId;
}

export function currentIdCounter() { return __idCounter; }

export class Component {

  /** 子类必须覆写 */
  static type = 'component';
  static displayName = '元件';
  static icon = '□';
  static category = 'misc';
  /** 需要序列化的自有属性名 */
  static PARAM_KEYS = [];

  constructor(id) {
    this.id = id ?? nextComponentId();
    this.x = 0;
    this.y = 0;

    /** 端子相对坐标（相对元件中心） */
    this.terminals = [
      { dx: -40, dy: 0 },
      { dx:  40, dy: 0 }
    ];

    /* ---- 状态 ---- */
    this.state = 'normal';        // normal | overload | burned | ...
    this.burnedOut = false;
    this.overloadTime = 0;

    /* ---- 运行量（每步求解后写回） ---- */
    this.I = 0;    // 电流（A，从端子 0 流入为正）
    this.V = 0;    // 端电压（V，V(0) - V(1)）
    this.P = 0;    // 功率（W）
  }

  /* ---------------- 基础 ---------------- */

  get type()    { return this.constructor.type; }
  get label()   { return this.constructor.displayName; }
  get icon()    { return this.constructor.icon; }

  /** 端子绝对坐标 */
  termPos(i) {
    const t = this.terminals[i];
    if (!t) return { x: this.x, y: this.y };
    return { x: this.x + t.dx, y: this.y + t.dy };
  }

  /** 端子个数 */
  get terminalCount() { return this.terminals.length; }

  /* ---------------- 电气行为 ---------------- */

  /**
   * 返回网表支路数组。
   * @param {object} model  PhysicalModel.get()
   * @param {number} dt     时间步长（s），用于电容
   * @returns {Array<object>}
   */
  netlist(model, dt) {   // eslint-disable-line no-unused-vars
    return [{ kind: 'open' }];
  }

  /* ---------------- 参数面板 ---------------- */

  /**
   * 返回可编辑参数描述：
   *   { key, label, unit, min, max, step, type, slider?, options?, hint? }
   * type: 'number' | 'bool' | 'select'
   */
  getProps() { return []; }

  /* ---------------- 序列化 ---------------- */

  serialize() {
    const o = {
      id: this.id,
      type: this.type,
      x: Math.round(this.x),
      y: Math.round(this.y),
      state: this.state,
      burnedOut: this.burnedOut
    };
    for (const k of this.constructor.PARAM_KEYS) {
      o[k] = this[k];
    }
    return o;
  }

  restore(data) {
    if (typeof data.x === 'number') this.x = data.x;
    if (typeof data.y === 'number') this.y = data.y;
    this.state = data.state ?? 'normal';
    this.burnedOut = !!data.burnedOut;
    for (const k of this.constructor.PARAM_KEYS) {
      if (data[k] !== undefined) this[k] = data[k];
    }
  }

  /* ---------------- 通用行为 ---------------- */

  /** 每步仿真后的状态更新（默认无操作） */
  update(dt, model) {   // eslint-disable-line no-unused-vars
  }

  /** 标记为过载 */
  markOverload() {
    if (this.state === 'normal') this.state = 'overload';
  }

  /** 清除过载（含冷却计时） */
  coolOverload(dt) {
    this.overloadTime = Math.max(0, this.overloadTime - dt * 2);
    if (this.overloadTime < 0.05 && this.state === 'overload') {
      this.state = 'normal';
    }
  }

  /** 烧毁 */
  burn() {
    this.burnedOut = true;
    this.state = 'burned';
    this.I = 0; this.V = 0; this.P = 0;
  }
}