/**
 * SchematicRenderer.js
 * 标准电路原理图渲染器（SVG）。
 *
 * 设计目标：
 *   - 与实验台完全独立：这是"教科书标准电路图"，不是实验台截图
 *   - 使用标准电路符号（电池 / 电阻 / 电流表 / 电压表 / 开关 / 滑动变阻器 / 电容 / 灯泡）
 *   - 导线走正交路径
 *   - 元件自动带标签（Rx / A / V / E / R）
 *   - 支持错误位置高亮（highlight(id)）
 *   - 支持点击回调（用于"点击原理图 → 高亮实验台对应器件"）
 *
 * 描述格式：
 *   {
 *     width:  560,
 *     height: 300,
 *     elements: [
 *       { id, type, x, y, rot:0|90, label, value, hl:boolean }
 *     ],
 *     wires: [
 *       { id, pts: [{x,y}, ...], hl:boolean }
 *     ]
 *   }
 */

const NS = 'http://www.w3.org/2000/svg';
/* ------------------------------------------------------------------
   自动正交化 —— 把折线里所有斜段拆成"水平+垂直"两段
   ------------------------------------------------------------------ */
function orthogonalize(pts) {
  if (!pts || pts.length < 2) return pts || [];
  const EPS = 0.5;
  const out = [{ x: pts[0].x, y: pts[0].y }];
  for (let i = 1; i < pts.length; i++) {
    const a = out[out.length - 1];
    const b = pts[i];
    const sameX = Math.abs(a.x - b.x) < EPS;
    const sameY = Math.abs(a.y - b.y) < EPS;
    if (sameX || sameY) {
      out.push({ x: b.x, y: b.y });
    } else {
      // 先水平走到 b.x，再垂直走到 b.y
      out.push({ x: b.x, y: a.y });
      out.push({ x: b.x, y: b.y });
    }
  }
  return out;
}
/* ------------------------------------------------------------------
   底层：SVG 元素构建
   ------------------------------------------------------------------ */

function el(tag, attrs = {}, children = []) {
  const e = document.createElementNS(NS, tag);
  for (const k in attrs) {
    if (attrs[k] === undefined || attrs[k] === null) continue;
    e.setAttribute(k, String(attrs[k]));
  }
  for (const c of [].concat(children)) {
    if (c) e.appendChild(c);
  }
  return e;
}

function txt(s, attrs = {}) {
  const e = el('text', {
    'font-family': '"PingFang SC","Microsoft YaHei",system-ui,sans-serif',
    'font-size': 11,
    ...attrs
  });
  e.textContent = s ?? '';
  return e;
}

/* ------------------------------------------------------------------
   端子定义（本地坐标，rot=0）
   ------------------------------------------------------------------ */

const TERMINALS = {
  battery:   [ { dx: -30, dy: 0 }, { dx:  30, dy: 0 } ],
  resistor:  [ { dx: -30, dy: 0 }, { dx:  30, dy: 0 } ],
  resistanceBox: [ { dx: -30, dy: 0 }, { dx:  30, dy: 0 } ],
  rheostat:  [ { dx: -34, dy: 0 }, { dx:  34, dy: 0 }, { dx: 0, dy: -22 } ],
  bulb:      [ { dx: -26, dy: 0 }, { dx:  26, dy: 0 } ],
  capacitor: [ { dx: -22, dy: 0 }, { dx:  22, dy: 0 } ],
  switch:    [ { dx: -30, dy: 0 }, { dx:  30, dy: 0 } ],
  spdt:      [ { dx: -32, dy: 0 }, { dx:  28, dy: -22 }, { dx: 28, dy: 22 } ],
  ammeter:   [ { dx: -26, dy: 0 }, { dx:  26, dy: 0 } ],
  voltmeter: [ { dx: -26, dy: 0 }, { dx:  26, dy: 0 } ]
};

/* 元件的本地包围盒（用于自动对齐和检测） */
const BBOX = {
  battery:   { w: 60, h: 28 },
  resistor:  { w: 60, h: 22 },
  resistanceBox: { w: 60, h: 26 },
  rheostat:  { w: 68, h: 24 },
  bulb:      { w: 52, h: 52 },
  capacitor: { w: 44, h: 30 },
  switch:    { w: 60, h: 24 },
  spdt:      { w: 64, h: 52 },
  ammeter:   { w: 52, h: 52 },
  voltmeter: { w: 52, h: 52 }
};

/* ------------------------------------------------------------------
   主渲染器
   ------------------------------------------------------------------ */

export class SchematicRenderer {

  /**
   * @param {HTMLElement} container  承载 SVG 的容器
   */
  constructor(container) {
    this.container = container;
    this.svg = null;
    this.schematic = null;
    this.onElementClick = null;
  }

  /**
   * 渲染原理图
   * @param {object} schematic
   * @param {object} [opts] { theme:'light'|'dark', interactive:boolean }
   */
    render(schematic, opts = {}) {
    if (!this.container) return;
    this.schematic = schematic;
    this.container.innerHTML = '';

    const W = schematic.width  || 560;
    const H = schematic.height || 300;

    const svg = el('svg', {
      viewBox: `0 0 ${W} ${H}`,
      xmlns: NS,
      'shape-rendering': 'geometricPrecision',
      style: 'display:block;width:100%;height:auto;'
    });

    /* defs */
    const defs = el('defs');
    defs.appendChild(this._arrowMarker());
    svg.appendChild(defs);

    /* 背景 */
    svg.appendChild(el('rect', {
      x: 0, y: 0, width: W, height: H,
      fill: '#f8fafc', rx: 6
    }));

    /* 网格 */
    const gridG = el('g', { opacity: 0.5 });
    for (let x = 20; x < W; x += 20) {
      gridG.appendChild(el('line', {
        x1: x, y1: 0, x2: x, y2: H,
        stroke: 'rgba(148,163,184,0.14)', 'stroke-width': 1
      }));
    }
    for (let y = 20; y < H; y += 20) {
      gridG.appendChild(el('line', {
        x1: 0, y1: y, x2: W, y2: y,
        stroke: 'rgba(148,163,184,0.14)', 'stroke-width': 1
      }));
    }
    svg.appendChild(gridG);

    /* ---- 预处理所有导线：正交化 ---- */
    const processedWires = (schematic.wires || []).map(w => ({
      ...w,
      _pts: orthogonalize(w.pts || [])
    }));

    /* ---- 收集所有水平/垂直段 ---- */
    const allSegs = [];
    processedWires.forEach((w, wi) => {
      for (let i = 1; i < w._pts.length; i++) {
        const a = w._pts[i - 1];
        const b = w._pts[i];
        const isH = Math.abs(a.y - b.y) < 0.5;
        const isV = Math.abs(a.x - b.x) < 0.5;
        if (isH || isV) allSegs.push({ wi, si: i - 1, a, b, isH, isV });
      }
    });

    /* ---- 计算所有交叉点：水平线在交叉处画跳跃 ---- */
    const JUMP_R = 5;
    const jumps = new Map();   // "wi:si" -> [{x,y}]（仅水平段）

    for (let i = 0; i < allSegs.length; i++) {
      for (let j = i + 1; j < allSegs.length; j++) {
        const s1 = allSegs[i];
        const s2 = allSegs[j];
        if (s1.wi === s2.wi) continue;   // 同一条导线内部不算

        let h, v;
        if (s1.isH && s2.isV) { h = s1; v = s2; }
        else if (s1.isV && s2.isH) { h = s2; v = s1; }
        else continue;

        const x = v.a.x;
        const y = h.a.y;

        // 严格位于两段"内部"（不是端点）才算交叉
        const inH = Math.min(h.a.x, h.b.x) + 1 < x &&
                    x < Math.max(h.a.x, h.b.x) - 1;
        const inV = Math.min(v.a.y, v.b.y) + 1 < y &&
                    y < Math.max(v.a.y, v.b.y) - 1;

        if (inH && inV) {
          const key = `${h.wi}:${h.si}`;
          if (!jumps.has(key)) jumps.set(key, []);
          jumps.get(key).push({ x, y });
        }
      }
    }

    /* ---- 导线层 ---- */
    const wireG = el('g', { 'data-layer': 'wires' });
    for (let wi = 0; wi < processedWires.length; wi++) {
      wireG.appendChild(this._renderWire(processedWires[wi], wi, jumps));
    }
    svg.appendChild(wireG);

    /* ---- 元件层 ---- */
    const compG = el('g', { 'data-layer': 'components' });
    for (const e of (schematic.elements || [])) {
      compG.appendChild(this._renderElement(e, opts));
    }
    svg.appendChild(compG);

    this.svg = svg;
    this.container.appendChild(svg);
  }

  _arrowMarker() {
    const marker = el('marker', {
      id: 'sch-arrow',
      viewBox: '0 0 10 10',
      refX: 8, refY: 5,
      markerWidth: 6, markerHeight: 6,
      orient: 'auto-start-reverse'
    });
    marker.appendChild(el('path', {
      d: 'M 0 0 L 10 5 L 0 10 z',
      fill: '#0f172a'
    }));
    return marker;
  }

  /* ---------------- 导线 ---------------- */

  _renderWire(w, wi, jumps) {
    const pts = w._pts || orthogonalize(w.pts || []);
    if (pts.length < 2) return el('g');

    const JUMP_R = 5;
    let d = `M ${pts[0].x} ${pts[0].y}`;

    for (let i = 1; i < pts.length; i++) {
      const a = pts[i - 1];
      const b = pts[i];
      const isH = Math.abs(a.y - b.y) < 0.5;

      if (isH) {
        const key = `${wi}:${i - 1}`;
        const js = jumps && jumps.get(key);

        if (js && js.length) {
          const dir = Math.sign(b.x - a.x);
          js.sort((p, q) => dir > 0 ? p.x - q.x : q.x - p.x);

          let curX = a.x;
          const y = a.y;

          for (const j of js) {
            if (dir > 0) {
              if (j.x - JUMP_R > curX + 1 && j.x + JUMP_R < b.x - 1) {
                d += ` L ${j.x - JUMP_R} ${y}`;
                d += ` A ${JUMP_R} ${JUMP_R} 0 0 1 ${j.x + JUMP_R} ${y}`;
                curX = j.x + JUMP_R;
              }
            } else {
              if (j.x + JUMP_R < curX - 1 && j.x - JUMP_R > b.x + 1) {
                d += ` L ${j.x + JUMP_R} ${y}`;
                d += ` A ${JUMP_R} ${JUMP_R} 0 0 0 ${j.x - JUMP_R} ${y}`;
                curX = j.x - JUMP_R;
              }
            }
          }
          d += ` L ${b.x} ${b.y}`;
        } else {
          d += ` L ${b.x} ${b.y}`;
        }
      } else {
        d += ` L ${b.x} ${b.y}`;
      }
    }

    const g = el('g', { 'data-wire-id': w.id || '' });
    g.appendChild(el('path', {
      d,
      fill: 'none',
      stroke: w.hl ? '#ef4444' : '#0f172a',
      'stroke-width': w.hl ? 3 : 2,
      'stroke-linejoin': 'round',
      'stroke-linecap': 'round'
    }));
    return g;
  }

  /* ---------------- 元件 ---------------- */

  _renderElement(e, opts) {
    const type = e.type;
    const rot = e.rot || 0;

    // 世界坐标变换：先本地绘制，再平移到 (x,y)
    // 对于 rot=90，把本地 (dx,dy) 映射到 (x - dy, y + dx)
    const g = el('g', {
      'data-el-id': e.id,
      style: 'cursor:pointer;'
    });

    // 高亮边框
    if (e.hl) {
      const bb = BBOX[type] || { w: 40, h: 40 };
      const pad = 10;
      let rx, ry, rw, rh;
      if (rot === 0) {
        rx = e.x - bb.w / 2 - pad;
        ry = e.y - bb.h / 2 - pad;
        rw = bb.w + pad * 2;
        rh = bb.h + pad * 2;
      } else {
        rx = e.x - bb.h / 2 - pad;
        ry = e.y - bb.w / 2 - pad;
        rw = bb.h + pad * 2;
        rh = bb.w + pad * 2;
      }
      g.appendChild(el('rect', {
        x: rx, y: ry, width: rw, height: rh,
        rx: 8,
        fill: 'rgba(239,68,68,0.08)',
        stroke: '#ef4444',
        'stroke-width': 1.6,
        'stroke-dasharray': '5 4'
      }));
    }

    // 内部绘制组（应用旋转）
    const inner = el('g', {
      transform: rot === 90
        ? `translate(${e.x} ${e.y}) rotate(90)`
        : `translate(${e.x} ${e.y})`
    });

    switch (type) {
      case 'battery':   this._symBattery(inner, e); break;
      case 'resistor':  this._symResistor(inner, e); break;
      case 'resistanceBox': this._symResistanceBox(inner, e); break;
      case 'rheostat':  this._symRheostat(inner, e); break;
      case 'bulb':      this._symBulb(inner, e); break;
      case 'capacitor': this._symCapacitor(inner, e); break;
      case 'switch':    this._symSwitch(inner, e); break;
      case 'spdt':      this._symSPDT(inner, e); break;
      case 'ammeter':   this._symMeter(inner, e, 'A'); break;
      case 'voltmeter': this._symMeter(inner, e, 'V'); break;
      default:          this._symGeneric(inner, e); break;
    }

    g.appendChild(inner);

    // 标签（始终水平）
    this._renderLabel(g, e, rot);

    // 交互
    if (opts.interactive !== false) {
      g.addEventListener('click', () => {
        this.onElementClick?.(e.id, e);
      });
    }

    return g;
  }

  _renderLabel(g, e, rot) {
    const bb = BBOX[e.type] || { w: 40, h: 20 };

    // 标签位置：元件外侧
    let lx = e.x;
    let ly = e.y;

    if (rot === 0) {
      ly = e.y - bb.h / 2 - 8;
    } else {
      lx = e.x + bb.h / 2 + 6;
      ly = e.y;
      // 竖直元件：文字仍在元件右侧
    }

    if (e.label) {
      g.appendChild(txt(e.label, {
        x: lx, y: ly,
        'text-anchor': 'middle',
        'font-weight': 700,
        fill: '#0f172a',
        'font-size': 12
      }));
    }

    if (e.value) {
      g.appendChild(txt(e.value, {
        x: lx, y: ly + (rot === 0 ? 14 : 15),
        'text-anchor': 'middle',
        fill: '#475569',
        'font-size': 10.5,
        'font-style': 'italic'
      }));
    }
  }

  /* ---------------- 标准符号 ---------------- */

  _symBattery(g, e) {
    // 长线 = 正极，短线 = 负极
    g.appendChild(el('line', {
      x1: -30, y1: 0, x2: -4, y2: 0,
      stroke: '#0f172a', 'stroke-width': 2
    }));
    g.appendChild(el('line', {
      x1: 30, y1: 0, x2: 4, y2: 0,
      stroke: '#0f172a', 'stroke-width': 2
    }));

    g.appendChild(el('line', {
      x1: -4, y1: -14, x2: -4, y2: 14,
      stroke: '#0f172a', 'stroke-width': 2.4
    }));
    g.appendChild(el('line', {
      x1:  4, y1:  -8, x2:  4, y2:  8,
      stroke: '#0f172a', 'stroke-width': 3.4
    }));

    // 正极 +
    g.appendChild(txt('+', {
      x: -12, y: -14,
      'text-anchor': 'middle',
      fill: '#0f172a', 'font-weight': 700, 'font-size': 11
    }));
  }

  _symResistor(g, e) {
    g.appendChild(el('line', {
      x1: -30, y1: 0, x2: -18, y2: 0,
      stroke: '#0f172a', 'stroke-width': 2
    }));
    g.appendChild(el('line', {
      x1: 30, y1: 0, x2: 18, y2: 0,
      stroke: '#0f172a', 'stroke-width': 2
    }));
    g.appendChild(el('rect', {
      x: -18, y: -10, width: 36, height: 20,
      fill: '#ffffff',
      stroke: '#0f172a', 'stroke-width': 2
    }));
  }

  _symResistanceBox(g, e) {
    /* 连接线 */
    g.appendChild(el('line', {
      x1: -30, y1: 0, x2: -18, y2: 0,
      stroke: '#0f172a', 'stroke-width': 2
    }));
    g.appendChild(el('line', {
      x1: 30, y1: 0, x2: 18, y2: 0,
      stroke: '#0f172a', 'stroke-width': 2
    }));

    /* 主体矩形 */
    g.appendChild(el('rect', {
      x: -18, y: -12, width: 36, height: 24,
      fill: '#ffffff',
      stroke: '#0f172a', 'stroke-width': 2
    }));

    /* 标准"可调电阻"符号：对角箭头 */
    g.appendChild(el('line', {
      x1: -12, y1: 8, x2: 12, y2: -8,
      stroke: '#0f172a', 'stroke-width': 1.6
    }));

    /* 箭头尖 */
    const head = el('path', {
      d: 'M 8 -8 L 12 -8 L 12 -4 Z',
      fill: '#0f172a'
    });
    g.appendChild(head);
  }
  
  _symRheostat(g, e) {
    /* 左右连接线 */
    g.appendChild(el('line', {
      x1: -34, y1: 0, x2: -20, y2: 0,
      stroke: '#0f172a', 'stroke-width': 2
    }));
    g.appendChild(el('line', {
      x1: 34, y1: 0, x2: 20, y2: 0,
      stroke: '#0f172a', 'stroke-width': 2
    }));

    /* 矩形电阻体 */
    g.appendChild(el('rect', {
      x: -20, y: -10, width: 40, height: 20,
      fill: '#ffffff',
      stroke: '#0f172a', 'stroke-width': 2
    }));

    /* 电阻体内部竖线纹理 */
    for (let i = -15; i <= 15; i += 5) {
      g.appendChild(el('line', {
        x1: i, y1: -8, x2: i, y2: 8,
        stroke: '#0f172a', 'stroke-width': 0.6, opacity: 0.35
      }));
    }

    /* 从端子到箭头尾部的短连接线（9 像素，视觉上是箭头的一部分） */
    g.appendChild(el('line', {
      x1: 0, y1: -22, x2: 0, y2: -13,
      stroke: '#0f172a', 'stroke-width': 2
    }));

    /* 实心大三角箭头，指向电阻体 */
    g.appendChild(el('path', {
      d: 'M -5 -13 L 5 -13 L 0 -3 Z',
      fill: '#0f172a'
    }));

    /* 滑片端子：空心圆（唯一的"接线柱"，供用户从外部拉导线） */
    g.appendChild(el('circle', {
      cx: 0, cy: -22, r: 3,
      fill: '#ffffff',
      stroke: '#0f172a', 'stroke-width': 2
    }));
  }

  _symBulb(g, e) {
    g.appendChild(el('line', {
      x1: -26, y1: 0, x2: -18, y2: 0,
      stroke: '#0f172a', 'stroke-width': 2
    }));
    g.appendChild(el('line', {
      x1: 26, y1: 0, x2: 18, y2: 0,
      stroke: '#0f172a', 'stroke-width': 2
    }));
    g.appendChild(el('circle', {
      cx: 0, cy: 0, r: 18,
      fill: '#ffffff',
      stroke: '#0f172a', 'stroke-width': 2
    }));
    // 内部 X
    g.appendChild(el('line', {
      x1: -12.7, y1: -12.7, x2: 12.7, y2: 12.7,
      stroke: '#0f172a', 'stroke-width': 2
    }));
    g.appendChild(el('line', {
      x1: 12.7, y1: -12.7, x2: -12.7, y2: 12.7,
      stroke: '#0f172a', 'stroke-width': 2
    }));
  }

  _symCapacitor(g, e) {
    g.appendChild(el('line', {
      x1: -22, y1: 0, x2: -4, y2: 0,
      stroke: '#0f172a', 'stroke-width': 2
    }));
    g.appendChild(el('line', {
      x1: 22, y1: 0, x2: 4, y2: 0,
      stroke: '#0f172a', 'stroke-width': 2
    }));
    g.appendChild(el('line', {
      x1: -4, y1: -14, x2: -4, y2: 14,
      stroke: '#0f172a', 'stroke-width': 2.4
    }));
    g.appendChild(el('line', {
      x1:  4, y1: -14, x2:  4, y2: 14,
      stroke: '#0f172a', 'stroke-width': 2.4
    }));
  }

  _symSwitch(g, e) {
    g.appendChild(el('line', {
      x1: -30, y1: 0, x2: -22, y2: 0,
      stroke: '#0f172a', 'stroke-width': 2
    }));
    g.appendChild(el('line', {
      x1: 30, y1: 0, x2: 22, y2: 0,
      stroke: '#0f172a', 'stroke-width': 2
    }));
    // 左触点
    g.appendChild(el('circle', {
      cx: -22, cy: 0, r: 2.6,
      fill: '#0f172a'
    }));
    // 右触点
    g.appendChild(el('circle', {
      cx: 22, cy: 0, r: 2.6,
      fill: '#0f172a'
    }));
    // 闸刀（斜线）
    g.appendChild(el('line', {
      x1: -22, y1: 0, x2: 18, y2: -18,
      stroke: '#0f172a', 'stroke-width': 2.4,
      'stroke-linecap': 'round'
    }));
  }

  _symSPDT(g, e) {
    g.appendChild(el('line', {
      x1: -32, y1: 0, x2: -18, y2: 0,
      stroke: '#0f172a', 'stroke-width': 2
    }));
    g.appendChild(el('line', {
      x1: 28, y1: -22, x2: 28, y2: -12,
      stroke: '#0f172a', 'stroke-width': 2
    }));
    g.appendChild(el('line', {
      x1: 28, y1:  22, x2: 28, y2:  12,
      stroke: '#0f172a', 'stroke-width': 2
    }));
    g.appendChild(el('circle', {
      cx: -18, cy: 0, r: 2.6, fill: '#0f172a'
    }));
    g.appendChild(el('circle', {
      cx: 28, cy: -12, r: 2.6, fill: '#0f172a'
    }));
    g.appendChild(el('circle', {
      cx: 28, cy:  12, r: 2.6, fill: '#0f172a'
    }));
    // 闸刀指向 A
    g.appendChild(el('line', {
      x1: -18, y1: 0, x2: 26, y2: -10,
      stroke: '#0f172a', 'stroke-width': 2.4,
      'stroke-linecap': 'round'
    }));
    g.appendChild(txt('A', {
      x: 40, y: -22 + 4, 'text-anchor': 'start',
      fill: '#0f172a', 'font-weight': 700, 'font-size': 11
    }));
    g.appendChild(txt('B', {
      x: 40, y: 22 + 4, 'text-anchor': 'start',
      fill: '#0f172a', 'font-weight': 700, 'font-size': 11
    }));
  }

  _symMeter(g, e, letter) {
    g.appendChild(el('line', {
      x1: -26, y1: 0, x2: -18, y2: 0,
      stroke: '#0f172a', 'stroke-width': 2
    }));
    g.appendChild(el('line', {
      x1: 26, y1: 0, x2: 18, y2: 0,
      stroke: '#0f172a', 'stroke-width': 2
    }));
    g.appendChild(el('circle', {
      cx: 0, cy: 0, r: 18,
      fill: '#ffffff',
      stroke: '#0f172a', 'stroke-width': 2
    }));
    g.appendChild(txt(letter, {
      x: 0, y: 5,
      'text-anchor': 'middle',
      'font-family': '"Times New Roman",serif',
      'font-weight': 700,
      'font-size': 18,
      fill: '#0f172a'
    }));
  }

  _symGeneric(g, e) {
    g.appendChild(el('rect', {
      x: -20, y: -12, width: 40, height: 24,
      fill: '#ffffff', stroke: '#0f172a', 'stroke-width': 2
    }));
  }

  /* ---------------- 高亮 ---------------- */

  /**
   * 高亮指定元件 id 列表
   * @param {string[]} ids
   */
  highlight(ids = []) {
    if (!this.svg) return;
    const set = new Set(ids);

    for (const g of this.svg.querySelectorAll('[data-el-id]')) {
      const id = g.getAttribute('data-el-id');
      g.style.filter = set.has(id) ? 'drop-shadow(0 0 6px rgba(239,68,68,0.85))' : '';
    }
    for (const g of this.svg.querySelectorAll('[data-wire-id]')) {
      const id = g.getAttribute('data-wire-id');
      const p = g.querySelector('path');
      if (!p) continue;
      if (set.has(id)) {
        p.setAttribute('stroke', '#ef4444');
        p.setAttribute('stroke-width', '3');
      } else {
        p.setAttribute('stroke', '#0f172a');
        p.setAttribute('stroke-width', '2');
      }
    }
  }

  clearHighlight() {
    this.highlight([]);
  }

  /* ---------------- 工具 ---------------- */

  /**
   * 计算某元件某端子的世界坐标（供外部布局用）
   */
  static terminalPos(e, ti) {
    const list = TERMINALS[e.type];
    if (!list || !list[ti]) return { x: e.x, y: e.y };
    const t = list[ti];
    const rot = e.rot || 0;
    if (rot === 90) {
      return { x: e.x - t.dy, y: e.y + t.dx };
    }
    return { x: e.x + t.dx, y: e.y + t.dy };
  }

  static TERMINALS = TERMINALS;
  static BBOX = BBOX;
}