/**
 * AmmeterResistance.js
 * 实验 7：安阻法测电阻（电阻箱 + SPDT）
 *
 * 电路：
 *   E+ ── S ── 左节点 P ──┬──[Rx]── 右节点 Qx ── A 掷 ─┐
 *                          │                            ├─[K]──[A表]── E-
 *                          └──[R0 电阻箱]── 右节点 Q0 ─ B 掷 ─┘
 *
 * 原理：
 *   Rx 与 R0 并联 → 两端电压 U 相同
 *   U = Ix·Rx = I0·R0
 *   →  Rx = R0 · I0 / Ix
 */

import { register } from './ExperimentRegistry.js';
import { ExperimentValidator } from './ExperimentValidator.js';
import { SchematicRenderer } from '../rendering/SchematicRenderer.js';

/* ------------------------------------------------------------------
   标准电路图
   ------------------------------------------------------------------ */

function buildSchematic() {
  const T = SchematicRenderer.terminalPos;

  const E  = { id: 'sch-E',  type: 'battery',       x: 100, y: 220, rot: 90, label: 'E' };
  const S  = { id: 'sch-S',  type: 'switch',        x: 200, y:  80, rot: 0,  label: 'S' };
  const Rx = { id: 'sch-Rx', type: 'resistor',      x: 400, y: 120, rot: 0,  label: 'Rx', value: '?' };
  const R0 = { id: 'sch-R0', type: 'resistanceBox', x: 400, y: 240, rot: 0,  label: 'R0', value: '电阻箱' };
  const K  = { id: 'sch-K',  type: 'spdt',          x: 540, y: 180, rot: 0,  label: 'K' };
  const A  = { id: 'sch-A',  type: 'ammeter',       x: 534, y: 320, rot: 0,  label: 'A' };

  const els = [E, S, Rx, R0, K, A];
  const P = (e, ti) => T(e, ti);
  const w = (id, pts) => ({ id, pts });

  const wires = [
    /* E+ → S → 左公共节点 P */
    w('w1', [ P(E,0), { x: 100, y: 80 }, P(S,0) ]),
    w('w2', [ P(S,1), { x: 280, y: 80 } ]),

    /* P 竖直主干，接 Rx / R0 左端 */
    w('w3', [ { x: 280, y: 80 }, { x: 280, y: 240 }, P(R0,0) ]),
    w('w4', [ { x: 280, y: 120 }, P(Rx,0) ]),

    /* Rx 右端 → K 的 A 掷 */
    w('w5', [ P(Rx,1), { x: 568, y: 120 }, P(K,1) ]),

    /* R0 右端 → K 的 B 掷 */
    w('w6', [ P(R0,1), { x: 568, y: 240 }, P(K,2) ]),

    /* K 公共端 → 电流表 */
    w('w7', [ P(K,0), P(A,0) ]),

    /* 电流表 → E- */
    w('w8', [ P(A,1), { x: 560, y: 380 },
              { x: 100, y: 380 }, P(E,1) ])
  ];

  return { width: 660, height: 440, elements: els, wires };
}

const FIELDS = [
  { key: 'n',  label: '次数',                    digits: 0 },
  { key: 'Ix', label: 'Ix',           unit: 'A', digits: 5 },
  { key: 'I0', label: 'I0',           unit: 'A', digits: 5 },
  { key: 'R0', label: 'R0',           unit: 'Ω', digits: 2 },
  { key: 'Rx', label: 'Rx = R0·I0/Ix',unit: 'Ω', digits: 4 }
];

const AmmeterResistance = {
  id: 'ammeter-method',
  name: '安阻法测电阻',
  category: '实验设计',

  purpose:
    '在只有电流表和电阻箱的条件下测量未知电阻 Rx；' +
    '理解并联电路电压相同的特点；' +
    '掌握用电流比例法求电阻的方法。',

  principle:
    'Rx 与电阻箱 R0 并联，两端电压 U 相同。' +
    'U = Ix·Rx = I0·R0。' +
    '两式相除得 Rx / R0 = I0 / Ix，' +
    '因此 Rx = R0 · I0 / Ix。' +
    '实验中用单刀双掷开关 K 切换电流表测量支路。',

  equipment: [
    { type: 'battery',         count: 1, label: '电源 E' },
    { type: 'switch',          count: 1, label: '开关 S' },
    { type: 'resistanceBox',   count: 1, label: '电阻箱 R0' },
    { type: 'unknownResistor', count: 1, label: '待测电阻 Rx' },
    { type: 'spdt',            count: 1, label: '单刀双掷开关 K' },
    { type: 'ammeter',         count: 1, label: '电流表 A' }
  ],

  schematic: buildSchematic(),

  defaultSetup: [
    { type: 'battery',         x: 0.18, y: 0.35 },
    { type: 'switch',          x: 0.40, y: 0.20 },
    { type: 'unknownResistor', x: 0.55, y: 0.20 },
    { type: 'resistanceBox',   x: 0.55, y: 0.65 },
    { type: 'spdt',            x: 0.75, y: 0.42 },
    { type: 'ammeter',         x: 0.85, y: 0.78 }
  ],

  fields: FIELDS,

  /* ---------- 校验 ---------- */
  validate({ topo }) {
    const checks = [];
    checks.push(ExperimentValidator.checkCount(topo, 'battery',         1, '电源'));
    checks.push(ExperimentValidator.checkCount(topo, 'switch',          1, '开关'));
    checks.push(ExperimentValidator.checkCount(topo, 'resistanceBox',   1, '电阻箱 R0'));
    checks.push(ExperimentValidator.checkCount(topo, 'unknownResistor', 1, '待测电阻 Rx'));
    checks.push(ExperimentValidator.checkCount(topo, 'spdt',            1, '单刀双掷开关'));
    checks.push(ExperimentValidator.checkCount(topo, 'ammeter',         1, '电流表'));

    const Rx = topo.comps.find(c => c.type === 'unknownResistor');
    const R0 = topo.comps.find(c => c.type === 'resistanceBox');
    if (Rx && R0) {
      const ok = ExperimentValidator.isParallel(topo, Rx, R0);
      checks.push({
        name: 'Rx 与 R0 并联',
        ok,
        msg: ok ? '待测电阻与电阻箱已并联' : 'Rx 与 R0 应并联连接'
      });
    }

    return { checks };
  },

  /* ---------- 数据采集 ---------- */
  makeRow(ctx) {
    const { graph, index, extra } = ctx;

    const Rx  = graph.allComponents.find(c => c.type === 'unknownResistor' && !c.burnedOut);
    const R0c = graph.allComponents.find(c => c.type === 'resistanceBox'   && !c.burnedOut);
    const A   = graph.allComponents.find(c => c.type === 'ammeter'         && !c.burnedOut);
    const K   = graph.allComponents.find(c => c.type === 'spdt'            && !c.burnedOut);

    if (!Rx || !R0c || !A || !K) return null;

    const Imeas = Math.abs(A.I);
    const isRx  = (K.position === 0);

    const Ix = isRx ? Imeas : (extra?.lastIx ?? 0);
    const I0 = isRx ? (extra?.lastI0 ?? 0) : Imeas;

    if (extra) {
      if (isRx) extra.lastIx = Imeas;
      else      extra.lastI0 = Imeas;
    }

    if (Ix < 1e-6 || I0 < 1e-6) return null;

    const R0 = R0c.R;
    const RxCalc = R0 * I0 / Ix;

    return {
      n:  index + 1,
      Ix: +Ix.toFixed(6),
      I0: +I0.toFixed(6),
      R0: +R0.toFixed(3),
      Rx: +RxCalc.toFixed(5)
    };
  },

  collectLiveData({ graph }) {
    const items = [];

    const R0c = graph.allComponents.find(c => c.type === 'resistanceBox' && !c.burnedOut);
    if (R0c) items.push({
      k: '电阻箱 R0',
      v: `${R0c.R.toFixed(0)} Ω`,
      cls: 'warn'
    });

    const A = graph.allComponents.find(c => c.type === 'ammeter' && !c.burnedOut);
    if (A) items.push({
      k: '电流表读数',
      v: `${Math.abs(A.I).toFixed(5)} A`,
      cls: A.overRange ? 'danger' : 'acc'
    });

    const K = graph.allComponents.find(c => c.type === 'spdt' && !c.burnedOut);
    if (K) items.push({
      k: '当前测量支路',
      v: K.position === 0 ? 'Rx 支路' : 'R0 支路',
      cls: 'acc'
    });

    return items;
  },

  charts: [
    {
      key: 'rx',
      title: 'Rx 分布图',
      xField: 'n',
      yField: 'Rx',
      xLabel: '次数 n',
      yLabel: 'Rx / Ω',
      mode: 'both',
      fit: false
    }
  ],

  interpret() {
    return {
      title: '实验结论',
      lines: [
        '原理：并联电路电压相同，Rx = R0 · I0 / Ix。',
        '改变电阻箱示数 R0，可得到多组数据。',
        'Rx 的真实值不会直接显示，需要通过数据自行计算。'
      ]
    };
  }
};

register(AmmeterResistance);

export default AmmeterResistance;