/**
 * SPDT.js —— 单刀双掷开关
 * 端子 0：公共端 端子 1：掷 A  端子 2：掷 B
 * position: 0 → 公共端接 A；1 → 公共端接 B
 */

import { Component, nextComponentId } from './Component.js';

export class SPDT extends Component {
  static type = 'spdt';
  static displayName = '单刀双掷开关';
  static icon = '⇋';
  static category = 'control';
  static PARAM_KEYS = ['position'];

  constructor(id) {
    super(id ?? nextComponentId('spdt'));
    this.terminals = [
      { dx: -46, dy: 0 },
      { dx:  40, dy: -30 },
      { dx:  40, dy:  30 }
    ];
    this.position = 0;   // 0 或 1
  }

  netlist(model) {
    if (this.burnedOut) return [{ kind: 'open' }];
    const R = Math.max(model.numeric.switchR, 1e-6);
    const out = [];
    out.push(this.position === 0
      ? { kind: 'resistor', a: 0, b: 1, R }
      : { kind: 'open' });
    out.push(this.position === 1
      ? { kind: 'resistor', a: 0, b: 2, R }
      : { kind: 'open' });
    return out;
  }

  getProps() {
    return [
      {
        key: 'position', label: '触头位置', type: 'select',
        options: [
          { value: 0, label: '公共端 → A' },
          { value: 1, label: '公共端 → B' }
        ]
      }
    ];
  }

  toggle() { this.position = this.position === 0 ? 1 : 0; }

  update(dt) { this.coolOverload(dt); }
}