/**
 * DataRecorder.js
 * 统一数据记录器：管理多个 Dataset，提供给 UI / ChartManager 使用。
 */

import { Dataset } from './Dataset.js';

export class DataRecorder {
  constructor() {
    /** @type {Map<string, Dataset>} */
    this.datasets = new Map();
    this.activeName = null;
    this._listeners = new Set();
  }

  on(fn) {
    this._listeners.add(fn);
    return () => this._listeners.delete(fn);
  }

  _emit() {
    for (const fn of this._listeners) {
      try { fn(this); } catch (e) { console.error(e); }
    }
  }

  /**
   * 创建或替换数据集
   * @param {string} name
   * @param {Array<{key,label,unit?,digits?}>} fields
   */
  create(name, fields) {
    const ds = new Dataset(name, fields);
    ds.on(() => this._emit());
    this.datasets.set(name, ds);
    if (!this.activeName) this.activeName = name;
    this._emit();
    return ds;
  }

  get(name) {
    return this.datasets.get(name) || null;
  }

  get active() {
    return this.activeName ? this.datasets.get(this.activeName) : null;
  }

  use(name) {
    if (this.datasets.has(name)) {
      this.activeName = name;
      this._emit();
    }
  }

  remove(name) {
    if (!this.datasets.has(name)) return false;
    this.datasets.delete(name);
    if (this.activeName === name) {
      this.activeName = this.datasets.size ? [...this.datasets.keys()][0] : null;
    }
    this._emit();
    return true;
  }

  clearAll() {
    for (const ds of this.datasets.values()) ds.clear();
    this._emit();
  }

  /**
   * 快捷记录到当前激活数据集
   * @param {object} row
   */
  record(row) {
    const ds = this.active;
    if (!ds) return null;
    return ds.add(row);
  }

  /**
   * 自动采样（用于电容器这类连续信号）
   * @param {number} now   当前仿真时间
   * @param {number} interval
   * @param {Function} sampler  () => row | null
   * @returns {number|null}  新行的索引
   */
  autoSample(now, interval, sampler) {
    if (!this._lastSampleAt) this._lastSampleAt = -Infinity;
    if (now - this._lastSampleAt < interval) return null;
    this._lastSampleAt = now;
    const row = sampler();
    if (!row) return null;
    return this.record(row);
  }

  resetAutoSample() {
    this._lastSampleAt = -Infinity;
  }
}